            $alc = self::v04Allocation($N, $cls);
            $check($id, 'mode_status',      $cls['mode_status'],      $st);
            $check($id, 'allocation_mode',  $cls['allocation_mode'],  $am);
            $check($id, 'S0',               $cls['S0'],               $s0);
