        $check('B-T17', '公開一致のみ加点', $m17['加点対象'], [2]);
        $check('B-T17', '内部採点のみ一致は加点しない', $m17['内部採点のみ一致'], [4]);

        // T18 異なるsnapshot_hashを両AIが返す → 統合しない
        $check('B-T18', 'UNDETERMINED',
