    // ── Block A: 直近走データ取得・プロンプト付加（① ⑩ 両AI対応）──────────────
    // 仕様:「各馬の直近5走以上（取得可能なら10走）」→ 取得上限を10走にする
    // _getAiAnalysisPrompt 内で 1st AI (Claude) にも全頭の過去成績・能力適性データを渡す。
    // $race->dist/$race->course/$race->grade = 今走レース条件
    // $horses（冒頭で全カラム取得済み）から今走騎手を参照
    {
        $todayDist   = isset($race->dist)   ? (int)$race->dist   : null;
        $todayCourse = isset($race->course) ? $race->course       : null;
        $todayGrade  = isset($race->grade)  ? $race->grade        : null;

        $aHistoryText  = "

【各馬の直近成績（過去最大10走）と今走データ】
";
        $aHistoryText .= "能力・適性評価（100点満点・6項目）の根拠として利用してください。
";
        $aHistoryText .= "評価区分：A（80〜100点）B（70〜79点）C（60〜69点）D（59点以下）
";
        if ($todayCourse || $todayDist) {
            $aHistoryText .= '【今走条件】'
                . ($todayCourse ?? '')
                . ($todayDist   ? $todayDist . 'm' : '')
                . ($todayGrade  ? ' ' . $todayGrade : '')
                . "
";
        }
        $aHistoryText .= "
";

        foreach ($horses as $_aNum => $_aHorse) {
            $_aName   = $_aHorse->name;
            $_aJockey = $_aHorse->jockey ?? null; // 今走騎手

            $_aRows = DB::table('t_horse_odds_finder_shutsuba_history')
                ->where('name', $_aName)
                ->where('date', '<', $targetDate)   // 【20260924】仕様「対象レースより前の最大10走」・未来情報混入の防止
                ->orderBy('date', 'desc')
                ->limit(10)   // 仕様: 取得可能なら10走
                ->get(['date', 'basho', 'race_name', 'dist', 'condition', 'grade',
                       'finishing_position', 'num_horses', 'popularity', 'jockey',
                       'burden_weight', 'horse_weight', 'last_3f', 'fin_time_diff',
                       'corner_1', 'corner_2', 'corner_3', 'corner_4']);

            $aHistoryText .= "{$_aNum}番 {$_aName}";
            if ($_aJockey) {
                $aHistoryText .= "（今走騎手: {$_aJockey}）";
            }
            $aHistoryText .= "
";

            // @ANCHOR-20261013-V04-ABILITY-VERIFY  AIへ渡した過去走の件数を控える
            self::$v04PastRunCount[(int) $_aNum] = $_aRows->count();

            if ($_aRows->isEmpty()) {
                $aHistoryText .= "  （出走履歴なし）
";
            } else {
                $_aRowsArr = $_aRows->values()->all(); // 0-indexed array
                foreach ($_aRowsArr as $_ai => $_ar) {
                    // 通過順位
                    $_corners = array_filter([
                        $_ar->corner_1 ?? null,
                        $_ar->corner_2 ?? null,
                        $_ar->corner_3 ?? null,
                        $_ar->corner_4 ?? null,
                    ], fn($v) => $v !== null && $v !== '');
                    $_cornerStr = !empty($_corners) ? implode('-', $_corners) : '-';

                    // 距離変化（今走 vs 最新前走）
                    $_distDiff = '';
                    if ($_ai === 0 && $todayDist && $_ar->dist) {
                        $_dd = $todayDist - (int)$_ar->dist;
                        if ($_dd > 0) $_distDiff = "（今走+{$_dd}m延長）";
                        elseif ($_dd < 0) $_distDiff = "（今走{$_dd}m短縮）";
                    }

                    // 騎手継続・乗り替わり（今走 vs 最新前走）
                    $_jockeyChg = '';
                    if ($_ai === 0 && $_aJockey && ($_ar->jockey ?? null)) {
                        $_jockeyChg = ($_ar->jockey === $_aJockey)
                            ? '（騎手継続）'
                            : "（乗替:前走{$_ar->jockey}）";
                    }

                    // 休養日数（この走と直前走との日数差）
                    $_restStr = '';
                    if ($_ai === 0 && $targetDate && $_ar->date) {
                        $_d1 = new \DateTime($targetDate);
                        $_d2 = new \DateTime($_ar->date);
                        $_restStr = '休' . $_d1->diff($_d2)->days . '日';
                    } elseif ($_ai > 0 && isset($_aRowsArr[$_ai - 1]->date) && $_ar->date) {
                        $_d1 = new \DateTime($_aRowsArr[$_ai - 1]->date);
                        $_d2 = new \DateTime($_ar->date);
                        $_restStr = '休' . $_d1->diff($_d2)->days . '日';
                    }

                    $aHistoryText .= sprintf(
                        "  %s %s %s %s%s %s着/%s頭中 %s人気 通過:%s 上がり%s 着差%s 斤%s 馬体%s %s%s%s%s
",
                        $_ar->date               ?? '-',
                        $_ar->basho              ?? '-',
                        $_ar->race_name          ?? '-',
                        $_ar->dist               ?? '-',
                        $_ar->condition          ?? '',
                        $_ar->finishing_position ?? '-',
                        $_ar->num_horses         ?? '-',
                        $_ar->popularity         ?? '-',
                        $_cornerStr,
                        $_ar->last_3f            ?? '-',
                        $_ar->fin_time_diff      ?? '-',
                        $_ar->burden_weight      ?? '-',
                        $_ar->horse_weight       ?? '-',
                        $_restStr,
                        $_distDiff,
                        $_jockeyChg,
                        ($_ar->grade ?? null) ? '[' . $_ar->grade . ']' : ''
                    );
                }
            }
            $aHistoryText .= "
";
        }
        $lines[] = $aHistoryText;
    }
    // ── Block A End ──────────────────────────────────────────────────────────────

    // ══════════════════════════════════════════════════════════════════════════
    // @ANCHOR-20261005-ALLSCORE-TAIL  全頭採点の指示を末尾でもう一度出す
    // ══════════════════════════════════════════════════════════════════════════
    // 【見つかった問題（2026-10-05）】
    //   10/3の24レースを呼び直したところ、1st・2ndとも全頭採点JSONが
    //   1レースも返らなかった（AUDIT_AI:「全頭採点のJSONが無い」×24）。
    //   公開候補数は5〜7で正常なので、候補行は指示どおり出せている。
    //   原因はプロンプトの並び順。【全頭採点（内部用）】の指示は前半にあり、
    //   そのあとに「このフォーマットを厳守」という出力指示と、
    //   各馬の過去成績が延々と続く。LLMは最後に読んだ指示を優先するため、
    //   末尾の「候補行だけ」という形に引っ張られてJSONが落ちていた。
    //   前半のブロックは動かさず（他の指示との参照関係を壊さないため）、
    //   末尾に同じことをもう一度、短く書く。
    // ══════════════════════════════════════════════════════════════════════════
    // @ANCHOR-20261013-V04-HV  研究用H/V10項目の依頼（既定OFF・送信文は変わらない）
    // ══════════════════════════════════════════════════════════════════════════
    // 付録A/Bの「共通全頭100点（hv10-v04）」をここで追記できるようにしておく。
    //   ・BAGANRIKI_V04_HV_PROMPT が既定falseなので、通常は空文字が返り、
    //     送信文は1バイトも変わらない（受入A4の最終項目を満たす）。
    //   ・ONにできるのは、07章Dの未決（現行BEGIN/ENDマーカー・Flutterパーサー・
    //     行区切りとの適合）がよっしーから回答され、ユーザーが明示承認したあと。
    //   ・付録A/Bの本文をそのまま送らないのは、資料自身が「実送信されていない
    //     設計テンプレート」「そのまま実運用APIへ送信しない」と明記しており、
    //     未置換の <<...>> を含むため（05-3）。
    if (self::v04HvPrompt()) {
        try {
            $hvNums = array_map(static fn($h) => (int) $h['num'], $promptHorses);
            $hvBlock = self::v04HvPromptBlock(
                (int) $targetSelectionCount,
                $v04['structure'] ?? [],
                $hvNums,
                // @ANCHOR-20261014-ID-ECHO  照合用の実値（統合時に突き合わせる）
                ['race_id'       => "{$targetDate}_{$targetKaisuu}_{$targetBasho}_{$targetDay}_{$targetRace}",
                 'snapshot_hash' => (string) $auSnapshotId]
            );
            if ($hvBlock !== '') {
                $lines[] = '';
                $lines[] = '────────────────────────────────────────';
                $lines[] = $hvBlock;
            }
        } catch (\Throwable $hvE) {
            \Log::error('[V04_HV] 研究用H/V採点の依頼文の生成に失敗（現行の送信文はそのまま）', [
                'message' => $hvE->getMessage(),
            ]);
        }
    }

    $lines[] = '';
    $lines[] = '────────────────────────────────────────';
    $lines[] = '【最後に・出力の締めくくり】';
    $lines[] = '上の候補行をすべて出し終えたあと、改行して、前述の【全頭採点（内部用）】を必ず出力してください。';
    // ══════════════════════════════════════════════════════════════════════
    // @ANCHOR-20261013-V04-HV-TAIL  締めくくりで出力ブロックを全部数え上げる
    // ══════════════════════════════════════════════════════════════════════
    // 【10/13の実AI送信テストで分かったこと】
    //   研究用H/Vの依頼文を末尾（この締めくくりより後ろ）に足して1レース送ったら、
    //   1st・2ndとも <<<BAGANRIKI_ALLSCORE_END>>> で回答が終わっており、
    //   H/VのJSONが1度も返ってこなかった。原因はこの締めくくりの文面で、
    //   「この2行のマーカーと、その間の1行のJSONだけを置いてください」の
    //   「だけ」をAIが出力契約として読み、そこで打ち切っていた。
    //   10/5に全頭採点JSONが1レースも返らなかったときと同じ構図（最後の指示が勝つ）。
    //   → 依頼文をこのブロックの手前へ移し、ここで「出すブロックは何組か」を
    //     明示的に数え上げる。H/V依頼がOFFのときは従来どおりの文面に戻るので、
    //     本番の送信文は1バイトも変わらない。
    if (self::v04HvPrompt()) {
        $lines[] = '書き方は次のとおりです。出力するマーカー付きブロックは【2組】あります。';
        $lines[] = '必ず両方とも、この順番で出力してください。1組だけで終えてはいけません。';
        $lines[] = '';
        $lines[] = '〈1組目〉現行の全頭採点（内部用）';
        $lines[] = self::AUDIT_JSON_BEGIN;
        $lines[] = '{"v":1,"horses":[ ... 全実出走馬ぶん ... ]}';
        $lines[] = self::AUDIT_JSON_END;
        $lines[] = '';
        $lines[] = '〈2組目〉研究用の全頭採点（' . self::V04_SCORING_VERSION . '）※前述のH1〜H5・V1〜V5';
        $lines[] = self::V04_HV_JSON_BEGIN;
        $lines[] = '{"schema_version":"' . self::V04_SCHEMA_VERSION . '", ... 全実出走馬ぶん ... }';
        $lines[] = self::V04_HV_JSON_END;
        $lines[] = '';
        $lines[] = 'この2組は別物です。1組目を2組目のマーカーで囲んだり、逆にしたりしないでください。';
        $lines[] = 'どちらの領域も画面に表示しないため、Flutter形式を崩すことにはなりません。';
        $lines[] = '候補行が0頭の場合も、この2組は両方とも出力してください。';
        $lines[] = '候補行の中にJSONを混ぜてはいけません。';
        $lines[] = '順番は「候補行 → 1組目のJSON → 2組目のJSON」です。';
    } else {
        $lines[] = '書き方は次のとおりです。この2行のマーカーと、その間の1行のJSONだけを置いてください。';
        $lines[] = self::AUDIT_JSON_BEGIN;
        $lines[] = '{"v":1,"horses":[ ... 全実出走馬ぶん ... ]}';
        $lines[] = self::AUDIT_JSON_END;
        $lines[] = 'この領域は画面に表示しないため、Flutter形式を崩すことにはなりません。';
        $lines[] = '候補行が0頭の場合も、この領域だけは出力してください。';
        $lines[] = '候補行の中にJSONを混ぜてはいけません。順番は「候補行 → マーカー付きJSON」です。';
    }

    // @ANCHOR-20261013-V04-HV  （2026-10-13 移動）研究用H/Vの依頼文はここにあったが、
    //   末尾の【最後に・出力の締めくくり】より後ろだと、AIがその直前の
    //   「この2行のマーカーと、その間の1行のJSONだけを置いてください」に従って
    //   出力を打ち切り、H/VのJSONを1度も返さなかった（10/13の実AI送信テストで確認）。
    //   そのため締めくくりブロックの手前へ移し、締めくくり側で
    //   「マーカーは2組」と明記するように変えた。@ANCHOR-20261013-V04-HV-TAIL
    $promptText = implode("\n", $lines);

    // ═══════════════════════════════════════════════════════════════════════
    // @ANCHOR-20260928-PROMPT-SELFCHECK  送信前の機械検査（受入チェック#85）
    // ═══════════════════════════════════════════════════════════════════════
    // よっしー20260928指摘【本番差し込みの必須規則】：
    //   「1st AI・2nd AIそれぞれの最終送信文に未置換プレースホルダー、例示値、
    //     別レース値が残っていないことを機械検査してから送信する」
    //   「生成後に全馬番が対象レースの実出走馬一覧に含まれることを検査する」
    // ※ここは診断専用。検査そのもので予測を止めないよう \Throwable で保護する。
    try {
        $pcNg = [];

        // ① 未置換プレースホルダー（{{...}} / {ピンク} / <...> 形式）
        if (preg_match_all('/\{\{[^}]{1,60}\}\}/u', $promptText, $pcM1)) {
            $pcNg['未置換プレースホルダー'] = array_values(array_unique($pcM1[0]));
        }
        if (mb_strpos($promptText, '{ピンク}') !== false) {
            $pcNg['差し込み位置の記号'] = '{ピンク}';
        }

        // ② レース識別が対象レースと一致しているか（別レース値の混入検知）
        if (preg_match('/^日付: (\S+)$/mu', $promptText, $pcM2) && $pcM2[1] !== (string) $targetDate) {
            $pcNg['日付の不一致'] = ['プロンプト' => $pcM2[1], '対象' => (string) $targetDate];
        }
        if (preg_match('/^レース: (\d+)R/mu', $promptText, $pcM3) && (int) $pcM3[1] !== (int) $targetRace) {
            $pcNg['レース番号の不一致'] = ['プロンプト' => (int) $pcM3[1], '対象' => (int) $targetRace];
        }

        // ③ 馬番ブロックの馬番がすべて対象レースの実出走馬に含まれるか
        //    （「 1番( 4人気) 馬名」の行を拾う）
        $pcValidNums = array_map(fn($h) => (int) $h['num'], $displayHorses);
        if (preg_match_all('/^\s*(\d+)番\(\s*\d+人気\)/mu', $promptText, $pcM4)) {
            $pcBlockNums = array_values(array_unique(array_map('intval', $pcM4[1])));
            $pcAlien     = array_values(array_diff($pcBlockNums, $pcValidNums));
            if (!empty($pcAlien)) {
                $pcNg['実出走馬にない馬番'] = $pcAlien;
            }
            if (count($pcBlockNums) !== count($pcValidNums)) {
                $pcNg['馬番ブロック数の不一致'] = [
                    'ブロック' => count($pcBlockNums), '実出走馬' => count($pcValidNums),
                ];
            }
        }

        if (!empty($pcNg)) {
            \Log::warning('[プロンプト検査] 送信前チェックでNG（受入チェック#85）', [
                'race' => "{$targetDate} {$targetKaisuu}回{$targetBasho} {$targetDay}日目 {$targetRace}R",
                'NG'   => $pcNg,
            ]);
        } else {
            \Log::info('[プロンプト検査] 送信前チェックOK（未置換・別レース値・不明馬番なし）', [
                'race'   => "{$targetDate} {$targetKaisuu}回{$targetBasho} {$targetDay}日目 {$targetRace}R",
                '馬番数' => count($pcValidNums),
                '文字数' => mb_strlen($promptText),
            ]);
        }
    } catch (\Throwable $pcE) {
        \Log::warning('[プロンプト検査] 検査中に例外（プロンプトはそのまま使用）', [
            'message' => $pcE->getMessage(),
        ]);
    }

    // ═══════════════════════════════════════════════════════════════════════
    // @ANCHOR-20261004-AUDIT-RACE  監査ログ【レース単位】（仕様書9.1 表10）
    // ═══════════════════════════════════════════════════════════════════════
    //   保存内容: 版、snapshot_id、N/C、入力とプロンプトのSHA-256、B/C/D、
    //             配分モード、目標と実配分、降格理由、最終表示
    //   ※実配分・最終表示は統合後に決まるため、統合側の [AUDIT_MERGE] に出す。
    //   ※ここは診断専用。失敗しても予測を止めない。
    try {
        \Log::info('[AUDIT_RACE] レース単位の監査ログ（@ANCHOR-20261004-AUDIT-RACE）', [
            'race'            => "{$targetDate} {$targetKaisuu}回{$targetBasho} {$targetDay}日目 {$targetRace}R",
            '版'              => self::ALLOC_SPEC_VERSION,
            '可変配分'        => self::allocFeatureEnabled() ? '有効' : '無効（巻き戻し中）',
            'snapshot_id'     => $auSnapshotId,
            'N'               => $activeRunnerCount,
            'C'               => $targetSelectionCount,
            '入力SHA256'      => $auInputHash,
            'プロンプトSHA256' => hash('sha256', $promptText),
            'プロンプト文字数' => mb_strlen($promptText),
            'B'               => $allocThreeLabel($condition2Met),
            'C条件'           => $allocThreeLabel($condition3Met),
            'D'               => $allocThreeLabel($condition4Met),
            '断層タイプ'      => $gapType,
            '下位開放'        => $allocThreeLabel($allocLowerOpen),
            '選出前ゲート'    => $allocGate ? '成立' : '不成立',
            '配分モード'      => $allocMode,
            '目標配分'        => ($allocTargetFav === null)
                ? '既存目安（表6に数値なし）'
                : "{$allocTargetFav}＋{$allocTargetLong}",
            '降格理由'        => $allocModeReason,
            '同配分の注記'    => $allocSameNote,
            '資格あり馬番'    => $allocQualified,
            '保護対象馬番'    => $protectedLongshotNums,
        ]);
        // @ANCHOR-20261015-PROMPT-FACTS  監査ログと同じ値を控える（検証で突き合わせる）
        //   監査ログへ書くかどうかとは別に、いつでも控えます。
        self::recordPromptFacts([
            'race'             => "{$targetDate} {$targetKaisuu}回{$targetBasho} {$targetDay}日目 {$targetRace}R",
            'snapshot_id'      => $auSnapshotId,
            'N'                => $activeRunnerCount,
            'C'                => $targetSelectionCount,
            '入力SHA256'       => $auInputHash,
            'プロンプトSHA256' => hash('sha256', $promptText),
            'プロンプト文字数' => mb_strlen($promptText),
            '断層タイプ'       => $gapType,
            '配分モード'       => $allocMode,
            '資格あり馬番'     => $allocQualified,
        ]);

        // ══════════════════════════════════════════════════════════════════
        // @ANCHOR-20261015-AUDIT-NODIRTY  検証で組み直すときは監査ログへ書かない
        // ══════════════════════════════════════════════════════════════════
        // 10/15（1回目）02.txt ⑤「比較CSVの1st・2nd送信文MD5が空欄です。
        //   取得状況と、実際に送信されたプロンプトの一致を確認してください」
        // への対応で、保存済みの記録と突き合わせるためにプロンプトを
        // 組み直す検証コマンド（--prompt-verify）を足しました。
        // 組み直しは実レースの予想ではないので、監査ログには新しい行を足しません。
        // $dryRunNoPersist = true のときだけ書かないので、本番の動きは変わりません。
        if (!self::$dryRunNoPersist) {
            self::auditFile('AUDIT_RACE', [
                'race'            => "{$targetDate} {$targetKaisuu}回{$targetBasho} {$targetDay}日目 {$targetRace}R",
                '版'              => self::ALLOC_SPEC_VERSION,
                '可変配分'        => self::allocFeatureEnabled() ? '有効' : '無効（巻き戻し中）',
                'snapshot_id'     => $auSnapshotId,
                'N'               => $activeRunnerCount,
                'C'               => $targetSelectionCount,
                '入力SHA256'      => $auInputHash,
                'プロンプトSHA256' => hash('sha256', $promptText),
                'プロンプト文字数' => mb_strlen($promptText),
                'B'               => $allocThreeLabel($condition2Met),
                'C条件'           => $allocThreeLabel($condition3Met),
                'D'               => $allocThreeLabel($condition4Met),
                '断層タイプ'      => $gapType,
                '下位開放'        => $allocThreeLabel($allocLowerOpen),
                '選出前ゲート'    => $allocGate ? '成立' : '不成立',
                '配分モード'      => $allocMode,
                '目標配分'        => ($allocTargetFav === null)
                    ? '既存目安（表6に数値なし）'
                    : "{$allocTargetFav}＋{$allocTargetLong}",
                '降格理由'        => $allocModeReason,
                '同配分の注記'    => $allocSameNote,
                '資格あり馬番'    => $allocQualified,
                '保護対象馬番'    => $protectedLongshotNums,
            ]);
        }
    } catch (\Throwable $arE) {
        \Log::warning('[AUDIT_RACE] レース単位の監査ログの作成に失敗（処理は継続）', [
            'message' => $arE->getMessage(),
        ]);
    }

    // @ANCHOR-20261014-EVIDENCE-AUDIT2  依頼書②：送信文のハッシュを残す
    //   1st AIへ送る本文そのもの。2nd AIはここから一部を外して使うので、
    //   2nd側は送信直前に別途控える。
    self::recordPromptHash('1st', (string) $promptText);

    return $promptText;
}




/**
 * DeepSeek による第2の AI 分析
 *
 * getHorseOddsFinderAiAnalysis で保存した .data ファイルを読み込み、
 * DeepSeek API に投げて Claude とは独立した視点の予想を取得する。
 * 【厳選穴レースの判定ルール】はDeepSeekには不要なので除去して送信する。
 *
 * @param  Request $request  date, kaisuu, basho, day, race
 * @return \Illuminate\Http\JsonResponse
 */
public function getHorseOddsFinderSecondAiOpinion(Request $request)
{
    $date   = $request->query('date');
    $kaisuu = $request->query('kaisuu');
    $basho  = $request->query('basho');  // 場コード
    $day    = $request->query('day');
    $race   = $request->query('race');

    // ── 20260926 追加: 再マージモード（remerge=1）─────────────────────────
    //   フィルターの仕様を変更したあと、過去レースへ新ルールを適用するためのモード。
    //   保存済みの 2nd AI 回答（ai_analysis2.analysis_text）をそのまま使い、
    //   DeepSeek を呼ばずに「マージ＋フィルター」だけをやり直して
    //   ai_merge_result を上書きする。
    //     ・外部AI呼び出しは 0 回（費用がかからない）
    //     ・入力が同じなので結果は決定的（LLMの揺らぎが入らない）
    //   仕組み自体は既存の $reuseSecondText（保存済み回答の再利用）を流用しており、
    //   新しい呼び出し経路を作っているわけではない。
    $b2Remerge = ((string) $request->query('remerge', '')) === '1';

    // ─── キャッシュ確認（DBにレコードがあれば無条件で返す） ─────────────
    //   @ANCHOR-20261004-DRY-RUN  試算モードでは保存済み回答を返さず、必ず呼び直す
    $cached = DB::table('t_horse_odds_finder_ai_analysis2')
        ->where('date',       $date)
        ->where('kaisuu',     $kaisuu)
        ->where('basho_code', $basho)
        ->where('day',        $day)
        ->where('race',       $race)
        ->first();

    // ── キャッシュの扱い（20260924 修正）──────────────────────────────────
    // 【旧実装の不具合】ここで 2nd AI の回答を「1st AI 用の判定」（厳選穴レース行・レース指標行が必須）
    //   に通していた。2nd AI は仕様上その2行を出力しないため、正常な回答まで「失敗」と判定して削除し、
    //   開くたびに DeepSeek を呼び直していた（1レース2回までの仕様違反・結果が毎回変わる）。
    // 【現在の扱い】
    //   ・統合結果（ai_merge_result）が保存済み、または過去日のレース → 保存内容をそのまま返す
    //   ・当日のレースで統合結果が未保存 → DeepSeek は呼ばず、保存済みの 2nd AI 回答で統合処理だけやり直す
    if ($cached && self::$dryRunForceFresh) { $cached = null; }

    $reuseSecondText = null;
    // @ANCHOR-20261004-DRY-RUN  試算モードで保持した2nd AI回答があれば、
    //   DeepSeekを呼び直さずそれを使う（同じ回答で配分だけ変えて統合し直すため）。
    if (self::$dryRunNoPersist && self::$dryRunSecondText !== null) {
        $reuseSecondText = self::$dryRunSecondText;
    }
    // remerge=1 のときは統合結果の有無にかかわらず、保存済み回答での再マージへ進む
    // ══════════════════════════════════════════════════════════════════════
    // @ANCHOR-20261005-DRY-REUSE-PRIORITY  試算モードの使い回しを上書きしない
    // ══════════════════════════════════════════════════════════════════════
    // 【見つかった不具合（2026-10-05）】
    //   --compare-rerun の条件C（呼び直した回答＋可変配分）が、
    //   呼び直した回答ではなく「保存済みの統合結果」を返していた。
    //   ・remerge を付けないためキャッシュ分岐で早期リターンしていた
    //   ・remerge を付けると、今度は保存済み回答が
    //     self::$dryRunSecondText（呼び直した回答）を上書きしていた
    //   どちらでもCが成立しないため、配分の効果を比較できていなかった。
    //   → 試算モードで使い回す回答があるときは、それを最優先する。
    if ($cached && ($b2Remerge || !$this->_canReturnSecondAiCache($date, $kaisuu, $basho, $day, $race))) {
        if ($reuseSecondText === null) {   // @ANCHOR-20261005-DRY-REUSE-PRIORITY
            $reuseSecondText = (string) $cached->analysis_text;
        }
        $cached = null;
    }
    // @ANCHOR-20261005-DRY-REUSE-PRIORITY
    //   試算モードで呼び直した回答を持っているなら、保存済みの統合結果は返さない。
    if ($cached && self::$dryRunNoPersist && $reuseSecondText !== null) {
        $cached = null;
    }
    if ($cached) {
        // 保存済みの統合結果（merged_horses / upset_race / race_metrics）も併せて返す。
        // これが無いと、キャッシュヒット時にアプリが統合表示へ切り替われない。
        return response()->json(['data' => array_merge([
            'date'          => $date,
            'kaisuu'        => $kaisuu,
            'basho_code'    => $basho,
            'day'           => $day,
            'race'          => $race,
            'analysis_text' => trim(self::publicPart((string) $cached->analysis_text)),   // 【20261004】内部監査用JSONは返さない
        ], $this->_loadSavedMergeResult($date, $kaisuu, $basho, $day, $race))]);
    }

    // ─── 排他ロック（同一レースへの並行リクエスト防止） ──────────────
    $lockKey = "ai_analysis2_{$date}_{$kaisuu}_{$basho}_{$day}_{$race}";
    // @ANCHOR-20261005-LOCK-FALLBACK  ロックが使えなくても処理を捨てない
    $lock = self::acquireRaceLock($lockKey);

    try {

        // ロック後に再度キャッシュ確認（フォーマット検証あり）
        $cached = DB::table('t_horse_odds_finder_ai_analysis2')
            ->where('date',       $date)
            ->where('kaisuu',     $kaisuu)
            ->where('basho_code', $basho)
            ->where('day',        $day)
            ->where('race',       $race)
            ->first();
        if ($cached && self::$dryRunForceFresh) { $cached = null; }   // @ANCHOR-20261004-DRY-RUN

        // ── キャッシュの扱い（20260924 修正・上のロック前判定と同じ）─────────────
        // ※20260926: ロック前の判定と同様に remerge=1 を考慮する。
        //   ここを直し忘れると、1箇所目を通過しても【このロック後の再確認】で
        //   早期リターンし、再マージが一切行われない。
        // @ANCHOR-20261005-DRY-REUSE-PRIORITY  上のロック前分岐と同じ扱いにする
        if ($cached && ($b2Remerge || !$this->_canReturnSecondAiCache($date, $kaisuu, $basho, $day, $race))) {
            if ($reuseSecondText === null) {
                $reuseSecondText = (string) $cached->analysis_text;
            }
            $cached = null;
        }
        if ($cached && self::$dryRunNoPersist && $reuseSecondText !== null) {
            $cached = null;
        }
        if ($cached) {
            // ロック後の再確認でも同じく統合結果を載せる（上のキャッシュ分岐と同じ形）
            return response()->json(['data' => array_merge([
                'date'          => $date,
                'kaisuu'        => $kaisuu,
                'basho_code'    => $basho,
                'day'           => $day,
                'race'          => $race,
                'analysis_text' => trim(self::publicPart((string) $cached->analysis_text)),   // 【20261004】内部監査用JSONは返さない
            ], $this->_loadSavedMergeResult($date, $kaisuu, $basho, $day, $race))]);
        }

        // ─── レース基本情報の取得（basho_name・race_name の保存用） ──────
        $raceRow = DB::table('t_horse_odds_finder_races')
            ->where('date',   $date)
            ->where('kaisuu', $kaisuu)
            ->where('basho',  $basho)
            ->where('day',    $day)
            ->where('race',   intval($race))
            ->first();

        if (!$raceRow) {
            return response()->json(['error' => 'レースが見つかりません'], 404);
        }

        // ─── 【20260924】1st AI の確認を DeepSeek 呼び出しより前に行う ─────────────
        //   ・1st AI が未実行 → 2nd AI も実行しない（1st と同じ入力データで独立評価するのが仕様。
        //     以前は 1st と同時に呼ばれると、注目馬番の無い別プロンプトで DeepSeek を呼び、
        //     1st 未保存のため統合できず、未統合のままキャッシュされていた）
        //   ・1st AI が失敗（空・形式不正・8頭以上）→ 予測は公開しないので DeepSeek も呼ばない
        $preFirstRecord = DB::table('t_horse_odds_finder_ai_analysis')
            ->where('date',       $date)
            ->where('kaisuu',     $kaisuu)
            ->where('basho_code', $basho)
            ->where('day',        $day)
            ->where('race',       $race)
            ->first(['analysis_text']);
        if (!$preFirstRecord) {
            return response()->json(['error' => '1st AIの分析が完了していません。しばらくしてから再度お試しください'], 409);
        }
        // 【20260928 レース停止回避追補】1st AI が失敗していても 2nd AI を呼び、
        //   2nd AI の有効候補でレースを成立させる。500 は返さない。
        //   @ANCHOR-20260928-NO-RACE-STOP
        $preFirstError = $this->_firstAiPublishError((string) $preFirstRecord->analysis_text);
        if ($preFirstError !== null) {
            \Log::warning('[PREDICTION_PARTIAL] 1st AI 回答に問題あり → 2nd AIの有効候補で続行', [
                'reason' => $preFirstError,
                'date' => $date, 'kaisuu' => $kaisuu, 'basho' => $basho, 'day' => $day, 'race' => $race,
            ]);
        }

        // ─── プロンプトの取得（.data ファイルがあれば再利用、なければ自力生成） ──
        // getHorseOddsFinderAiAnalysis で保存した .data ファイルを優先して使い回す
        // 例: /var/www/horse_odds_finder/public/prompt/prompt_2026-08-16_2_07_8_9.data
        $filePath = public_path("prompt/prompt_{$date}_{$kaisuu}_{$basho}_{$day}_{$race}.data");

        // @ANCHOR-20261004-DRY-RUN  試算モードでは、1st AI側が作った新しいお願い文を使う
        //   （保存済みの .data ファイルは読まない＝旧プロンプトと混ぜない）
        if (self::$dryRunForceFresh && self::$dryRunFirstPrompt !== null) {
            $oddsData = self::$dryRunFirstPrompt;
        } elseif (file_exists($filePath)) {
            $oddsData = file_get_contents($filePath);
        } else {
            // .data ファイルがない場合はプロンプトを自力生成する
            $oddsData = $this->_getAiAnalysisPrompt($date, $kaisuu, $basho, $day, $race, '', '');
            if ($oddsData === null) {
                // 【20260928 レース停止回避追補】必須データ欠損でレースを止めない。
                //   候補行0件・レース情報のみの部分結果を HTTP 200 で返す。
                //   @ANCHOR-20260928-NO-RACE-STOP
                \Log::warning('[DATA_CORE_ERROR] 2nd AI用プロンプトを生成できない（候補0件で続行）', [
                    'date' => $date, 'kaisuu' => $kaisuu, 'basho' => $basho, 'day' => $day, 'race' => $race,
                ]);
                return response()->json(['data' => [
                    'date'          => $date,
                    'kaisuu'        => $kaisuu,
                    'basho_code'    => $basho,
                    'day'           => $day,
                    'race'          => $race,
                    'analysis_text'     => '',
                    'merged_horses'     => [],
                    'upset_race'        => 0,     // 候補0件＝条件A不成立 → 厳選穴レース|0
                    'upset_race_status' => '0',
                    'race_metrics'      => null,
                ]]);
            }
        }

        // ═══════════════════════════════════════════════════════════════════
        // @ANCHOR-20260928-UPSET-COND-SNAPSHOT  条件B・C・Dの先読み（重要）
        // ═══════════════════════════════════════════════════════════════════
        // 【不具合と修正 20260928】
        //   Block 15（厳選穴レースの再判定）は、これまで「2nd AI用に整形したあと」の
        //   $oddsData から「条件B（PHP算出済み）: …」を探していた。
        //   ところが直後の整形で【厳選穴レースの判定ルール】ブロックを丸ごと除去しており、
        //   条件B・C・Dの行も一緒に消えるため、3条件は一度も読み取れていなかった。
        //   旧実装は preg_match の結果を (bool) にしていたので「見つからない = 不成立」となり、
        //   実質「条件Aだけで厳選穴レースを判定する」状態で素通りしていた。
        //   （2026-09-27 の再マージで、3条件がすべて「不明」になり発覚）
        //   → 除去する前のプロンプト本文から読み取って保持する。
        //   ※2nd AIへ判定ルールを送らない仕様（除去）はそのまま維持する。
        $b15CondSnapshot = (function (string $src): array {
            $read = function (string $key) use ($src): ?bool {
                // 「不成立」を先に置く（前方一致の取り違え防止）
                if (preg_match('/条件' . $key . '（PHP算出済み）: (不成立|成立|不明)/u', $src, $m)) {
                    if ($m[1] === '成立')   return true;
                    if ($m[1] === '不成立') return false;
                    return null;
                }
                return null;   // 記載が無い → 不明
            };
            return ['B' => $read('B'), 'C' => $read('C'), 'D' => $read('D')];
        })($oddsData);

        // ── @ANCHOR-20261004-ALLOC-SNAPSHOT  配分モードの読み戻し（必ず整形前）──
        //   配分モード・目標配分・資格あり馬番は _getAiAnalysisPrompt() が確定して
        //   プロンプト本文へ埋め込んでいる。統合時に同じ値を使うため、ここで凍結値を
        //   読み戻す（再計算しない）。
        //   ※条件B・C・Dと同じ理由で、必ず2nd AI用の整形より前に読むこと。
        //     整形で【配分（PHP算出済み・変更禁止）】ブロックを除去するため、
        //     あとから読もうとすると一度も読めない（2026-09-28に同じ事故があった）。
        $allocSnapshot = (function (string $src): array {
            $mode = '通常'; $fav = null; $long = null; $qual = []; $n = null; $c = null;
            if (preg_match('/実出走頭数N:\s*(\d+)頭\s*\/\s*目標数C:\s*(\d+)頭\s*\/\s*配分モード:\s*(通常|中|強)/u', $src, $m)) {
                $n = (int) $m[1]; $c = (int) $m[2]; $mode = $m[3];
            }
            if (preg_match('/目標配分:\s*人気側（1〜6番人気）(\d+)頭\s*＋\s*穴側（PHPが資格を確認した7番人気以下）(\d+)頭/u', $src, $m)) {
                $fav = (int) $m[1]; $long = (int) $m[2];
            }
            if (preg_match('/資格あり馬番:\s*([0-9|]+)/u', $src, $m)) {
                $qual = array_values(array_unique(array_filter(
                    array_map('intval', explode('|', $m[1])),
                    fn($x) => $x > 0
                )));
                sort($qual);
            }
            return ['mode' => $mode, 'fav' => $fav, 'long' => $long, 'qualified' => $qual, 'N' => $n, 'C' => $c];
        })($oddsData);

        // @ANCHOR-20261004-FIX-REQUEST  1st AI用プロンプトの原文（整形前）を控える。
        //   不正回答への修正要求（該当AIにつき1回まで）で投げ直すときに使う。
        $firstPromptRaw = $oddsData;

        // @ANCHOR-20261004-QUAL-EVIDENCE  資格馬の根拠を読み戻す（必ず整形前）
        //   よっしー20261004回答①A-2の定型理由文に使う。
        //   書式: 馬番=pop:人気,s216:21→6短縮率,s96:9→6短縮率,fuku:複勝人気,opi:予測補正OPI
        $allocEvidenceSnapshot = (function (string $src): array {
            if (!preg_match('/^資格根拠:\s*(.+)$/mu', $src, $m)) return [];
            $txt = trim($m[1]);
            if ($txt === '' || $txt === 'なし') return [];
            $out = [];
            foreach (preg_split('/\s+/u', $txt) as $chunk) {
                if (!preg_match('/^(\d+)=(.+)$/u', $chunk, $cm)) continue;
                $row = [];
                foreach (explode(',', $cm[2]) as $kv) {
                    $p = explode(':', $kv, 2);
                    if (count($p) !== 2) continue;
                    $row[$p[0]] = ($p[1] === '-') ? null : (float) $p[1];
                }
                $out[(int) $cm[1]] = $row;
            }
            return $out;
        })($oddsData);

        // @ANCHOR-20261006-QUAL-STATE  7番人気以下の資格判定（三値）を読み戻す
        //   書式: 馬番:状態（1=成立 / 0=不成立 / ?=不明）
        //   読めない場合は空配列。空＝「資格ありの馬番だけで判断する」従来どおりの動き。
        $allocQualState = (function (string $src): array {
            if (!preg_match('/^資格判定:\s*(.+)$/mu', $src, $m)) return [];
            $txt = trim($m[1]);
            if ($txt === '' || $txt === 'なし') return [];
            $out = [];
            foreach (preg_split('/\s+/u', $txt) as $chunk) {
                if (!preg_match('/^(\d+):(1|0|\?)$/u', $chunk, $cm)) continue;
                $out[(int) $cm[1]] = ($cm[2] === '1') ? true : (($cm[2] === '0') ? false : null);
            }
            return $out;
        })($oddsData);

        // @ANCHOR-20261004-AUDIT-SNAPSHOT  プロンプト生成時の snapshot_id を読み戻す
        //   仕様書9.2「途中の取消更新 → 旧snapshot_idと混ぜない」の照合に使う。
        $auPromptSnapshotId = null;
        if (preg_match('/snapshot_id:\s*([0-9a-f]{16})/u', $oddsData, $auSm)) {
            $auPromptSnapshotId = $auSm[1];
        }
        // 統合時点のDBから同じ式で再計算し、プロンプト生成時と一致するか確認する。
        //   一致しない = 6分前オッズが更新された（取消等）。仕様書9.2は
        //   「両AIを同じ最新版で再実行。旧snapshot_idと混ぜない」としているため、
        //   ここでは混在を検知してログに残す（処理は止めない）。
        $auNowSnapshotId     = null;
        $auNowSnapshotSource = [];
        try {
            $auNowSnapshotRows = DB::table('t_horse_odds_finder_odds')
                    ->where('date',   $date)
                    ->where('kaisuu', $raceRow->kaisuu)
                    ->where('basho',  $raceRow->basho)
                    ->where('day',    $raceRow->day)
                    ->where('race',   $raceRow->race)
                    ->where('minutes_before_start', self::SNAPSHOT_TIMING)
                    ->get();
            $auNowSnapshotSource = self::oddsSnapshotSource($auNowSnapshotRows);
            $auNowSnapshotId     = substr(hash('sha256', json_encode($auNowSnapshotSource)), 0, 16);
        } catch (\Throwable $auNe) {
            \Log::warning('[AUDIT_SNAPSHOT] 統合時のsnapshot_id再計算に失敗（処理は継続）', [
                'message' => $auNe->getMessage(),
            ]);
        }
        $auSnapshotMatch = ($auPromptSnapshotId !== null && $auNowSnapshotId !== null)
            ? ($auPromptSnapshotId === $auNowSnapshotId)
            : null;
        if ($auSnapshotMatch === false) {
            // 【20261004 よっしー回答③Aの条件】
            //   「不一致を警告するだけで旧入力と新入力を混ぜて統合することは避けてください。
            //     取消更新などで入力が変わった場合は、仕様書9.2どおり、両AIを同じ最新版の
            //     入力で再実行してください。」
            //   → 通常実行では統合せず「未確定」で返す（混ぜない）。
            //     再実行は保存済み回答を消してから行う（勝手に消さない）。
            //   ※--remerge（比較・再マージ）のときは、保存済み回答の診断が目的なので
            //     統合を続けるが、混在であることを必ず記録に残す。
            //   @ANCHOR-20261004-SNAPSHOT-NO-MIX
            \Log::warning('[INPUT_SNAPSHOT_MISMATCH] 6分前オッズがプロンプト生成後に変わっている（旧入力と新入力を混ぜない）', [
                'race'               => "{$date} {$kaisuu}回{$basho} {$day}日目 {$race}R",
                '対象時点'           => self::SNAPSHOT_TIMING . '分前',
                'プロンプト生成時'   => $auPromptSnapshotId,
                '統合時'             => $auNowSnapshotId,
                'モード'             => $b2Remerge ? '再マージ（診断のため続行・混在を記録）' : '通常（統合せず未確定で返す）',
                '対応'               => '両AIを同じ最新版の入力で再実行する。'
                                        . 'ai_analysis / ai_analysis2 の該当行と public/prompt/*.data を消してから実行する',
            ]);
            if (!$b2Remerge) {
                $this->_saveUndetermined($date, $kaisuu, $basho, $day, $race,
                    '6分前オッズがプロンプト生成後に変わった（旧入力と新入力を混ぜない）', [
                        'プロンプト生成時' => $auPromptSnapshotId,
                        '統合時'           => $auNowSnapshotId,
                        '対象時点'         => self::SNAPSHOT_TIMING . '分前',
                    ]);
                return response()->json(['data' => [
                    'date'          => $date,
                    'kaisuu'        => $kaisuu,
                    'basho_code'    => $basho,
                    'day'           => $day,
                    'race'          => $race,
                    'analysis_text' => '',
                    'merged_horses' => [],
                    'upset_race'    => null,
                    'status'        => 'undetermined',
                    'status_reason' => '6分前オッズがプロンプト生成後に変わったため未確定（旧入力と新入力を混ぜない）',
                ]]);
            }
        } else {
            \Log::info('[AUDIT_SNAPSHOT] snapshot_idの照合', [
                'race'             => "{$date} {$kaisuu}回{$basho} {$day}日目 {$race}R",
                'プロンプト生成時' => $auPromptSnapshotId,
                '統合時'           => $auNowSnapshotId,
                '判定'             => $auSnapshotMatch === null ? '不明（どちらかが取得できない）' : '一致',
            ]);
        }

        \Log::info('[配分] 整形前のプロンプトから配分モードを読み戻し（@ANCHOR-20261004-ALLOC-SNAPSHOT）', [
            'race'         => "{$date} {$kaisuu}回{$basho} {$day}日目 {$race}R",
            'N'            => $allocSnapshot['N'],
            'C'            => $allocSnapshot['C'],
            '配分モード'   => $allocSnapshot['mode'],
            '目標配分'     => $allocSnapshot['fav'] === null
                ? '既存目安（表6に数値なし）'
                : "{$allocSnapshot['fav']}＋{$allocSnapshot['long']}",
            '資格あり馬番' => $allocSnapshot['qualified'],
            '読み取り'     => ($allocSnapshot['N'] === null)
                ? '★失敗（プロンプトに配分ブロックが無い。旧プロンプトの再実行か、埋め込み漏れ）'
                : 'OK',
        ]);

        \Log::info('[厳選穴レース] 整形前のプロンプトから条件B・C・Dを読み取り', [
            'race'  => "{$date} {$kaisuu}回{$basho} {$day}日目 {$race}R",
            '条件B' => $b15CondSnapshot['B'] === null ? '不明' : ($b15CondSnapshot['B'] ? '成立' : '不成立'),
            '条件C' => $b15CondSnapshot['C'] === null ? '不明' : ($b15CondSnapshot['C'] ? '成立' : '不成立'),
            '条件D' => $b15CondSnapshot['D'] === null ? '不明' : ($b15CondSnapshot['D'] ? '成立' : '不成立'),
        ]);

        // ─── DeepSeek 用にプロンプトを整形 ──────────────────────────────
        // 【仕様「1st AI のプロンプトを読み込んで以下を除去した上で送信する」】
        //   ① 「厳選穴レースの判定ルール」ブロック全体
        //   ② 出力フォーマット内の「厳選穴レース|1または0」行
        //   ③ 「レース指標|波乱度: X|下位進入度: X|大穴進入度: X」行
        //   ④ 末尾の1st AI専用出力指示
        // ※「おすすめ度計算方法」「システムの目的」「回収率優先・低配当除外ルール」等の
        //   【2nd AIにも残す絶対ルール】は除去しない（維持必須）。
        // ※ /u（UTF-8）を付けないと全角文字がバイト単位で扱われ、意図しない切断が起きうる。
        //   不正なUTF-8が混じると preg_replace が null を返すため、その場合は元の文字列を保つ。
        $b2ndStrip = function (string $subject, string $pattern): string {
            $replaced = preg_replace($pattern, '', $subject);
            return ($replaced === null) ? $subject : $replaced;   // null なら除去せず元のまま
        };
        // ① 判定ルールブロック
        $oddsData = $b2ndStrip($oddsData, '/【厳選穴レースの判定ルール】.*?(?=\nおすすめ度は)/su');
        // ② 「厳選穴レース|1または0」行
        // 【20261004】配分ブロックは2nd AIへ送らない。
        //   仕様書6.1②「2nd単独に3＋4の7頭を要求しない」。
        //   PHP側は $allocSnapshot（整形前に読み戻した凍結値）を使う。
        $oddsData = $b2ndStrip($oddsData, '/^【配分（PHP算出済み・変更禁止）】\n?/mu');
        $oddsData = $b2ndStrip($oddsData, '/^【入力スナップショット（記録用・予想の判断には使いません）】[^\n]*\n?/mu');
        $oddsData = $b2ndStrip($oddsData, '/^実出走頭数N:[^\n]*\n?/mu');
        $oddsData = $b2ndStrip($oddsData, '/^目標配分:[^\n]*\n?/mu');
        $oddsData = $b2ndStrip($oddsData, '/^資格あり馬番:[^\n]*\n?/mu');
        $oddsData = $b2ndStrip($oddsData, '/^資格根拠:[^\n]*\n?/mu');
        $oddsData = $b2ndStrip($oddsData, '/^配分モードと目標配分はPHPが確定した値です。[^\n]*\n?/mu');
        $oddsData = $b2ndStrip($oddsData, '/^目標配分は最終候補の内訳の目標です。[^\n]*\n?/mu');
        $oddsData = $b2ndStrip($oddsData, '/^厳選穴レース\|1または0\n?/mu');
        // ③ 「レース指標|波乱度: X|下位進入度: X|大穴進入度: X」行（2nd AIは候補行だけを返す）
        $oddsData = $b2ndStrip($oddsData, '/^2行目: 「レース指標[^\n]*\n?/mu');
        $oddsData = $b2ndStrip($oddsData, '/^レース指標\|波乱度[^\n]*\n?/mu');
        // ④ 末尾の1st AI専用出力指示
        $oddsData = $b2ndStrip($oddsData, '/^選出馬は必ず「厳選穴レース[^\n]*\n?/mu');
        $oddsData = $b2ndStrip($oddsData, '/^1行目: 「厳選穴レース[^\n]*\n?/mu');
        // 【20260924】1st AI専用の「候補0頭時は1行目と2行目だけ」指示も除去（2nd AIは「候補なし|0」を使う）
        $oddsData = $b2ndStrip($oddsData, '/^候補が0頭の場合は、1行目と2行目だけ[^\n]*\n?/mu');

        // ⑤ 【20260927】1st AI専用の「目標数C頭ちょうど」指示を除去する ───────────
        //   よっしー20260927指摘で1st AIはC頭必達になったが、
        //   2nd AI（DeepSeek）は従来どおり1〜5頭。C頭の指示が残ると
        //   末尾で付け直す2nd AI用の出力指示と矛盾し、頭数が崩れる。
        //   ※「このレースの実出走頭数は N 頭です」は2nd AIにも有益なので残す。
        //   ※「低配当条件・回収率・人気帯条件を除外理由にしてはいけない」は
        //     2nd AIにも適用される絶対ルールなので残す。
        //   @ANCHOR-20260927-TARGET-COUNT
        $oddsData = $b2ndStrip($oddsData, '/^選出する頭数は [^\n]*\n?/mu');
        $oddsData = $b2ndStrip($oddsData, '/^全実出走馬を同一の固定100点配点で評価し、全頭を順位付けしたうえで[^\n]*\n?/mu');
        $oddsData = $b2ndStrip($oddsData, '/^利用可能な情報だけでは \d+ 頭に届かない場合[^\n]*\n?/mu');
        $oddsData = $b2ndStrip($oddsData, '/^\d+ 頭を超えて出力してはいけません。[^\n]*\n?/mu');
        $oddsData = $b2ndStrip($oddsData, '/^頭数は人間が別途算出した確定値です。[^\n]*\n?/mu');
        $oddsData = $b2ndStrip($oddsData, '/^目標数 \d+ 頭に近づけるために必要なら[^\n]*\n?/mu');
        $oddsData = $b2ndStrip($oddsData, '/^【目標数 \d+ 頭（目標かつ上限）】\n?/mu');
        $oddsData = $b2ndStrip($oddsData, '/^全実出走馬を100点満点で採点し、固定おすすめ度順に並べたうえで[^\n]*\n?/mu');
        $oddsData = $b2ndStrip($oddsData, '/^点数が低いという理由だけで候補を削らないでください。[^\n]*\n?/mu');
        $oddsData = $b2ndStrip($oddsData, '/^選出馬は必ず下記フォーマットを厳守して出力してください[^\n]*\n?/mu');
        $oddsData = $b2ndStrip($oddsData, '/^候補0件または \d+ 頭未満でもエラーや公開停止にはなりません。[^\n]*\n?/mu');
        $oddsData = $b2ndStrip($oddsData, '/^厳選穴レース行・レース指標行は候補数に数えません。\n?/mu');
        // 人気薄保護枠のうち、1st AI専用の「C頭の中に含める／最下位と入替」だけ置換する。
        // 「対象馬番: 〜」行は統合処理で読み戻すため絶対に消さない。
        $oddsData = preg_replace(
            '/^この中でおすすめ度が最も高い1頭を、最大 \d+ 頭の候補の中に可能な範囲で含めてください。$/mu',
            'この中でおすすめ度が最も高い1頭を、あなたの候補にも優先して含めてください。',
            $oddsData
        ) ?? $oddsData;
        $oddsData = $b2ndStrip($oddsData, '/^通常の上位候補の最下位1頭と入れ替える形になります。[^\n]*\n?/mu');
        // 1・2行目を除去した結果ひとりだけ残る「3行目以降: 〜」も除去する。
        // 2nd AI用の出力フォーマットはプロンプト末尾で改めて指示している。
        $oddsData = $b2ndStrip($oddsData, '/^3行目以降: 「馬番：[^\n]*\n?/mu');

        // ── 【20260928】C頭要求が2nd AI用プロンプトに残っていないかの機械検証 ──────
        //   よっしー20260928指摘：
        //     「2nd AIに渡す最終プロンプトからC頭を要求する指示がなくなったことを
        //       送信前に機械的に検証する。」
        //   ※【人気薄の根拠付き保護対象】ブロックの行は2nd AIにも残す仕様なので除く。
        //   @ANCHOR-20260928-VERIFY-NO-C-DEMAND
        try {
            // 【20260928 修正】検査条件が緩すぎて誤検知していた。
            //   出力フォーマットの例文「馬番：X、…（候補1頭につき改行なし…」の
            //   「候補」＋「1頭」を、C頭を要求する指示と誤認して毎レース警告が出ていた。
            //   行の書式見本や保護枠の案内は対象外とし、
            //   実際に頭数を要求している言い回しだけを拾う。
            $b2ndSkipHead = [
                '対象馬番:',                      // 保護枠：統合処理で読み戻すため残す行
                'この中でおすすめ度が最も高い1頭',  // 保護枠：2nd AI向けに置換済みの行
                '馬番：X',                        // 出力フォーマットの例文
                '3行目以降:',                     // 出力フォーマットの行番号案内
                '2nd AIは',                       // 末尾に付け足す2nd AI自身への指示
            ];
            // 【20260928 再修正】「選出頭数」という語だけで引っかけていたため、
            //   『これが人気帯別の選出頭数の根拠になります』という指標の説明文まで
            //   誤検知していた（毎レース警告が出ていた）。
            //   語そのものではなく「頭数を要求している言い回し」だけを拾う。
            $b2ndDemand = [
                '/目標数/u',
                '/選出する頭数/u',
                '/必ず\s*\d+\s*頭/u',
                '/\d+\s*頭ちょうど/u',
                '/\d+\s*頭を超えて出力/u',
                '/\d+\s*頭より少なく/u',
                '/\d+\s*頭に届かない/u',
                '/\d+\s*頭は必ず/u',
                '/\d+\s*頭を選べます/u',
            ];

            $b2ndLeft = [];
            foreach (explode("\n", $oddsData) as $b2ndLine) {
                $b2ndT = trim($b2ndLine);
                if ($b2ndT === '') continue;

                $b2ndSkip = false;
                foreach ($b2ndSkipHead as $b2ndH) {
                    if (mb_strpos($b2ndT, $b2ndH) === 0) { $b2ndSkip = true; break; }
                }
                if ($b2ndSkip) continue;

                foreach ($b2ndDemand as $b2ndP) {
                    if (preg_match($b2ndP, $b2ndT)) {
                        $b2ndLeft[] = mb_substr($b2ndT, 0, 80);
                        break;
                    }
                }
            }
            if (!empty($b2ndLeft)) {
                \Log::warning('[2nd AI検証] C頭を要求する指示が残っている可能性', [
                    'race'  => "{$date} {$kaisuu}回{$basho} {$day}日目 {$race}R",
                    'lines' => $b2ndLeft,
                ]);
            }

            // 【20260928 受入チェック#85】2nd AI送信文にも未置換・別レース値が無いか検査する
            //   @ANCHOR-20260928-PROMPT-SELFCHECK
            $b2ndNg = [];
            if (preg_match_all('/\{\{[^}]{1,60}\}\}/u', $oddsData, $b2ndPh)) {
                $b2ndNg['未置換プレースホルダー'] = array_values(array_unique($b2ndPh[0]));
            }
            if (mb_strpos($oddsData, '{ピンク}') !== false) {
                $b2ndNg['差し込み位置の記号'] = '{ピンク}';
            }
            if (preg_match('/^日付: (\S+)$/mu', $oddsData, $b2ndDt) && $b2ndDt[1] !== (string) $date) {
                $b2ndNg['日付の不一致'] = ['プロンプト' => $b2ndDt[1], '対象' => (string) $date];
            }
            if (preg_match('/^レース: (\d+)R/mu', $oddsData, $b2ndRc) && (int) $b2ndRc[1] !== (int) $race) {
                $b2ndNg['レース番号の不一致'] = ['プロンプト' => (int) $b2ndRc[1], '対象' => (int) $race];
            }
            if (!empty($b2ndNg)) {
                \Log::warning('[2nd AI検証] 送信前チェックでNG（受入チェック#85）', [
                    'race' => "{$date} {$kaisuu}回{$basho} {$day}日目 {$race}R",
                    'NG'   => $b2ndNg,
                ]);
            }
        } catch (\Throwable $b2ndVfE) {
            \Log::warning('[2nd AI検証] C頭要求の検証で例外（処理は継続）', ['msg' => $b2ndVfE->getMessage()]);
        }
        // ─── 頭数から選出数を再計算（1st AIと同じロジック） ─────────────────
        $horseCount2nd = DB::table('t_horse_odds_finder_horses')
            ->where('date',   $date)
            ->where('kaisuu', $raceRow->kaisuu)
            ->where('basho',  $raceRow->basho)
            ->where('day',    $raceRow->day)
            ->where('race',   $raceRow->race)
            ->count();
        $pickupCount = 5; // 2nd AI（DeepSeek）の回答上限は出走頭数に関係なく固定5頭

        // ── 【20260927】人気薄の根拠付き保護対象の復元 ────────────────────────
        //   保護対象は _getAiAnalysisPrompt() が算出してプロンプト本文へ埋め込んでいる。
        //   .data ファイルから読み直した場合でも同じ値が得られるよう、
        //   ここでは再計算せずプロンプト本文から読み戻す（凍結値をそのまま使う）。
        //   @ANCHOR-20260927-PROTECTED-LONGSHOT
        $protectedLongshotForMerge = [];
        if (preg_match(
                '/【人気薄の根拠付き保護対象（PHP算出済み）】.*?\n対象馬番:\s*([0-9|]+)/su',
                $oddsData, $plmM
            )) {
            $protectedLongshotForMerge = array_values(array_unique(array_filter(
                array_map('intval', explode('|', $plmM[1])),
                fn($n) => $n > 0
            )));
            sort($protectedLongshotForMerge);
        }


        // ── Block 9: 出走履歴データ取得・プロンプト付加（⑩ 項目拡充済み）──────────────
        // 対象馬の直近走（最大10走）を shutsuba_history から取得し、能力適性評価の根拠として追記する
        // 仕様:「各馬の直近5走以上（取得可能なら10走）」
        // ⑩ 拡充: grade/jockey/burden_weight/horse_weight/corner_1〜4 を追加
        // 今走条件（$raceRow->dist/$raceRow->course/$raceRow->grade）も先頭に付加
        // ── よっしー20260922-03指摘①: 過去成績の二重送信を防止 ─────────────
        // 1st AI用プロンプト（.dataファイル）には Block A として同一内容の
        // 【各馬の直近成績（過去最大10走）と今走データ】が既に含まれている。
        // そのまま Block 9 を追記すると DeepSeek へ同じ過去成績が2回送られるため、
        // 未収録の場合（将来 Block A が外れた場合の保険）だけ生成・追記する。
        // ※ 能力適性ブロックの本文にも同じ見出し文字列が含まれる
        //   （'プロンプト末尾の【各馬の直近成績…】を根拠に'）ため、
        //   単純な部分一致では Block A が外れても収録済みと誤判定する。
        //   Block A は必ず行頭に出るので前後の改行込みで判定する。
        $b9NeedHistory = (mb_strpos($oddsData, "\n【各馬の直近成績（過去最大10走）と今走データ】\n") === false);
        if (!$b9NeedHistory) {
//             \Log::info('[Block9] 過去成績は1st AIプロンプト（Block A）に収録済みのため追記をスキップ');
        }

        $b9HorseRows = $b9NeedHistory
            ? DB::table('t_horse_odds_finder_horses')
                ->where('date',   $date)
                ->where('kaisuu', $raceRow->kaisuu)
                ->where('basho',  $raceRow->basho)
                ->where('day',    $raceRow->day)
                ->where('race',   $raceRow->race)
                ->orderBy('num')
                ->get(['num', 'name', 'jockey']) // ⑩ 今走騎手を追加
            : collect();

        $b9TodayDist   = isset($raceRow->dist)   ? (int)$raceRow->dist   : null;
        $b9TodayCourse = isset($raceRow->course) ? $raceRow->course       : null;
        $b9TodayGrade  = isset($raceRow->grade)  ? $raceRow->grade        : null;

        $b9HistoryText  = "\n\n【各馬の直近成績（過去最大10走）と今走データ】\n";
        $b9HistoryText .= "能力・適性評価（100点満点・6項目）の根拠として利用してください。\n";
        $b9HistoryText .= "評価区分：A（80〜100点）B（70〜79点）C（60〜69点）D（59点以下）\n";
        if ($b9TodayCourse || $b9TodayDist) {
            $b9HistoryText .= '【今走条件】'
                . ($b9TodayCourse ?? '')
                . ($b9TodayDist   ? $b9TodayDist . 'm' : '')
                . ($b9TodayGrade  ? ' ' . $b9TodayGrade : '')
                . "\n";
        }
        $b9HistoryText .= "\n";

        foreach ($b9HorseRows as $b9Horse) {
            $b9Num    = (int)$b9Horse->num;
            $b9Name   = $b9Horse->name;
            $b9Jockey = $b9Horse->jockey ?? null; // 今走騎手

            $b9Rows = DB::table('t_horse_odds_finder_shutsuba_history')
                ->where('name', $b9Name)
                ->where('date', '<', $date)   // 【20260924】仕様「対象レースより前の最大10走」・未来情報混入の防止
                ->orderBy('date', 'desc')
                ->limit(10)   // 仕様: 取得可能なら10走
                ->get(['date', 'basho', 'race_name', 'dist', 'condition', 'grade',
                        'finishing_position', 'num_horses', 'popularity', 'jockey',
                        'burden_weight', 'horse_weight', 'last_3f', 'fin_time_diff',
                        'corner_1', 'corner_2', 'corner_3', 'corner_4']);

            $b9HistoryText .= "{$b9Num}番 {$b9Name}";
            if ($b9Jockey) {
                $b9HistoryText .= "（今走騎手: {$b9Jockey}）";
            }
            $b9HistoryText .= "\n";

            if ($b9Rows->isEmpty()) {
                $b9HistoryText .= "  （出走履歴なし）\n";
            } else {
                $b9RowsArr = $b9Rows->values()->all();
                foreach ($b9RowsArr as $b9i => $b9r) {
                    // 通過順位
                    $b9Corners = array_filter([
                        $b9r->corner_1 ?? null,
                        $b9r->corner_2 ?? null,
                        $b9r->corner_3 ?? null,
                        $b9r->corner_4 ?? null,
                    ], fn($v) => $v !== null && $v !== '');
                    $b9CornerStr = !empty($b9Corners) ? implode('-', $b9Corners) : '-';

                    // 距離変化（今走 vs 最新前走）
                    $b9DistDiff = '';
                    if ($b9i === 0 && $b9TodayDist && $b9r->dist) {
                        $b9dd = $b9TodayDist - (int)$b9r->dist;
                        if ($b9dd > 0) $b9DistDiff = "（今走+{$b9dd}m延長）";
                        elseif ($b9dd < 0) $b9DistDiff = "（今走{$b9dd}m短縮）";
                    }

                    // 騎手継続・乗り替わり（今走 vs 最新前走）
                    $b9JockeyChg = '';
                    if ($b9i === 0 && $b9Jockey && ($b9r->jockey ?? null)) {
                        $b9JockeyChg = ($b9r->jockey === $b9Jockey)
                            ? '（騎手継続）'
                            : "（乗替:前走{$b9r->jockey}）";
                    }

                    // 休養日数
                    $b9RestStr = '';
                    if ($b9i === 0 && $date && $b9r->date) {
                        $b9d1 = new \DateTime($date);
                        $b9d2 = new \DateTime($b9r->date);
                        $b9RestStr = '休' . $b9d1->diff($b9d2)->days . '日';
                    } elseif ($b9i > 0 && isset($b9RowsArr[$b9i - 1]->date) && $b9r->date) {
                        $b9d1 = new \DateTime($b9RowsArr[$b9i - 1]->date);
                        $b9d2 = new \DateTime($b9r->date);
                        $b9RestStr = '休' . $b9d1->diff($b9d2)->days . '日';
                    }

                    $b9HistoryText .= sprintf(
                        "  %s %s %s %s%s %s着/%s頭中 %s人気 通過:%s 上がり%s 着差%s 斤%s 馬体%s %s%s%s%s\n",
                        $b9r->date               ?? '-',
                        $b9r->basho              ?? '-',
                        $b9r->race_name          ?? '-',
                        $b9r->dist               ?? '-',
                        $b9r->condition          ?? '',
                        $b9r->finishing_position ?? '-',
                        $b9r->num_horses         ?? '-',
                        $b9r->popularity         ?? '-',
                        $b9CornerStr,
                        $b9r->last_3f            ?? '-',
                        $b9r->fin_time_diff      ?? '-',
                        $b9r->burden_weight      ?? '-',
                        $b9r->horse_weight       ?? '-',
                        $b9RestStr,
                        $b9DistDiff,
                        $b9JockeyChg,
                        ($b9r->grade ?? null) ? '[' . $b9r->grade . ']' : ''
                    );
                }
            }
            $b9HistoryText .= "\n";
        }
        if ($b9NeedHistory) {
            $oddsData .= $b9HistoryText;   // よっしー20260922-03指摘①: 未収録時のみ追記
        }
        // ── Block 9 End ────────────────────────────────────────────────────────────

        // ── 仕様書【末尾に追記される内容】の本文そのまま（要約・改変禁止）──────
        // 【重大な不具合と修正】以前はここで「候補が0頭の場合は、『厳選穴レース行』と
        //   『レース指標行』のみを出力し…」と指示していた。これは仕様と正反対で、
        //   仕様は「基準を満たす馬が0頭の場合だけ、例外出力として『候補なし|0』の
        //   1行だけを返してください」と定めている。
        //   この誤った指示のせいで 2nd AI が候補行以外を返し、PHP側の形式検証に
        //   毎レース弾かれて「1st AI単独継続」になり続けていた。
        //   （2026-09-21 の本番ログで全7レースが [B-7] 形式不正になっていた）
        // 【20260928 仕様（よっしー20260928指摘・仕様書の本文どおり）】
        //   2nd AI は 0〜5頭の独立候補。C頭に合わせて補充しない。
