            if ($b2Remerge) {
                \Log::info('[再マージ] DeepSeekを呼ばず保存済み回答でフィルターを再適用', [
                    'race' => "{$date} {$kaisuu}回{$basho} {$day}日目 {$race}R",
                ]);
            }
            $maxRetries   = 0; // 下の呼び出しループを実行しない
            $analysisText = trim($reuseSecondText);
            // 【20260928 仕様（よっしー20260928指摘）】
            //   ・候補行0件の空回答     … 正常な候補なし（失敗ではない）
            //   ・「候補なし|0」マーカー … 形式外マーカーなので形式不正として記録
            //   ・非空だが候補行を1行も読めない … 形式不正として記録
            //   いずれの場合もレースは止めず、1st AI の有効候補で続行する。
            //   @ANCHOR-20260928-SECOND-EMPTY-IS-NORMAL
            if (preg_match('/^候補なし\|0$/mu', $analysisText)) {
                \Log::warning('[B-7] 保存済み2nd AI回答に形式外マーカー「候補なし|0」（候補なし扱いで続行）', [
                    'race' => "{$date} {$kaisuu}回{$basho} {$day}日目 {$race}R",
                ]);
                $analysisText     = '';
                $b7SecondAiFailed = true;
            } elseif ($analysisText === '') {
                \Log::info('[B-7] 保存済み2nd AI回答が空（正常な候補なし）', [
                    'race' => "{$date} {$kaisuu}回{$basho} {$day}日目 {$race}R",
                ]);
            } elseif (empty($this->_parseAiHorses($analysisText))) {
                \Log::warning('[B-7] 保存済み2nd AI回答の候補行がすべて不正（候補なし扱いで続行）', [
                    'race' => "{$date} {$kaisuu}回{$basho} {$day}日目 {$race}R",
                ]);
                $b7SecondAiFailed = true;
            }
        }
        // ══════════════════════════════════════════════════════════════════
        // @ANCHOR-20261020-R122-PROMPT  r12.2 の本文へ全文置換（機能フラグ）
        // ══════════════════════════════════════════════════════════════════
        // 根拠：server_contract_r12.2.txt 6章・9章／prompts/prompt_2nd.txt
        //
        //   1st側と同じ扱いです。system を prompt_2nd.txt の全文、
        //   user を INPUT_JSON 1個へ入れ替えます（role_cap=min(5,C)）。
        //
        //   【ここで入れ替える理由】この手前にある条件B・C・Dの先読みと
        //   配分の読み戻しは、旧本文の文面から読んでいます。送信文だけを
        //   差し替えれば、統合側の既存の流れを壊さずに本文を置換できます。
        //   <b>統合側（_mergeAiResults）を r12.2 の応答キーへ合わせる作業は
        //   まだ残っています</b>（残作業「実AI接続」。14_残作業と日程に記載）。
        // @ANCHOR-20261020-R122-SHADOW  shadow のときは本文を差し替えません
        if (BaganrikiPrompt::sending()) {
            $r122b = $this->r122AssembleSend($date, $kaisuu, $basho, $day, $race, '2nd');
            if (!$r122b['ok']) {
                \Log::error('[INPUT_INVALID] r12.2の送信文を作れないため2nd AIを呼びません', [
                    'date' => $date, 'kaisuu' => $kaisuu, 'basho' => $basho,
                    'day'  => $day,  'race'   => $race,
                    'code' => $r122b['code'], 'reason' => $r122b['reason'],
                ]);
                return response()->json(['data' => [
                    'date'              => $date,
                    'kaisuu'            => $kaisuu,
                    'basho_code'        => $basho,
                    'day'               => $day,
                    'race'              => $race,
                    'analysis_text'     => '',
                    'merged_horses'     => [],
                    'upset_race'        => 0,
                    'upset_race_status' => '0',
                    'race_metrics'      => null,
                ]]);
            }
            $oddsData     = $r122b['user'];
            $systemPrompt = $r122b['system'];
            \Log::info('[R122-PROMPT] 2nd AI へ r12.2 の本文で送ります', [
                'race_id'       => $r122b['race_id'],
                'system_sha256' => $r122b['system_sha256'],
                'snapshot_hash' => $r122b['snapshot_hash'],
                'user_bytes'    => $r122b['user_bytes'],
            ]);

            // @ANCHOR-20261020-R122-QUEUE  予約を確定してから送ります。
            //   保存済み回答を使い回すとき（$maxRetries=0）は送らないので
            //   枠も取りません。
            if ($maxRetries > 0) {
                $r122q2 = $this->r122QueueReserve($date, $kaisuu, $basho, $day, $race,
                                                  '2nd', $r122b);
                if (!$r122q2['skip'] && !$r122q2['ok'] && $r122q2['shadow']) {
                    // @ANCHOR-20261020-R122-SHADOW  記録だけ諦めて送ります
                    \Log::error('[R122-QUEUE] 枠を取れませんでした（shadow なので2nd AIは送ります）', [
                        'date' => $date, 'kaisuu' => $kaisuu, 'basho' => $basho,
                        'day'  => $day,  'race'   => $race,
                        'code' => $r122q2['code'], 'reason' => $r122q2['reason'],
                    ]);
                }
                if (!$r122q2['skip'] && !$r122q2['ok'] && !$r122q2['shadow']) {
                    \Log::error('[R122-QUEUE] 枠を予約できないため2nd AIを呼びません', [
                        'date' => $date, 'kaisuu' => $kaisuu, 'basho' => $basho,
                        'day'  => $day,  'race'   => $race,
                        'code' => $r122q2['code'], 'reason' => $r122q2['reason'],
                    ]);
                    // 1st AI 単独で続けます（正常な他AIを失わない：契約6章）
                    $maxRetries       = 0;
                    $b7SecondAiFailed = true;
                }
            }
        }

        for ($attempt = 0; $attempt < $maxRetries; $attempt++) {
            $aiElapsed2ndStart = microtime(true);   // @ANCHOR-20261006-AI-ELAPSED
            // ══════════════════════════════════════════════════════════════
            // @ANCHOR-20261013-V04-HV-TOKENS  研究用H/Vを頼むときだけ出力上限を上げる
            // ══════════════════════════════════════════════════════════════
            //   deepseek-chat は max_tokens を指定しないと出力が既定4,096トークンで
            //   打ち切られる。研究用H/Vは全出走馬（最大18頭）×10項目＋証拠なので、
            //   現行の回答（約3,800バイト）に足すと上限に当たってJSONが途中で切れる。
            //   H/V依頼がOFFのときはキー自体を付けないので、本番の送信内容は変わらない。
            // @ANCHOR-20261014-EVIDENCE-AUDIT2  依頼書②：2nd送信文のハッシュを残す
            self::recordPromptHash('2nd', (string) $oddsData);
            self::recordPromptHash('2nd_system', (string) $systemPrompt);

            $dsPayload = [
                'model'    => 'deepseek-chat',
                'messages' => [
                    ['role' => 'system', 'content' => $systemPrompt],
                    ['role' => 'user',   'content' => $oddsData],
                ],
            ];
            // @ANCHOR-20261020-R122-DEADLINE  2nd AI も応答期限から決めます
            $dsTimeout = $this->r122AiTimeout(60, $r122q2 ?? null);
            if (self::v04HvPrompt()) {
                $dsPayload['max_tokens'] = 8192;   // deepseek-chat の上限
                $dsTimeout = $this->r122AiTimeout(120, $r122q2 ?? null);
            }
            $response = Http::timeout($dsTimeout)->withHeaders([
                'Authorization' => 'Bearer ' . env('DEEPSEEK_API_KEY'),
            ])->post('https://api.deepseek.com/v1/chat/completions', $dsPayload);

            if ($response->failed()) {
                \Log::error('[B-7] DeepSeek API通信エラー', [
                    'status'  => $response->status(),
                    'body'    => $response->body(),
                    'attempt' => $attempt + 1,
                    'date' => $date, 'kaisuu' => $kaisuu, 'basho' => $basho, 'day' => $day, 'race' => $race,
                ]);
                if ($attempt < $maxRetries - 1) {
                    continue; // ※ maxRetries=1 のため実質到達しない
                }
                // @ANCHOR-20261020-R122-QUEUE  明確な失敗が返ったので FAILED にします
                if (isset($r122q2)) {
                    $this->r122QueueFail($r122q2,
                        '2nd AI の API エラー status=' . $response->status(), false);
                }
                // 全リトライ失敗 → 2nd AI失敗確定
                $b7SecondAiFailed = true;
//                 \Log::warning('[B-7] DeepSeek全リトライ失敗、1st AI単独継続', [
//                     'date' => $date, 'kaisuu' => $kaisuu, 'basho' => $basho, 'day' => $day, 'race' => $race,
//                 ]);
                break;
            }

            // @ANCHOR-20261006-AI-ELAPSED  2nd AI の応答時間も毎回記録する
            // @ANCHOR-20261017-ELAPSED-LEVEL  同上
            \Log::error('[AI_ELAPSED] 2nd AI 応答時間', [
                'race'     => "{$date} {$kaisuu}回{$basho} {$day}日目 {$race}R",
                '出走頭数' => $horseCount2nd ?? null,
                '秒'       => round(microtime(true) - $aiElapsed2ndStart, 2),
                'モデル'   => 'deepseek-chat',
                'プロンプト文字数' => mb_strlen($oddsData),
            ]);
            $result       = $response->json();
            $analysisText = trim($result['choices'][0]['message']['content'] ?? '');
            // @ANCHOR-20261013-V04-HV-TOKENS  出力が上限で打ち切られたら必ず表に出す
            $dsFinish = $result['choices'][0]['finish_reason'] ?? null;
            // @ANCHOR-20261020-R122-QUEUE  原応答と complete を保存します
            if (isset($r122q2)) {
                $this->r122QueueReceive($r122q2, $analysisText,
                    ($dsFinish === null || $dsFinish === 'stop')
                    && trim($analysisText) !== '');
            }
            if ($dsFinish !== null && $dsFinish !== 'stop') {
                \Log::error('[B-7] DeepSeekの回答が途中で終わっている（finish_reason）', [
                    'finish_reason' => $dsFinish,
                    '出力トークン'  => $result['usage']['completion_tokens'] ?? null,
                    'max_tokens指定' => $dsPayload['max_tokens'] ?? '未指定（既定4096）',
                    'race' => "{$date} {$kaisuu}回{$basho} {$day}日目 {$race}R",
                    '対処' => 'max_tokens を上げる、または依頼する項目を減らす',
                ]);
            }
            // @ANCHOR-20261004-DRY-RUN  試算モードは保存しないため、ここで保持しておく
            if (self::$dryRunNoPersist) {
                self::$dryRunSecondText = $analysisText;
            }

            // 【20260928 仕様（よっしー20260928指摘）】
            //   「候補なし|0」は形式外マーカー。出力させない指示に変えたうえで、
            //   届いた場合は形式不正として記録し、候補なし扱いでレースを続行する。
            //   @ANCHOR-20260928-SECOND-EMPTY-IS-NORMAL
            if (preg_match('/^候補なし\|0$/mu', $analysisText)) {
                \Log::warning('[B-7] DeepSeek回答に形式外マーカー「候補なし|0」（候補なし扱いで続行）', [
                    'date' => $date, 'kaisuu' => $kaisuu, 'basho' => $basho, 'day' => $day, 'race' => $race,
                ]);
                $analysisText     = '';
                $b7SecondAiFailed = true;
                break;
            }

            // ── 形式検証は「実際に候補行を読み取れるか」で判定する ──────────────
            // 【不具合と修正】以前は専用の正規表現 /馬番[：:]\d+/ で検証していたが、
            //   読み取り側の _parseAiHorses() は /馬番[：:]\s*(\d+).../ と
            //   コロンの後ろの空白を許容しており、条件が食い違っていた。
            //   そのため「馬番: 3、」のように半角スペースを挟んだ回答は、
            //   読み取れるにもかかわらず「形式不正」として捨てられ、
            //   2nd AI が毎レース無効化されて 1st AI 単独運用になっていた。
            //   検証と読み取りで同じメソッドを使えば、二度と食い違わない。
            // ※候補行の前に「厳選穴レース|0」等の余分な行があっても、
            //   候補行さえ読み取れれば正常として扱う（行単位で解析するため）。
            // 【20260928】空回答（候補行0件）は正常な候補なし。通信/API失敗や形式不正と区別する。
            if ($analysisText === '') {
                \Log::info('[B-7] DeepSeekが候補行0件の空回答（正常な候補なし）', [
                    'date' => $date, 'kaisuu' => $kaisuu, 'basho' => $basho, 'day' => $day, 'race' => $race,
                ]);
                break;   // $b7SecondAiFailed は false のまま（＝失敗ではない）
            }

            $b7ParsedHorses = $this->_parseAiHorses($analysisText);
            if (empty($b7ParsedHorses)) {
                // 非空なのに候補行を1行も読めない → 形式不正として記録（再試行禁止）
                \Log::warning('[B-7] DeepSeek回答の候補行がすべて不正（候補なし扱いで続行）', [
                    'date' => $date, 'kaisuu' => $kaisuu, 'basho' => $basho, 'day' => $day, 'race' => $race,
                    'text' => mb_substr($analysisText, 0, 2000),
                ]);
                $b7SecondAiFailed = true;
//                 \Log::warning('[B-7] DeepSeek形式不正（再試行禁止）、1st AI単独継続', [
//                     'date' => $date, 'kaisuu' => $kaisuu, 'basho' => $basho, 'day' => $day, 'race' => $race,
//                     // 原因が分かるよう全文に近い長さを残す（200字では1行目しか写らなかった）
//                     'text' => mb_substr($analysisText, 0, 2000),
//                 ]);
                break;
            }
//             \Log::info('[B-7] DeepSeek回答を受理', [
//                 'date' => $date, 'kaisuu' => $kaisuu, 'basho' => $basho, 'day' => $day, 'race' => $race,
//                 'parsed_cnt' => count($b7ParsedHorses),
//             ]);

            break; // 正常回答
        }

        // ─── 分析結果をDBに保存（常に保存：失敗テキストはログとして残す） ─────
        // @ANCHOR-20261004-DRY-RUN  試算モードでは保存しない
        // ══════════════════════════════════════════════════════════════════════
        // @ANCHOR-20261014-ALLSCORE-KEEP  2nd AIの全頭採点をDBに残す
        // ══════════════════════════════════════════════════════════════════════
        // 10/14（6回目）ご指摘⑤の調査で見つかりました。
        // 【旧実装の問題】
        //   1st AI は生の回答をそのまま保存しているのに、2nd AI だけ
        //   self::publicPart() を通して保存していました。
        //   publicPart() は内部監査用JSON（全頭採点）を落とすので、
        //   2nd の全頭採点が【DBに1件も残っていませんでした】。
        //   10月10〜12日の72レースすべてで「2nd 未受領」と出たのはこれが原因です。
        //   処理中は採点を使えていましたが、後から検証できない状態でした。
        //   仕様R08「候補0頭でも内部全頭JSONを必須」の証跡が2ndだけ欠けていました。
        // 【この変更】
        //   1st と同じく生の回答を保存します。画面へ出さないための publicPart() は
        //   応答を作るところ（下の return）と、ダンプ用APIの2か所で通します。
        //   DBに残すことと、画面へ出さないことは別の話なので分けました。
        if (!self::$dryRunNoPersist) DB::table('t_horse_odds_finder_ai_analysis2')->updateOrInsert(
            ['date' => $date, 'kaisuu' => $kaisuu, 'basho_code' => $basho, 'day' => $day, 'race' => $race],
            [
                'basho'         => $raceRow->basho_name,
                'race_name'     => $raceRow->race_name,
                'analysis_text' => $analysisText,   // 生のまま保存（全頭採点を残す）
            ]
        );
        // 全頭採点が入っていなければ、仕様R08違反として必ず表に出す
        {
            $akRep = self::allScoreReport((string) $analysisText);
            if (!$akRep['received']) {
                \Log::error('[ALLSCORE_MISSING] 2nd AIの全頭採点が受け取れていない（@ANCHOR-20261014-ALLSCORE-KEEP）', [
                    'race'   => "{$date} {$kaisuu}回{$basho} {$day}日目 {$race}R",
                    '理由'   => $akRep['reason'],
                    '対処'   => '公開は止めない。採点は採用しない（UNDETERMINED）',
                ]);
            }
        }
        // B-7: $b7SecondAiFailed の場合は以降の2nd AI処理をスキップし、1st AI単独で統合処理する

        // ─── 1st AI テキスト取得 → 統合処理 ────────────────────────────────
        $firstAiRecord = DB::table('t_horse_odds_finder_ai_analysis')
            ->where('date',       $date)
            ->where('kaisuu',     $kaisuu)
            ->where('basho_code', $basho)
            ->where('day',        $day)
            ->where('race',       $race)
            ->first(['analysis_text']);
        $firstAiText = $firstAiRecord->analysis_text ?? '';
        // @ANCHOR-20261004-DRY-RUN  試算モードは保存していないので受け渡しから取る
        // @ANCHOR-20261005-DRY-REUSE-PRIORITY
        //   条件C（呼び直した回答を使い回して配分だけ変える）は $dryRunForceFresh が
        //   false になるため、ここで保存済みの旧回答を読んでしまっていた。
        //   旧回答には全頭採点JSONが無いので、Cだけ「採点なし」になっていた。
        //   試算モードで受け渡された1st回答があるなら、常にそれを使う。
        if (self::$dryRunNoPersist && self::$dryRunFirstText !== null) {
            $firstAiText = self::$dryRunFirstText;
        }

        // 断層タイプ・主断層位置は AI実行前（Block 10前処理）で設定済み
        // $gapTypeForMerge・$primaryGapUpperPopForMerge をそのまま利用する
        // 人気帯別上限テーブル（_getAiAnalysisPrompt() と同一ロジック）
        if ($primaryGapUpperPopForMerge === null) {
            [$mergeUpperMax, $mergeMidMax, $mergeLowerMax] = [3, 3, 2];
        } elseif ($primaryGapUpperPopForMerge === 1) {
            [$mergeUpperMax, $mergeMidMax, $mergeLowerMax] = [3, 2, 1];
        } elseif ($primaryGapUpperPopForMerge <= 4) {
            [$mergeUpperMax, $mergeMidMax, $mergeLowerMax] = [4, 2, 1];
        } elseif ($primaryGapUpperPopForMerge === 5) {
            [$mergeUpperMax, $mergeMidMax, $mergeLowerMax] = [3, 3, 2];
        } else {
            [$mergeUpperMax, $mergeMidMax, $mergeLowerMax] = [2, 3, 2];
        }

        // ── 1st AI の回答判定（#65・#66）──────────────────────────────────────
        // 失敗（空・形式不正・必要な2行が無い）なら通常予測を公開しない。
        // 2nd AI だけの候補を公開してはいけない。
        $b66First = $this->_judgeFirstAiResponse($firstAiText);
        if ($b66First['status'] === 'failed') {
            \Log::error('[B-7/#66] 1st AI 回答失敗 → 通常予測を公開しない（制御済みエラー）', [
                'reason'         => $b66First['reason'],
                'has_upset_line' => $b66First['has_upset_line'],
                'has_index_line' => $b66First['has_index_line'],
                'second_ai_cnt'  => count($this->_parseAiHorses($b7SecondAiFailed ? '' : $analysisText)),
                'date' => $date, 'kaisuu' => $kaisuu, 'basho' => $basho, 'day' => $day, 'race' => $race,
                'raw_text'       => mb_substr($firstAiText, 0, 2000),
            ]);
            // 【20261004 よっしー回答③A】
            //   「なお無効なら有効な他方を使い、両方無効なら未確定表示とし、
            //     HTTP500にはしないでください。」
            //   → HTTP 500 を廃止し、未確定（undetermined）として200で返す。
            //     捏造した予想は出さない（仕様書9.2 表11「両AI無効」）。
            //   ※アプリ側の未確定カードは未着手（申告事項C-1）。
            //     現状は候補0件・未確定フラグつきの正常レスポンスになる。
            //   @ANCHOR-20261004-NO-HTTP500-UNDETERMINED
            $this->_saveUndetermined($date, $kaisuu, $basho, $day, $race,
                '1st AIの回答を採用できない（両AI無効）', [
                    '1st判定'   => $b66First['reason'] ?? '',
                    '2nd候補数' => count($this->_parseAiHorses($b7SecondAiFailed ? '' : $analysisText)),
                ]);
            return response()->json(['data' => [
                'date'          => $date,
                'kaisuu'        => $kaisuu,
                'basho_code'    => $basho,
                'day'           => $day,
                'race'          => $race,
                'analysis_text' => '',
                'merged_horses' => [],
                'upset_race'    => null,
                'status'        => 'undetermined',
                'status_reason' => '1st AIの回答を取得できませんでした（未確定）',
            ]]);
        }
        if ($b66First['status'] === 'zero') {
//             \Log::info('[B-7/#65] 1st AI 候補0頭（正常）', [
//                 'date' => $date, 'kaisuu' => $kaisuu, 'basho' => $basho, 'day' => $day, 'race' => $race,
//             ]);
        }

        $firstAiHorses  = $this->_parseAiHorses($firstAiText);
        $secondAiHorses = $this->_parseAiHorses($b7SecondAiFailed ? '' : $analysisText);

        // ── Block 9 Session 11: 能力適性グレードの抽出・スコア補正 ─────────────────
        $this->_applyAbilityGrade($secondAiHorses);
        // ── Block 9 Session 11 End ─────────────────────────────────────────────────

        // ── Block 6: F1〜F8フラグ計算（_mergeAiResults に渡す） ──────────────────
        // 【20260924 修正】フラグは 2nd AI の馬だけでなく 1st AI の馬にも計算する。
        //   5点以内の入れ替え判定では「独自発見馬」と「現在の最下位候補（1st独自馬のこともある）」を
        //   比べるため、相手側のフラグが無いと常に独自発見馬が優れている扱いになっていた。
        $b6FlagHorses = $secondAiHorses;
        $b6FlagNums   = array_column($secondAiHorses, 'num');
        foreach ($firstAiHorses as $b6fh) {
            if (!in_array($b6fh['num'], $b6FlagNums, true)) {
                $b6FlagHorses[] = $b6fh;
                $b6FlagNums[]   = $b6fh['num'];
            }
        }
        [
            'horseFlagsMap'   => $horseFlagsMap,
            'oddsHorseBlocks' => $oddsHorseBlocks,
            'b6OddsRows'      => $b6OddsRows,
            'b6TanPopMap'     => $b6TanPopMap,
            'b6FukuPopMap'    => $b6FukuPopMap,
        ] = $this->_buildFlagsAndOddsMap($b6FlagHorses, $oddsData, $date, $kaisuu, $basho, $day, $race);
        // ── Block 6 End ───────────────────────────────────────────────────────────

        // ── Block 10: 市場妙味基礎点（#17 仕様書準拠: AI実行前に算出済み）────────────
        // $b8InfoMap, $b10TotalScoreMap, $b13UnderevalFlagMap, $b13ScoreAMap, $b10ScoreE は
        // AI呼び出し前（Block 10前処理ブロック）で _calcMarketScore() により算出済み。
        // ── F1/F5 更新（Block 10 算出後、merge前）───────────────────────────────
        foreach (array_keys($horseFlagsMap) as $_hfNum) {
            $horseFlagsMap[$_hfNum]['F1'] = (($b13ScoreAMap[$_hfNum] ?? -1) >= 12);
            // 【20260924 修正】F5 は仕様「市場妙味基礎点Eが6点以上」＝馬ごとのE点で判定する。
            //   旧実装はレース単位の断層タイプ点（A=1/B=3/C=5/D=8/E=15）で判定しており、
            //   タイプD/Eのレースでは全馬がF5成立、タイプA〜Cでは全馬が不成立になっていた。
            $horseFlagsMap[$_hfNum]['F5'] = (($b10ScoreEMap[$_hfNum] ?? null) !== null && $b10ScoreEMap[$_hfNum] >= 6);
        }
        // ── Block 10 End ──────────────────────────────────────────────────────────

        // ── Block 16: ⑥ AI回答のDB照合強化 ──────────────────────────────────────────
        // 実在馬番・重複・人気順・6分前オッズ・おすすめ度(0〜100) をDBと照合し、
        // 不正エントリを除去・DB値で上書きする。$b6TanPopMap / $b6OddsRows を利用。
        {
            // 6分前オッズマップ (num => odds)
            $_b16OddsMap = [];
            foreach ($b6OddsRows as $_b16or) {
                $_b16OddsMap[(int)$_b16or->num] = (float)$_b16or->odds;
            }
            // 実在馬番セット
            $_b16ValidNums = array_keys($b6TanPopMap); // numは int

            $this->_dbValidateHorses($firstAiHorses,  '1st', $_b16ValidNums, $b6TanPopMap, $_b16OddsMap);
            $this->_dbValidateHorses($secondAiHorses, '2nd', $_b16ValidNums, $b6TanPopMap, $_b16OddsMap);

            // ══════════════════════════════════════════════════════════════════
            // @ANCHOR-20261005-AUX-NEVER-BREAKS  全頭採点まわりで予想を落とさない
            // ══════════════════════════════════════════════════════════════════
            // 全頭採点の取得・検証と修正要求（AIへの投げ直し）は20261004で追加した
            // 新しい経路。修正要求は外部APIを叩くため、通信エラーや想定外の応答で
            // 例外になり得る。ここで落ちると候補を捨ててしまうので個別に囲む。
            // 採点が取れなければ「採点なし」として進む（統合のタイブレークに
            // 使わないだけで、候補そのものには影響しない）。
            $allScore1st = ['ok' => false, 'horses' => [], 'errors' => ['未取得']];
            $allScore2nd = ['ok' => false, 'horses' => [], 'errors' => ['未取得']];
            try {
            // ── @ANCHOR-20261004-AUDIT-ALLSCORE  全頭採点（内部用JSON）の取得と検証 ──
            //   よっしー20261004回答③A。DB照合のあとに実行する
            //   （候補行のおすすめ度がDB値で確定した状態で突き合わせるため）。
            $b16FirstJson  = self::splitAuditJson((string) $firstAiText)['json'];
            $b16SecondJson = self::splitAuditJson((string) ($b7SecondAiFailed ? '' : $analysisText))['json'];
            $allScore1st = $this->_parseAllHorseScores($b16FirstJson,  $_b16ValidNums, $firstAiHorses,  '1st');
            $allScore2nd = $this->_parseAllHorseScores($b16SecondJson, $_b16ValidNums, $secondAiHorses, '2nd');

            // ── @ANCHOR-20261004-FIX-REQUEST  修正要求（該当AIにつき1回まで）────
            //   よっしー20261004回答③A。通常の2回とは別枠の例外。
            //   ・AIが回答自体を返していない場合は送らない（直すものが無い）
            //   ・--remerge（保存済み回答の再マージ）では送らない（AI呼び出し0回を守る）
            //   ・1回だけ送って再検証し、なお無効なら当該回答を採用しない
            $b16RaceLabel = "{$date} {$kaisuu}回{$basho} {$day}日目 {$race}R";
            $b16FixCount  = ['1st' => 0, '2nd' => 0];
            if (!$b2Remerge) {
                // @ANCHOR-20261006-SCORE-SOURCE-OF-TRUTH
                //   不一致・欠落も修正要求の対象にする（20261006 ご指摘②）。
                if ($allScore1st['needs_fix'] && trim((string) self::publicPart((string) $firstAiText)) !== '') {
                    $b16FixCount['1st'] = 1;
                    $b16Why1 = array_merge($allScore1st['errors'], $allScore1st['warnings']);
                    $b16Fixed = $this->_requestScoreFix(
                        '1st', $firstPromptRaw, (string) $firstAiText,
                        $b16Why1, $b16RaceLabel
                    );
                    if ($b16Fixed !== null) {
                        $b16Retry = $this->_parseAllHorseScores($b16Fixed, $_b16ValidNums, $firstAiHorses, '1st(修正後)');
                        // 読める採点になっていれば採用する。
                        //   なお不一致が残る馬は $b16Retry 側で未検証になっているので、
                        //   補充順位には使われない（公開候補行はそのまま残る）。
                        if ($b16Retry['ok']) {
                            $allScore1st = $b16Retry;
                            \Log::info('[FIX_REQUEST] 1st の全頭採点を修正後の内容で採用', [
                                'race' => $b16RaceLabel,
                                '残った不一致' => $b16Retry['mismatch'],
                                '全頭採点完了' => $b16Retry['complete'] ? 'はい' : 'いいえ',
                            ]);
                        } else {
                            \Log::warning('[FIX_REQUEST] 1st は修正後も読めない → 当該回答の全頭採点は採用しない', [
                                'race' => $b16RaceLabel, 'エラー' => $b16Retry['errors'],
                            ]);
                        }
                    }
                }
                // @ANCHOR-20261006-SCORE-SOURCE-OF-TRUTH
                if ($allScore2nd['needs_fix'] && !$b7SecondAiFailed && trim((string) self::publicPart((string) $analysisText)) !== '') {
                    $b16FixCount['2nd'] = 1;
                    $b16Why2 = array_merge($allScore2nd['errors'], $allScore2nd['warnings']);
                    $b16Fixed2 = $this->_requestScoreFix(
                        '2nd', $oddsData, (string) $analysisText,
                        $b16Why2, $b16RaceLabel
                    );
                    if ($b16Fixed2 !== null) {
                        $b16Retry2 = $this->_parseAllHorseScores($b16Fixed2, $_b16ValidNums, $secondAiHorses, '2nd(修正後)');
                        if ($b16Retry2['ok']) {
                            $allScore2nd = $b16Retry2;
                            \Log::info('[FIX_REQUEST] 2nd の全頭採点を修正後の内容で採用', [
                                'race' => $b16RaceLabel,
                                '残った不一致' => $b16Retry2['mismatch'],
                                '全頭採点完了' => $b16Retry2['complete'] ? 'はい' : 'いいえ',
                            ]);
                        } else {
                            \Log::warning('[FIX_REQUEST] 2nd は修正後も読めない → 当該回答の全頭採点は採用しない', [
                                'race' => $b16RaceLabel, 'エラー' => $b16Retry2['errors'],
                            ]);
                        }
                    }
                }
            }
            \Log::info('[AUDIT_AI] AI呼び出し回数の内訳（@ANCHOR-20261004-FIX-REQUEST）', [
                'race'         => $b16RaceLabel,
                '通常'         => $b2Remerge ? '0回（--remergeのため保存済み回答を再利用）' : '2回（1st・2nd各1回）',
                '修正要求1st'  => $b16FixCount['1st'] . '回',
                '修正要求2nd'  => $b16FixCount['2nd'] . '回',
                '上限'         => '修正要求は該当AIにつき1回まで（通常の2回とは別枠）',
            ]);
            } catch (\Throwable $asE) {
                // @ANCHOR-20261005-AUX-NEVER-BREAKS
                \Log::error('[AUDIT_ALLSCORE] 全頭採点の取得・検証で例外（採点なしとして続行）', [
                    'race'    => "{$date} {$kaisuu}回{$basho} {$day}日目 {$race}R",
                    'message' => $asE->getMessage(),
                    'file'    => $asE->getFile() . ':' . $asE->getLine(),
                    '影響'    => '統合のタイブレークとPHP候補生成に使えないだけ。候補そのものは通常どおり',
                ]);
            }

            // 信頼度小計を統合のタイブレーク（仕様書6.2の最後の段）へ渡す。
            //   取得できなかった馬は値を付けない（0や推測値で補わない・仕様書6.3）。
            //   @ANCHOR-20261006-SCORE-SOURCE-OF-TRUTH
            //   検証済み（公開候補行と総合点が一致）の馬だけを使う。
            foreach ($firstAiHorses as &$asH1) {
                $asN1 = (int) $asH1['num'];
                if ($allScore1st['ok'] && !empty($allScore1st['horses'][$asN1]['verified'])) {
                    $asH1['conf_1st'] = $allScore1st['horses'][$asN1]['conf_sub'];
                }
            }
            unset($asH1);
            foreach ($secondAiHorses as &$asH2) {
                $asN2 = (int) $asH2['num'];
                if ($allScore2nd['ok'] && !empty($allScore2nd['horses'][$asN2]['verified'])) {
                    $asH2['conf_2nd'] = $allScore2nd['horses'][$asN2]['conf_sub'];
                }
            }
            unset($asH2);

            // ── 監査ログ【AI単位】（仕様書9.1 表10）────────────────────────────
            //   全11項目得点・小計・総合・順位・候補か・能力不明の処理を保存する。
            //   生応答は既に analysis_text（ai_analysis / ai_analysis2）に保存済み。
            $b16AiAudit = [];
            foreach ([['1st', $allScore1st, $firstAiHorses], ['2nd', $allScore2nd, $secondAiHorses]] as [$asLbl, $asRes, $asPub]) {
                $asPubNums = array_map(static fn($x) => (int) $x['num'], $asPub);
                // 総合点の降順・同点は馬番昇順で全頭順位を付ける
                $asRows = $asRes['horses'];
                uksort($asRows, static function ($a, $b) use ($asRows) {
                    if ($asRows[$a]['total'] !== $asRows[$b]['total']) {
                        return $asRows[$b]['total'] <=> $asRows[$a]['total'];
                    }
                    return $a <=> $b;
                });
                $asRank = 0; $asDetail = [];
                foreach ($asRows as $asNum => $asRow) {
                    $asRank++;
                    $asDetail[$asNum] = [
                        '信頼度7項目' => $asRow['conf_items'],
                        '信頼度小計' => $asRow['conf_sub'],
                        '妙味4項目'  => $asRow['merit_items'],
                        '妙味小計'   => $asRow['merit_sub'],
                        '総合'       => $asRow['total'],
                        '全頭順位'   => $asRank,
                        '候補か'     => in_array($asNum, $asPubNums, true),
                        '能力適性'   => $asRow['ability'],
                        '能力不明の処理' => ($asRow['ability'] === null)
                            ? '不明（採点不可）のまま。0点・D評価・減点・除外の理由にしない'
                            : '採点あり',
                    ];
                }
                $b16AiAudit[$asLbl] = [
                    '判定'       => $asRes['ok'] ? 'OK' : 'NG',
                    // @ANCHOR-20261006-SCORE-SOURCE-OF-TRUTH
                    '全頭採点完了'   => !empty($asRes['complete']) ? 'はい' : 'いいえ',
                    '検証済み頭数'   => count(array_filter($asRes['horses'] ?? [], static fn($h) => !empty($h['verified']))),
                    '未検証'         => $asRes['unverified'] ?? [],
                    '候補行との不一致数' => $asRes['mismatch'] ?? 0,
                    '修正要求の対象' => !empty($asRes['needs_fix']) ? 'はい' : 'いいえ',
                    'エラー'     => $asRes['errors'],
                    // @ANCHOR-20261005-ALLSCORE-WARN  警告は提出物に必ず載せる
                    '警告'       => $asRes['warnings'] ?? [],
                    '欠落'       => $asRes['missing'],
                    '重複'       => $asRes['duplicated'],
                    '実在しない馬番' => $asRes['extra'],
                    '公開候補数' => count($asPubNums),
                    '全頭'       => $asDetail,
                ];
            }
            \Log::info('[AUDIT_AI] AI単位の監査ログ（@ANCHOR-20261004-AUDIT-ALLSCORE）', [
                'race' => "{$date} {$kaisuu}回{$basho} {$day}日目 {$race}R",
                '版'   => self::ALLOC_SPEC_VERSION,
                'AI'   => $b16AiAudit,
            ]);
            self::auditFile('AUDIT_AI', [
                'race' => "{$date} {$kaisuu}回{$basho} {$day}日目 {$race}R",
                '版'   => self::ALLOC_SPEC_VERSION,
                'AI'   => $b16AiAudit,
            ]);
        }
        // ── Block 16 End ──────────────────────────────────────────────────────────

        // ── 【20260928】順序について ────────────────────────────────────────────
        //   仕様（AI応答の検証）は「候補行ごとに検証 → 不正な行だけ無効化 →
        //   候補上限超過時に決定論的な上限処理」の順を定めている。
        //   B-15（上限処理）を Block 16（DB照合）より前に置くと、
        //   実在しない馬番や重複行が枠を先取りし、検証後に消えて
        //   目標数を下回る事故が起きるため、必ずこの順序で実行する。
        // ── B-15: AI回答の候補上限処理（決定論的な絞り込み・再試行禁止）──────────
        // 【20260928 レース停止回避追補（よっしー20260928指摘）】
        //   旧実装は 1st AI が8頭以上で HTTP 500、2nd AI が6頭以上で回答ごと無効化していた。
        //   仕様は「過剰行や重複行があっても回答全体やレースを停止しない」
        //   「超過行は不採用として原文・理由をログへ残す」に変わったため、
        //   上限まで決定論的に絞り込み、レースはそのまま続行する。
        //   @ANCHOR-20260928-NO-RACE-STOP / @ANCHOR-20260928-TRIM-OVER-LIMIT
        $b15RaceCtx     = ['date' => $date, 'kaisuu' => $kaisuu, 'basho' => $basho,
                           'day'  => $day,  'race'   => $race];
        $b15TargetCount = self::targetSelectionCount((int) $horseCount2nd);

        $firstAiHorses  = $this->_trimAiCandidates(
            $firstAiHorses,  $b15TargetCount, $protectedLongshotForMerge,
            $b15TargetCount, '1st AI（Claude）',   $b15RaceCtx
        );
        $secondAiHorses = $this->_trimAiCandidates(
            $secondAiHorses, 5,               $protectedLongshotForMerge,
            $b15TargetCount, '2nd AI（DeepSeek）', $b15RaceCtx
        );

        // ── 候補不足は記録だけ残して続行する（公開停止・HTTP 500 は禁止）──────────
        if (count($firstAiHorses) < $b15TargetCount) {
            \Log::warning('[PREDICTION_PARTIAL] 1st AI の候補が目標数Cに不足（有効候補で続行）', $b15RaceCtx + [
                '実出走頭数N' => (int) $horseCount2nd,
                '目標数C'     => $b15TargetCount,
                '候補行数'    => count($firstAiHorses),
                '不足数'      => $b15TargetCount - count($firstAiHorses),
                'raw_text'    => mb_substr($firstAiText, 0, 500),
            ]);
        }
        if (empty($firstAiHorses) && empty($secondAiHorses)) {
            \Log::warning('[NO_VALID_CANDIDATES] 両AIから有効候補が得られない（候補行0件でレース情報を返す）', $b15RaceCtx + [
                '実出走頭数N' => (int) $horseCount2nd,
                '目標数C'     => $b15TargetCount,
            ]);
        }


        // ── Block 13b・13a・12: _mergeAiResults() 後に適用（正規仕様）──────────────
        // 仕様: 統合→統合おすすめ度算出→最低基準点→低配当除外→回収率フィルター→順位確定
        // 統合スコア（一致馬+5点ボーナス）算出後・上限適用前にフィルターをかけるため
        // 実装は下記「候補絞り込みフィルター」（_mergeAiResults 内の Step4b で実行）にある。

        // ⑧ 大穴進入度: 4〜5番人気間断層 + 大穴進入度1〜2 → mergeLowerMax=0
        // ⑨ 波乱度は 1st AI のみ参照（merge前に先取り）
        $_earlyBigGap = null;
        if (preg_match(
            '/レース指標\|波乱度[:：\s]*(\d+)\|下位進入度[:：\s]*(\d+)\|大穴進入度[:：\s]*(\d+)/u',
            $firstAiText, $_egm
        )) {
            $_earlyBigGap = (int)$_egm[3];
        }
        // 【20260924 修正】仕様「大穴進入度1〜2：11番人気以下は原則0頭。3なら最大1頭、4〜5なら上表の最大値まで」
        //   旧実装は 1〜5番人気間の断層のときだけ 0頭にしていた。断層位置に関係なく適用する。
        if ($_earlyBigGap !== null && $_earlyBigGap <= 2) {
            $mergeLowerMax = 0;
        } elseif ($_earlyBigGap === 3) {
            $mergeLowerMax = min($mergeLowerMax, 1);
        }

        // ══════════════════════════════════════════════════════════════════════════
        // 候補絞り込みフィルター（Block13b → #69 → Block13a → Block12）
        // 【20260924 修正】仕様【最終PHP処理順序】どおり「最低基準→低配当除外→回収率フィルター」を
        //   人気帯上限・出走頭数上限より【前】に適用する。
        //   旧実装は上限で候補を絞った【後】にこれらで除外していたため、
        //   除外された馬の枠が空いたまま繰り上がらず、本来残るはずの馬が表示されなかった。
        //   ここではフィルター処理を関数として用意し、_mergeAiResults の中（分類・統合おすすめ度の算出直後、
        //   独自発見枠判定・順位付け・上限適用の前）で呼び出す。判定内容そのものは変更していない。
        // ══════════════════════════════════════════════════════════════════════════
        $b69MeritCap = [];
        // ── よっしー20260926指摘【今回の確認ログ】: 各段階の頭数を記録する ──
        $b13Stats = [
            'after_min_score'   => null, // ② 最低基準点の通過数
            'low_payout_hit'    => 0,    // ③ 低配当条件に該当した数
            'recovery_avoid'    => 0,    // ④ 回収率で購入回避となった数
        ];
        $b13PreCapFilter = function (array $horses) use ($oddsHorseBlocks, $primaryGapUpperPopForMerge, $b13ScoreAMap, &$b69MeritCap, &$b13Stats,
                                                        $gapTypeForMerge, $b10ScoreEMap, $horseFlagsMap): array {

            // ── Block 13b: 最低基準点【フラグ化】（merge後・統合スコアで判定）────────
            // 【20260927 仕様変更（よっしー20260927指摘）】
            //   目標数C頭を目指す方針に変わったため、ここでの【除外】を廃止した。
            //   最低基準点は候補から削るハード条件ではなく、
            //   「第1パスで優先しない」順位材料（優先目安）として使う。
            //   @ANCHOR-20260927-NO-HARD-EXCLUDE
            {
                $b13bPassed = 0;
                $horses = array_values(array_map(function ($h) use (&$b13bPassed) {
                    $score = (float)($h['score'] ?? 0);
                    $pop   = (int)($h['popularity'] ?? 999);

                    $required = ($pop >= 11) ? 55.0 : (($pop >= 1 && $pop <= 10) ? 60.0 : 70.0);
                    $ok       = ($score >= 70.0) || ($score >= $required);

                    $h['min_score_required'] = $required;
                    $h['below_min_score']    = $ok ? 0 : 1;

                    if ($ok) {
                        $b13bPassed++;
                    } else {
                        \Log::info('[Block13b] 最低基準点未満（候補には残す／優先度を下げる）', [
                            'num'      => $h['num'], 'name' => $h['name'],
                            'score'    => $score,    'popularity' => $pop,
                            'required' => $required,
                            'category' => $h['category'] ?? '',
                        ]);
                    }
                    return $h;
                }, $horses));
                $b13Stats['after_min_score'] = $b13bPassed;   // ② 最低基準点を満たした数
            }
            // ── Block 13b End ─────────────────────────────────────────────────────────

            // ── 【20260924 追加】11番人気以下（大穴）の選出条件をPHPでも確認する ─────────────
            // 仕様「11番人気以下（大穴）の選出条件」：以下を【全て】満たした馬のみ選出可能。
            //   （おすすめ度70点以上の本候補でも、11番人気以下なら同じ条件を満たす必要がある）
            //   ① おすすめ度55点以上                              … 上の最低基準で確認済み
            //   ② 複勝オッズが複数時点で継続低下（単発急落は不可）  … 市場妙味基礎点A（複勝継続流入）12点以上
            //   ③ 複勝流入ランクが7人気以下グループ内で1〜2位      … プロンプトの「複勝流入ランク: N位」
            //   ④ 単勝と複勝の両方で資金流入                      … 単勝が計測開始→6分前で2%超下落 かつ ②
            //   ⑤ 下位進入を裏付ける構造：断層なし（タイプD）・単複断層の矛盾（タイプE）・
            //      主断層が5〜6番人気間／6番人気以降・この馬に断層縮小／接近／単複不一致の根拠（基礎点E≥6）。
            //      タイプB・Cでも「強い継続流入（基礎点A=25点）＋客観的根拠（回収率110%・類似レース・予測補正OPIのいずれか）」
            //      が揃えば最大1頭まで比較可能。
            //   仕様【追加禁止事項】「不明値を0点、不振、条件未達と扱うこと」は禁止のため、
            //   データが無く確認できない条件は「不明」とし、それだけを理由に除外しない。
            //   確認できて「満たしていない」と分かった条件が1つでもあれば除外する。
            // 【20260927 仕様変更（よっしー20260927指摘）】
            //   目標数C頭を目指す方針に変わったため、ここでの【除外】をすべて廃止した。
            //   ・大穴条件の不成立          → buy_avoid_longshot フラグ（優先度を下げる材料）
            //   ・タイプB・C特例の1頭制限   → longshot_bc_special_rank（2頭目以降も候補に残す）
            //   @ANCHOR-20260927-NO-HARD-EXCLUDE
            {
                $b13dBcSpecial = []; // タイプB・Cの特例に該当した馬（順位材料として順序づけ）
                $horses = array_values(array_map(function ($h) use (
                    $oddsHorseBlocks, $primaryGapUpperPopForMerge, $b13ScoreAMap,
                    $gapTypeForMerge, $b10ScoreEMap, $horseFlagsMap, &$b13dBcSpecial
                ) {
                    $h['longshot_cond_ok']        = null;   // 10番人気以内は判定対象外
                    $h['buy_avoid_longshot']      = 0;
                    $h['longshot_bc_special']     = 0;

                    $pop = (int)($h['popularity'] ?? 0);
                    if ($pop < 11) return $h;                         // 10番人気以内は対象外

                    $num    = (int)$h['num'];
                    $block  = $oddsHorseBlocks[$num] ?? '';
                    $scoreA = $b13ScoreAMap[$num] ?? null;

                    // 各条件は true（満たす）/ false（満たさない）/ null（データ無しで不明）の3値
                    $c2 = ($scoreA === null) ? null : ($scoreA >= 12);
                    $c3 = preg_match('/複勝流入ランク: (\d+)位/u', $block, $m3) ? ((int)$m3[1] <= 2) : null;
                    $tanChange = $this->_parseTanChangeRate($block);
                    $tanIn = ($tanChange === null) ? null : ($tanChange < -2.0);
                    $c4 = ($c2 === false || $tanIn === false) ? false
                        : (($c2 === null || $tanIn === null) ? null : true);

                    $scoreE = $b10ScoreEMap[$num] ?? null;
                    if (in_array($gapTypeForMerge, ['D', 'E'], true)
                        || ($primaryGapUpperPopForMerge !== null && $primaryGapUpperPopForMerge >= 5)
                        || ($scoreE !== null && $scoreE >= 6)) {
                        $c5 = true;
                    } else {
                        $c5 = ($scoreE === null) ? null : false;
                    }

                    $h['longshot_cond_detail'] = [
                        'c2_複勝継続低下'   => $c2,
                        'c3_流入ランク1-2位' => $c3,
                        'c4_単複流入'        => $c4,
                        'c5_構造'            => $c5,
                    ];

                    // 「確認できて満たしていない」条件が1つも無ければ成立（不明は不成立にしない）
                    if ($c2 !== false && $c3 !== false && $c4 !== false && $c5 !== false) {
                        $h['longshot_cond_ok'] = 1;
                        return $h;
                    }

                    // タイプB・Cの特例（強い継続流入＋客観的根拠）: 構造条件だけが不成立の馬
                    if ($c2 === true && $c3 !== false && $c4 !== false && $c5 === false
                        && in_array($gapTypeForMerge, ['B', 'C'], true) && $scoreA === 25) {
                        $fl = $horseFlagsMap[$num] ?? [];
                        if (!empty($fl['F6']) || !empty($fl['F7']) || !empty($fl['F8'])) {
                            $h['longshot_cond_ok']    = 1;
                            $h['longshot_bc_special'] = 1;
                            $b13dBcSpecial[]          = $h;
                            return $h;
                        }
                    }

                    $h['longshot_cond_ok']   = 0;
                    $h['buy_avoid_longshot'] = 1;   // 馬券購入は見送り寄り。候補からは削除しない
                    \Log::info('[大穴選出条件] 11番人気以下の条件不足（候補には残す／優先度を下げる）', [
                        'num' => $num, 'name' => $h['name'] ?? '', 'popularity' => $pop, 'score' => $h['score'] ?? null,
                        'c2_複勝継続低下' => $c2, 'c3_流入ランク1-2位' => $c3, 'c4_単複流入' => $c4, 'c5_構造' => $c5,
                        'gap_type' => $gapTypeForMerge,
                    ]);
                    return $h;
                }, $horses));

                // 特例馬が2頭以上のときの序列づけ（おすすめ度降順・同点は馬番小）。
                // 【20260927】2頭目以降を除外していた処理を廃止し、順位材料（rank）だけを付ける。
                if (count($b13dBcSpecial) >= 2) {
                    usort($b13dBcSpecial, fn($a, $b) =>
                        $b['score'] !== $a['score'] ? $b['score'] <=> $a['score'] : $a['num'] <=> $b['num']);
                    $b13dRank = [];
                    foreach ($b13dBcSpecial as $b13dI => $b13dH) {
                        $b13dRank[(int)$b13dH['num']] = $b13dI + 1;
                    }
                    $horses = array_values(array_map(function ($h) use ($b13dRank) {
                        $h['longshot_bc_special_rank'] = $b13dRank[(int)$h['num']] ?? null;
                        return $h;
                    }, $horses));
                    \Log::info('[大穴選出条件] タイプB・C特例馬の序列（1頭制限は廃止）', [
                        'rank' => $b13dRank, 'gap_type' => $gapTypeForMerge,
                    ]);
                }
            }
            // ── 大穴選出条件 End ──────────────────────────────────────────────────────

            // ── 受入チェック #69: 妙味小計上限のPHP側検証（AI採点は書き換えない）──────
            // 仕様「推定確定複勝最小 < 1.5 の馬は妙味小計を原則5点以下」を、
            //   おすすめ度 = 信頼度(最大60) + 妙味小計 という固定内訳から検証する。
            //   例外解除なしの低配当馬が66点以上なら、妙味小計が5点を超えた証拠になる。
            // 検出結果はログと features_json（シャドー）へ保存する。
            $b69MeritCap = $this->_verifyLowPayoutMeritCap(
                $horses, $oddsHorseBlocks, $primaryGapUpperPopForMerge, $b13ScoreAMap
            );

            // ── Block 13a: 低配当【購入回避フラグ】（merge後・正規仕様）──────────────
            // 【20260926 仕様変更（よっしー指摘 01.txt 第4項）】
            //   以前はここで候補から【除外】していたが、5着以内候補の選出条件ではなく
            //   「馬券購入の見送り条件」として扱うよう変更された。
            //     ・推定確定複勝1.5倍未満 かつ 単勝3.0倍未満 の馬は購入価値が低い可能性がある
            //     ・しかし1〜3番人気など5着以内に来る根拠がある馬は候補行に残す
            //     ・低配当例外3条件は「候補に残す条件」ではなく
            //       「馬券購入を例外的に認める条件」として使う
            //   したがって candidates からは削除せず、フラグだけを立てる。
            // 判定条件（判定そのものは変更なし）:
            //   推定確定複勝最小 < 1.5倍 かつ 推定確定単勝（推定確定オッズ）< 3.0倍
            // 例外解除（次の3条件を【すべて】満たす場合のみ → 除外しない / AND判定）:
            //   例外①: 断層最上位グループ（人気順 <= 主断層上限人気）
            //   例外②: 単勝・複勝の両方が複数時点で継続流入
            //   例外③: サンプル30件以上の回収率110%以上が2種類以上
            // ※最新確定版仕様: 「例外解除は既存の低配当例外3条件をすべて満たす場合だけ」
            //   → OR判定は仕様違反。必ずAND（&&）で結合すること。
            // ※判定そのものは _judgeLowPayoutException() に集約してある。
            //   #69 の検証と同じ判定を使うため、両者が食い違うことはない。
            {
                $horses = array_values(array_map(
                    function ($h) use ($oddsHorseBlocks, $primaryGapUpperPopForMerge, $b13ScoreAMap, &$b13Stats) {
                        $b13aBlock = $oddsHorseBlocks[(int)$h['num']] ?? '';
                        $b13aJ = $this->_judgeLowPayoutException(
                            $h, $b13aBlock, $primaryGapUpperPopForMerge, $b13ScoreAMap
                        );

                        // 判定結果を馬ごとに保持する（候補からは削除しない）
                        $h['low_payout']          = $b13aJ['low_payout'] ? 1 : 0;
                        $h['low_payout_released'] = $b13aJ['released']   ? 1 : 0;
                        $h['low_payout_fuku_min'] = $b13aJ['fuku_min'];
                        $h['low_payout_tan_odds'] = $b13aJ['tan_odds'];

                        // 購入回避フラグ: 低配当に該当し、かつ例外3条件で解除されていない
                        $h['buy_avoid_low_payout'] =
                            ($b13aJ['low_payout'] && !$b13aJ['released']) ? 1 : 0;

                        if ($b13aJ['low_payout']) {
                            $b13Stats['low_payout_hit']++;   // ③ 低配当条件の該当数
                            \Log::info('[Block13a] 低配当該当（候補には残す）', [
                                'num'                => $h['num'],           'name'     => $h['name'],
                                'fuku_min'           => $b13aJ['fuku_min'],  'tan_odds' => $b13aJ['tan_odds'],
                                'ex1_最上位グループ' => $b13aJ['ex1'],
                                'ex2_単複継続流入'   => $b13aJ['ex2'],
                                'ex3_回収率110x2'    => $b13aJ['ex3'],
                                'released'           => $b13aJ['released'],
                                '購入判定'           => $b13aJ['released'] ? '購入可' : '見送り',
                            ]);
                        }
                        return $h;
                    },
                    $horses
                ));
            }
            // ── Block 13a End ─────────────────────────────────────────────────────────

            // ── Block 12: 回収率【購入回避フラグ】（merge後・統合馬リストに適用）────────
            // 【20260926 仕様変更（よっしー指摘 01.txt 第1項・第3項）】
            //   以前はここで候補から【ハード除外】していたが、5着以内候補の選出段階では
            //   回収率によるハード除外を行わないよう変更された。
            //     ・回収率はすでに「おすすめ度」の妙味項目12点に反映されている。
            //       候補除外まで重ねると二重評価になり、AIが選んだ馬がPHPで全消しになる。
            //     ・60% は「馬券購入回避」の暫定基準として残す。
            //       有効値（サンプル30件以上）が2種類以上あり、
            //       そのうち2種類以上が60%未満なら購入回避フラグを立てる。
            //     ・ただし候補行からは消さない。馬券判定を「見送り」「監視」にする。
            //   案A/B/C のうち【案C】を採用（減点のみ・ハード除外なし）。
            //   人気帯別の閾値は現時点では採用しない（全人気帯共通の60%）。
            // ※よっしー指摘【今回の確認ログ】に従い、馬ごとに3種類の回収率・サンプル数・
            //   閾値未満の個数を保持し、どの処理で何が起きたか追えるようにする。
            {
                foreach ($horses as &$b12mh) {
                    $b12mNum   = (int)$b12mh['num'];
                    $b12mBlock = $oddsHorseBlocks[$b12mNum] ?? '';
                    if ($b12mBlock === '') {
                        $b12mh['buy_avoid_recovery'] = 0;
                        $b12mh['recovery_detail']    = ['note' => 'オッズブロックなし'];
                        continue;
                    }
                    $b12mEntries = [];
                    if (preg_match(
                        '/過去回収率[（(][^）)]+[）)]: 回収率([\d.]+)%\s+勝率[\d.]+%\s+サンプル(\d+)件/u',
                        $b12mBlock, $b12me1
                    )) {
                        $b12mEntries[] = ['rate' => (float)$b12me1[1], 'samples' => (int)$b12me1[2]];
                    }
                    if (preg_match(
                        '/OPI帯別回収率[（(][^）)]+[）)]: 回収率([\d.]+)%\s+勝率[\d.]+%\s+サンプル(\d+)件/u',
                        $b12mBlock, $b12me2
                    )) {
                        $b12mEntries[] = ['rate' => (float)$b12me2[1], 'samples' => (int)$b12me2[2]];
                    }
                    if (preg_match(
                        '/フェーズパターン別回収率[（(][^）)]+[）)]: 回収率([\d.]+)%\s+勝率[\d.]+%\s+サンプル(\d+)件/u',
                        $b12mBlock, $b12me3
                    )) {
                        $b12mEntries[] = ['rate' => (float)$b12me3[1], 'samples' => (int)$b12me3[2]];
                    }
                    $b12mValid = array_values(array_filter($b12mEntries, fn($r) => $r['samples'] >= 30));
                    // @ANCHOR-20260926-B12-RECOVERY-THRESHOLD（閾値はクラス定数で一元管理）
                    $b12mLow   = array_values(array_filter(
                        $b12mValid,
                        fn($r) => $r['rate'] < self::B12_RECOVERY_LOW_THRESH
                    ));

                    // 購入回避フラグ（候補からは削除しない）
                    $b12mAvoid = (count($b12mValid) >= 2 && count($b12mLow) >= 2);
                    $b12mh['buy_avoid_recovery'] = $b12mAvoid ? 1 : 0;
                    $b12mh['recovery_detail']    = [
                        'rates'       => $b12mEntries,                  // 3種類の回収率とサンプル数
                        'valid_count' => count($b12mValid),             // サンプル30件以上の有効値の数
                        'low_count'   => count($b12mLow),               // うち閾値未満の数
                        'threshold'   => self::B12_RECOVERY_LOW_THRESH, // 判定に使った閾値
                    ];

                    if ($b12mAvoid) {
                        $b13Stats['recovery_avoid']++;   // ④ 回収率による購入回避数
                        \Log::info("[Block12] 回収率による購入回避（候補には残す）: 馬番{$b12mNum}", [
                            'name'        => $b12mh['name'] ?? '',
                            'rates'       => $b12mEntries,
                            'valid_count' => count($b12mValid),
                            'low_count'   => count($b12mLow),
                            'threshold'   => self::B12_RECOVERY_LOW_THRESH,
                            '購入判定'    => '見送り',
                        ]);
                    }
                }
                unset($b12mh);
            }
            // ── Block 12 End ──────────────────────────────────────────────────────────
            return $horses;
        };
        // ══════════════════════════════════════════════════════════════════════════
        // 候補絞り込みフィルター End
        // ══════════════════════════════════════════════════════════════════════════

        // ── @ANCHOR-20261004-PHP-CANDIDATE  生成する候補行に使うDB値 ──────────
        //   馬名と6分前単勝オッズは必ずDBの値を使う（AIの出力を使わない）。
        $b14DbNameMap  = [];
        $b14DbOdds6Map = [];
        try {
            foreach (DB::table('t_horse_odds_finder_horses')
                        ->where('date',   $date)
                        ->where('kaisuu', $raceRow->kaisuu)
                        ->where('basho',  $raceRow->basho)
                        ->where('day',    $raceRow->day)
                        ->where('race',   $raceRow->race)
                        ->get(['num', 'name']) as $b14h) {
                $b14DbNameMap[(int) $b14h->num] = (string) $b14h->name;
            }
            foreach ($b6OddsRows as $b14o) {
                if (is_numeric($b14o->odds)) $b14DbOdds6Map[(int) $b14o->num] = (float) $b14o->odds;
            }
        } catch (\Throwable $b14e) {
            \Log::warning('[PHP_CANDIDATE] 馬名・6分前オッズの取得に失敗（生成は行わない）', [
                'message' => $b14e->getMessage(),
            ]);
        }

        // ── @ANCHOR-20261004-ALLOC-COMPARE  比較実行用の配分上書きを解決する ──
        $b14AllocMode = $allocSnapshot['mode'];
        $b14AllocFav  = $allocSnapshot['fav'];
        $b14AllocLong = $allocSnapshot['long'];
        if (self::$allocOverride !== null) {
            $b14Ovr = self::$allocOverride;
            if (array_key_exists('fav', $b14Ovr) && $b14Ovr['fav'] !== null) {
                $b14AllocFav  = (int) $b14Ovr['fav'];
                $b14AllocLong = (int) $b14Ovr['long'];
                $b14AllocMode = (string) ($b14Ovr['label'] ?? $b14AllocMode);
            }
            \Log::info('[配分比較] 配分を上書きして統合する（@ANCHOR-20261004-ALLOC-COMPARE）', [
                'race'       => "{$date} {$kaisuu}回{$basho} {$day}日目 {$race}R",
                '条件名'     => $b14Ovr['label'] ?? '(名称なし)',
                '可変配分'   => array_key_exists('feature', $b14Ovr)
                                    ? (($b14Ovr['feature'] ? '有効' : '無効')) : '上書きなし',
                '目標配分'   => ($b14AllocFav === null) ? '既存目安' : "{$b14AllocFav}＋{$b14AllocLong}",
                'プロンプト凍結値' => ($allocSnapshot['fav'] === null)
                                    ? '既存目安' : "{$allocSnapshot['fav']}＋{$allocSnapshot['long']}",
            ]);
        }

        // @ANCHOR-20261006-ANSWER-HASH  統合に使った回答をここで確定させて控える
        $b14HashOf = static function (?string $s): ?string {
            $s = trim((string) $s);
            return $s === '' ? null : substr(hash('sha256', $s), 0, 16);
        };
        $this->lastAnswerHash = [
            '1st_public' => $b14HashOf(self::publicPart((string) $firstAiText)),
            '1st_raw'    => $b14HashOf((string) $firstAiText),
            '2nd_public' => $b14HashOf(self::publicPart((string) ($b7SecondAiFailed ? '' : $analysisText))),
            '2nd_raw'    => $b14HashOf((string) ($b7SecondAiFailed ? '' : $analysisText)),
        ];

        // ═════════════════════════════════════════════════════════════════════
        // @ANCHOR-20261013-V04-AUDIT  AUDIT_V04_AI（05-7の必須監査ログ）
        // ═════════════════════════════════════════════════════════════════════
        //   05-3「公開候補行、内部全頭JSON、生AI応答、パース成否を分けて保存」
        //   05-7「prompt SHA、実送信本文の保存識別子、同一snapshot_hash、
        //     1st/2nd独立性、応答時間、原文・公開行・内部JSON、
        //     マーカー/フィールド不備、訂正要求件数」
        //   既存の AUDIT_AI は現行版の記録。これはv0.4-X用に項目を足した別タグで、
        //   既存ログを置き換えない。AI呼び出しは1回も増えない。
        try {
            $v4First  = (string) $firstAiText;
            $v4Second = (string) ($b7SecondAiFailed ? '' : $analysisText);
            $v4Sha    = static function (string $s): ?string {
                $s = trim($s);
                return $s === '' ? null : hash('sha256', $s);
            };
            // 研究用H/V JSON（BAGANRIKI_V04_HV_PROMPT が無効なら未受領になる）
            $v4Hv1 = self::v04ParseHvJson($v4First);
            $v4Hv2 = self::v04ParseHvJson($v4Second);
            if (self::v04HvPrompt()) {
                // 実AI送信テストのときだけ、生回答を控えて提出物にする
                self::$v04LastAnswers = ['1st' => $v4First, '2nd' => $v4Second];
            }

            // ══════════════════════════════════════════════════════════════
            // @ANCHOR-20261013-V04-HV-FIX  研究用H/V採点の訂正要求（各AI最大1回）
            // ══════════════════════════════════════════════════════════════
            //   付録A・Bの「修正要求はAIごと最大1回」に対応する。
            //   BAGANRIKI_V04_HV_PROMPT がOFFの本番では一度も発生しない。
            //   --remerge（保存済み回答での再統合）では新たにAIを呼ばない。
            $v4FixCount = ['1st' => 0, '2nd' => 0];
            $v4FixWhy   = ['1st' => [], '2nd' => []];
            if (self::v04HvPrompt() && !$b2Remerge) {
                // 実在馬番は Block 16 で作った $_b16ValidNums を使う（DB照合済み）
                $v4ValidNums = array_map('intval', $_b16ValidNums ?? []);
                if (empty($v4ValidNums)) {
                    $v4ValidNums = array_keys(array_merge($v4Hv1['horses'] ?? [], $v4Hv2['horses'] ?? []));
                }
                foreach ([['1st', $v4First, $firstPromptRaw ?? ''], ['2nd', $v4Second, $oddsData]] as [$v4Who, $v4Txt, $v4Prompt]) {
                    if (trim((string) $v4Txt) === '') continue;
                    $v4P   = ($v4Who === '1st') ? $v4Hv1 : $v4Hv2;
                    $v4Why = self::v04HvFixReasons($v4P, $v4ValidNums);
                    if (empty($v4Why)) continue;

                    $v4FixCount[$v4Who] = 1;         // 1回だけ。2以上にしてはいけない
                    $v4FixWhy[$v4Who]   = $v4Why;
                    $v4Fixed = $this->_requestHvFix($v4Who, (string) $v4Prompt, $v4Why,
                        "{$date} {$kaisuu}回{$basho} {$day}日目 {$race}R");
                    if ($v4Fixed === null || trim($v4Fixed) === '') continue;

                    $v4Retry = self::v04ParseHvJson($v4Fixed);
                    $v4Rest  = self::v04HvFixReasons($v4Retry, $v4ValidNums);
                    if (!empty($v4Retry['horses']) && count($v4Rest) < count($v4Why)) {
                        // 指摘が減っていれば訂正後を採用する（残った不備は partial/invalid のまま）
                        if ($v4Who === '1st') $v4Hv1 = $v4Retry; else $v4Hv2 = $v4Retry;
                        \Log::info("[HV_FIX_REQUEST] {$v4Who} の研究用H/V採点を訂正後の内容で採用", [
                            'race' => "{$date} {$kaisuu}回{$basho} {$day}日目 {$race}R",
                            '訂正前の指摘' => count($v4Why),
                            '訂正後の指摘' => count($v4Rest),
                            '残った指摘'   => array_slice($v4Rest, 0, 5),
                        ]);
                        self::$v04LastAnswers[$v4Who . '_訂正後'] = $v4Fixed;
                    } else {
                        \Log::warning("[HV_FIX_REQUEST] {$v4Who} は訂正後も改善しない → 訂正前の採点をそのまま使う", [
                            'race' => "{$date} {$kaisuu}回{$basho} {$day}日目 {$race}R",
                            '訂正前の指摘' => count($v4Why),
                            '訂正後の指摘' => count($v4Rest),
                        ]);
                    }
                }
            }

            self::v04WriteAuditAi([
                'race'              => "{$date} {$kaisuu}回{$basho} {$day}日目 {$race}R",
                'snapshot_hash'     => ['プロンプト生成時' => $auPromptSnapshotId,
                                        '統合時'           => $auNowSnapshotId,
                                        '一致'             => $auSnapshotMatch],
                'prompt_1st_sha256' => $v4Sha($v4First)  === null ? null : 'answer:' . substr($v4Sha($v4First), 0, 16),
                'prompt_2nd_sha256' => $v4Sha($v4Second) === null ? null : 'answer:' . substr($v4Sha($v4Second), 0, 16),
                'answer_hash'       => $this->lastAnswerHash,
                '1st_2nd独立性'     => '2ndのプロンプトに1stの候補・点数・回答を渡していない'
                                       . '（送信文の生成元が別で、1stの結果を参照する入力が無い）',
                'target_count'      => $b15TargetCount ?? null,
                'public_cap'        => ['1st' => $b15TargetCount ?? null, '2nd' => self::V04_PUBLIC_CAP_2ND],
                '公開候補数'        => ['1st' => count($firstAiHorses), '2nd' => count($secondAiHorses)],
                '研究用H/V JSON'    => [
                    '1st' => ['受領' => $v4Hv1['ok'], '頭数' => $v4Hv1['頭数'] ?? 0,
                              'マーカー' => $v4Hv1['marker'] ?? null, 'エラー' => $v4Hv1['errors'] ?? [],
                              '馬番重複' => $v4Hv1['duplicated'] ?? []],
                    '2nd' => ['受領' => $v4Hv2['ok'], '頭数' => $v4Hv2['頭数'] ?? 0,
                              'マーカー' => $v4Hv2['marker'] ?? null, 'エラー' => $v4Hv2['errors'] ?? [],
                              '馬番重複' => $v4Hv2['duplicated'] ?? []],
                ],
                // @ANCHOR-20261014-CONTRACT-GATE  契約検証の結果（採用の可否）
                '契約検証'          => $v4Contract ?? null,
                '照合に使った値'    => $v4Expect ?? null,
                '一致加点'          => self::v04MatchBonusHorses(
                    array_map(static fn($h) => (int) ($h['num'] ?? 0), $firstAiHorses),
                    array_map(static fn($h) => (int) ($h['num'] ?? 0), $secondAiHorses),
                    array_keys($v4Hv1['horses'] ?? []),
                    array_keys($v4Hv2['horses'] ?? [])
                ),
                '訂正要求件数'      => [
                    '研究用H/V（@ANCHOR-20261013-V04-HV-FIX）' => $v4FixCount ?? ['1st' => 0, '2nd' => 0],
                    '指摘の内容' => array_map(static fn($w) => array_slice($w, 0, 5), $v4FixWhy ?? []),
                    '上限'       => '付録A・Bどおり、AIごと最大1回',
                    '現行11項目の修正要求' => 'AUDIT_AI の「修正要求の対象」に記録済み（別枠）',
                ],
                'switches'          => self::v04Switches(),
                '注記'              => 'BAGANRIKI_V04_HV_PROMPT が無効の間、研究用H/V JSONは'
                                       . '必ず未受領になる（送信文に依頼を入れていないため）。'
                                       . 'これは異常ではなく既定の状態',
            ]);

            // ══════════════════════════════════════════════════════════════
            // @ANCHOR-20261014-CONTRACT-GATE  契約検証を採用処理に接続する
            // ══════════════════════════════════════════════════════════════
            // 10/14のご指摘④「AI回答の契約検証を、研究用の採点・候補選出処理に
            //   正しく接続すること」への対応。
            // 【旧実装の問題】
            //   v04CheckAiContract() を作ったのに、受入試験からしか呼んでおらず、
            //   実際の統合処理では一度も通していなかった。
            //   そのため snapshot_hash や race_id が違う回答、馬番が重複した回答、
            //   頭数の合わない回答でも、そのまま採点として採用されてしまう状態だった。
            // 【対処】
            //   両AIの回答を契約検証にかけ、UNDETERMINED のAIの採点は採用しない。
            //   PARTIAL（頭数不足・混入）は採用するが、状態を記録する。
            //   判定結果は AUDIT_V04_AI に残す。
            $v4Expect = [
                'race_id'       => "{$date}_{$kaisuu}_{$basho}_{$day}_{$race}",
                'snapshot_hash' => (string) ($auNowSnapshotId ?? $auPromptSnapshotId ?? ''),
                'nums'          => array_map('intval', $_b16ValidNums ?? []),
            ];
            $v4Contract = [
                '1st' => self::v04CheckAiContract($v4Hv1, $v4Expect, $v4FixCount['1st'] ?? 0),
                '2nd' => self::v04CheckAiContract($v4Hv2, $v4Expect, $v4FixCount['2nd'] ?? 0),
            ];
            foreach (['1st', '2nd'] as $v4Who) {
                if (($v4Contract[$v4Who]['state'] ?? 'OK') !== 'UNDETERMINED') continue;
                // 契約違反のAIの採点は、研究用の採点としても採用しない
                \Log::log(self::v04HvPrompt() ? 'error' : 'info', "[CONTRACT_GATE] {$v4Who} の研究用H/V採点は契約検証で不採用（@ANCHOR-20261014-CONTRACT-GATE）", [
                    'race'   => "{$date} {$kaisuu}回{$basho} {$day}日目 {$race}R",
                    'issues' => $v4Contract[$v4Who]['issues'] ?? [],
                    '扱い'   => '採点を採用しない。選出にも使わない（0点補完や推測埋めはしない）',
                ]);
                if ($v4Who === '1st') $v4Hv1['horses'] = []; else $v4Hv2['horses'] = [];
            }

            // @ANCHOR-20261013-V04-HV-APPLY  採点が届いていれば選出まで通して記録する
            //   10/13のご指摘【3】「返答が採点処理へ正しく渡されること」の確認用。
            //   公開候補・おすすめ度・DBには一切反映しない。
            $v4HvMap  = ($v4Hv1['horses'] ?? []) ?: [];
            $v4Role   = !empty($v4Hv1['horses']) ? '1st' : '';
            if (!empty($v4Hv2['horses'])) {
                // 2頭のAIが同じ馬を採点していたら、1stを優先して記録する
                // （両方を混ぜて平均しない。混ぜると出所が追えなくなる）
                foreach ($v4Hv2['horses'] as $v4n => $v4row) {
                    if (!isset($v4HvMap[$v4n])) $v4HvMap[$v4n] = $v4row;
                }
                $v4Role = ($v4Role === '') ? '2nd' : '1st+2nd';
            }
            if (!empty($v4HvMap)) {
                $v4Applied = self::v04ApplyHvAndSelect(
                    "{$date} {$kaisuu}回{$basho} {$day}日目 {$race}R", $v4HvMap, $v4Role);
                if ($v4Applied !== null) {
                    \Log::info('[V04_HV] AIの研究用採点を選出まで通した（記録のみ）', [
                        'race'             => $v4Applied['race'],
                        'ai_role'          => $v4Applied['ai_role'],
                        '受領頭数'         => $v4Applied['AI採点を受領した頭数'],
                        'score_status内訳' => $v4Applied['score_status内訳'],
                        'Tier別頭数'       => $v4Applied['Tier別頭数'],
                        '仕様どおりの選出' => $v4Applied['仕様どおりの選出']['selected'],
                        '参考選出'         => $v4Applied['参考選出（採点なし）']['selected'],
                    ]);
                    self::auditFile('AUDIT_V04_HV_APPLY', $v4Applied);
                    self::$v04LastHvApplied = $v4Applied;
                } else {
                    \Log::warning('[V04_HV] 採点は届いたが、構造判定の入力の控えが無いため'
                        . '選出まで通せなかった（プロンプト再生成が行われていない可能性）', [
                        'race' => "{$date} {$kaisuu}回{$basho} {$day}日目 {$race}R",
                    ]);
                }
            }
        } catch (\Throwable $v4AiE) {
            \Log::error('[AUDIT_V04_AI] v0.4-X のAI監査ログの作成に失敗（処理は継続）', [
                'message' => $v4AiE->getMessage(),
                'file'    => $v4AiE->getFile() . ':' . $v4AiE->getLine(),
            ]);
        }


        $mergedHorses   = $this->_mergeAiResults(
            $firstAiHorses,
            $secondAiHorses,
            $gapTypeForMerge,
            $horseCount2nd,
            $mergeUpperMax,
            $mergeMidMax,
            $mergeLowerMax,
            $horseFlagsMap,     // Block 6: F1〜F8フラグマップ（F1/F5はBlock10後に有効化済み）
            $b13PreCapFilter,   // 【20260924】上限適用前の絞り込みフィルター
            $protectedLongshotForMerge, // 【20260927】人気薄の根拠付き保護対象の馬番（20261004以降は参考入力）
            // 【20261004】プロンプトから読み戻した配分モード（@ANCHOR-20261004-ALLOC-SNAPSHOT）
            //   比較実行中（@ANCHOR-20261004-ALLOC-COMPARE）は上書きを使う。
            $b14AllocMode, $b14AllocFav, $b14AllocLong,
            $allocSnapshot['qualified'],
            // 【20261004 回答①A-2】検証済みの全頭採点からPHPが候補行を生成する入力
            //   検証がOKだったAIの採点だけを渡す（NGの採点は使わない）。
            //   @ANCHOR-20261004-PHP-CANDIDATE
            //   @ANCHOR-20261006-SCORE-SOURCE-OF-TRUTH
            //   補充候補の生成には「検証済みの内部採点」だけを渡す。
            //   不一致で未検証になった馬は渡さない（公開候補行は別途そのまま残る）。
            self::verifiedAllScore($allScore1st),
            self::verifiedAllScore($allScore2nd),
            $allocEvidenceSnapshot,
            $b14DbNameMap,
            $b14DbOdds6Map,
            // @ANCHOR-20261006-QUAL-STATE  7番人気以下の資格判定（成立/不成立/不明）
            $allocQualState
        );

        // ── よっしー20260926指摘【今回の確認ログ】──────────────────────────
        //   どの処理で候補が減ったのかを1レース1行で追えるようにする。
        //   ①各AIの候補数 ②最低基準点通過数 ③低配当条件該当数
        //   ④回収率購入回避フラグ数 ⑤人気帯上限適用後の候補数 ⑥最終候補数
        //   ※20260926の仕様変更により、③④は「該当しただけ」で候補からは消えない。
        \Log::info('[候補内訳] レースごとの絞り込み経過', [
            'race'                    => "{$date} {$kaisuu}回{$basho} {$day}日目 {$race}R",
            '①1stAI候補数'           => count($firstAiHorses),
            '①2ndAI候補数'           => count($secondAiHorses),
            '②最低基準点の通過数'    => $b13Stats['after_min_score'],
            '③低配当条件の該当数'    => $b13Stats['low_payout_hit'],
            '④回収率で購入回避の数'  => $b13Stats['recovery_avoid'],
            '⑤実出走頭数N'           => (int) $horseCount2nd,
            '⑥目標数C'               => self::targetSelectionCount((int) $horseCount2nd),
            '⑦最終候補数'            => count($mergedHorses),
            '⑧保護対象馬番'          => $protectedLongshotForMerge,
            '注記'                    => '②③④はすべて購入判定・順位づけ用のフラグであり候補からは除外しない（20260927）',
        ]);

        // ══════════════════════════════════════════════════════════════════════
        // @ANCHOR-20261014-EVIDENCE-AUDIT2  依頼書⑧：処理前後の頭数を監査ログに残す
        // ══════════════════════════════════════════════════════════════════════
        // 【これまでの問題】
        //   上の [候補内訳] は \Log::info なので、.env の LOG_LEVEL=error では
        //   【1件も記録されていませんでした】。
        //   「候補が落ちる全経路について処理前後の頭数を残す」というご依頼に
        //   対して、実際には残っていなかったことになります。
        // 【この変更】
        //   同じ内容を統合の監査ログ（merge_result の audit_merge）へ入れます。
        //   DBに保存されるので、後から race_id で引けます。
        $stN = (int) $horseCount2nd;
        self::recordStageCount('① AIの候補行', count($firstAiHorses) . '(1st)+'
            . count($secondAiHorses) . '(2nd)', '両AIの合計（重複込み）',
            'AIが公開候補として出した行の数');
        self::recordStageCount('② 最低基準点', count($firstAiHorses) + count($secondAiHorses),
            $b13Stats['after_min_score'],
            '通過数。未満でも候補からは消さない（順位材料と購入判断にのみ使う）');
        self::recordStageCount('③ 低配当', '－', $b13Stats['low_payout_hit'] . '頭が該当',
            '購入回避フラグのみ。候補からは消さない');
        self::recordStageCount('④ 回収率40%未満', '－', $b13Stats['recovery_avoid'] . '頭が該当',
            '購入回避フラグのみ。候補からは消さない');
        self::recordStageCount('⑤ 出走頭数と目標数C', $stN . '頭立て',
            self::targetSelectionCount($stN) . '頭（目標数C）', 'Cは目標かつ上限');
        self::recordStageCount('⑥ 統合・最終候補', '－', count($mergedHorses),
            '実際に公開した頭数。Cに届かないまま公開することがある');



        // ── Block 15: 厳選穴レース 再判定（最終候補確定後にPHPが上書き） ────────
        // 【20260928 受入チェック#84】条件B・C・Dは三値（成立／不成立／不明）。
        //   プロンプトテキストに「条件X（PHP算出済み）: 成立|不成立|不明…」として
        //   埋め込んであるので、その3語を読み戻して再利用する（DB再クエリ不要）。
        //   行が見つからない＝確認できないので「不明」に倒す（不成立にしない）。
        //   @ANCHOR-20260928-UPSET-TRISTATE
        //   ★ $oddsData は 2nd AI 用に整形済みで、判定ルールブロックごと条件行が
        //     除去されている。必ず整形前に読み取った $b15CondSnapshot を使うこと。
        //     @ANCHOR-20260928-UPSET-COND-SNAPSHOT
        $condBMet = $b15CondSnapshot['B'];
        $condCMet = $b15CondSnapshot['C'];
        $condDMet = $b15CondSnapshot['D'];

        // 条件A: 最終候補（mergedHorses）の中に7〜10番人気が1頭以上いるか
        $condAMet = false;
        foreach ($mergedHorses as $mh) {
            $pop = (int) ($mh['popularity'] ?? 0);
            if ($pop >= 7 && $pop <= 10) {
                $condAMet = true;
                break;
            }
        }

        // 再判定ルール（仕様書ブロック15 ＋ 20260928 受入チェック#84）
        //   ① B・C・Dのいずれかが【成立】          → 0（穴レースなし。条件Aは見ない）
        //   ② B・C・Dが全て【不成立】 かつ 条件A成立 → 1
        //   ③ B・C・Dが全て【不成立】 かつ 条件A不成立 → 0
        //   ④ 【成立】が無く【不明】が残る かつ 条件A成立   → 不明（null）
        //   ⑤ 【成立】が無く【不明】が残る かつ 条件A不成立 → 0
        $b15AnyMet     = ($condBMet === true || $condCMet === true || $condDMet === true);
        $b15AnyUnknown = ($condBMet === null || $condCMet === null || $condDMet === null);

        if ($b15AnyMet) {
            $upsetRaceFinal = 0;                       // ①
        } elseif (!$b15AnyUnknown) {
            $upsetRaceFinal = $condAMet ? 1 : 0;       // ②③
        } else {
            $upsetRaceFinal = $condAMet ? null : 0;    // ④⑤（null = 不明）
        }

        // Flutterへ渡す表示用の文字列（既存の upset_race は数値のまま・不明は null）
        $upsetRaceStatus = ($upsetRaceFinal === null) ? '不明' : (string) $upsetRaceFinal;

        \Log::info('[厳選穴レース] 最終候補確定後の再判定', [
            'race'   => "{$date} {$kaisuu}回{$basho} {$day}日目 {$race}R",
            '条件A'  => $condAMet ? '成立' : '不成立',
            '条件B'  => $condBMet === null ? '不明' : ($condBMet ? '成立' : '不成立'),
            '条件C'  => $condCMet === null ? '不明' : ($condCMet ? '成立' : '不成立'),
            '条件D'  => $condDMet === null ? '不明' : ($condDMet ? '成立' : '不成立'),
            '厳選穴レース' => $upsetRaceStatus,
        ]);

        // ── レース指標パース（B-14 / B-11 で共通利用） ───────────────────────────────
        // ⑨ 仕様: 波乱度・下位進入度・大穴進入度は 1st AI（Claude）の出力のみ参照
        // フォーマット: 「レース指標|波乱度: X|下位進入度: X|大穴進入度: X」
        $b14WaveLevel  = null;
        $b14LowerEntry = null;
        $b14BigGap     = null;
        if (preg_match(
            '/レース指標\|波乱度[:：\s]*(\d+)\|下位進入度[:：\s]*(\d+)\|大穴進入度[:：\s]*(\d+)/u',
            $firstAiText, $_gm
        )) {
            $b14WaveLevel  = (int)$_gm[1];
            $b14LowerEntry = (int)$_gm[2];
            $b14BigGap     = (int)$_gm[3];
        }

        // ── Block 14: 統合結果を ai_merge_result テーブルに UPSERT ──────────────────
        $this->_saveAiMergeResult(
            $mergedHorses, $upsetRaceFinal, $gapTypeForMerge,
            $b14WaveLevel, $b14LowerEntry, $b14BigGap,
            $date, $kaisuu, $basho, $day, $race, $raceRow,
            $b69MeritCap,  // #69: 妙味小計上限の検証結果（DBに証跡として残す）
            // 【20261004】snapshot_idの照合結果（@ANCHOR-20261004-AUDIT-SNAPSHOT）
            //   よっしー回答③Aの条件「レースID・対象時点とセットで管理し、
            //   ハッシュの元になった入力も保存してください。」
            [
                'race_id'            => "{$date}_{$kaisuu}_{$basho}_{$day}_{$race}",
                'timing'             => self::SNAPSHOT_TIMING,
                'prompt_snapshot_id' => $auPromptSnapshotId,
                'merge_snapshot_id'  => $auNowSnapshotId,
                'match'              => $auSnapshotMatch,
                'mixed_inputs'       => ($auSnapshotMatch === false),
                'normalize'          => '馬番昇順・小数2桁固定・非数値は-',
                'source'             => $auNowSnapshotSource,   // ハッシュの元になった入力そのもの
            ]
        );
        // ── Block 14 End ──────────────────────────────────────────────────────────

        // ── Block 10: 市場妙味基礎点（② 修正: merge前に移動済み）──

        // ── Block B-8: 偽流入警戒フラグ判定（シャドー期間：ログ保存・フラグ付与のみ） ────────
        $this->_judgeFalseInflowFlags(
            $mergedHorses, $b8InfoMap, $b13UnderevalFlagMap,
            $horseFlagsMap, $b6TanPopMap, $b6FukuPopMap,
            $date, $kaisuu, $basho, $day, $race
        );
        // ── Block B-8 End ────────────────────────────────────────────────────────

        // ══════════════════════════════════════════════════════════════════════
        // @ANCHOR-20261005-AUX-NEVER-BREAKS  補助処理の失敗で予想を落とさない
        // ══════════════════════════════════════════════════════════════════════
        // シャドーログと学習用スナップショットは「あとで分析するための記録」であり、
        // 画面に出す予想とは無関係。ここで例外が出ると下の catch (\Throwable) に
        // 流れ、せっかく計算した候補を捨てて「候補0件」を返してしまう。
        // 記録のための処理が予想を殺すのは本末転倒なので、個別に囲む。
        //   ※2026-10-05: _saveMlSnapshot() の実着順取得の列名を直した
        //     （finishing_position → result）。これまでSQLエラーで常に失敗して
        //     いた経路が初めて動くため、ここを囲まずに本番へ出すのは危険。
        // ── Block B-10: シャドー期間中の高配当総合点・仮順位・馬券判定ログ保存 ──────────
        try {
            $this->_saveHighPayoutShadow(
                $mergedHorses, $b10TotalScoreMap, $b13UnderevalFlagMap,
                $b13ScoreAMap, $b6OddsRows, $oddsHorseBlocks,
                $gapTypeForMerge, $firstAiHorses, $secondAiHorses,
                $horseFlagsMap, $date, $kaisuu, $basho, $day, $race, $raceRow
            );
        } catch (\Throwable $auxE) {
            \Log::error('[AUX_FAILED] シャドーログの保存に失敗（予想表示は継続）', [
                'race'    => "{$date} {$kaisuu}回{$basho} {$day}日目 {$race}R",
                'message' => $auxE->getMessage(),
                'file'    => $auxE->getFile() . ':' . $auxE->getLine(),
            ]);
        }
        // ── Block B-10 End ──────────────────────────────────────────────────────────

        // ── Block 11: 断層パターン学習 特徴量スナップショット保存 ───────────────────
        try {
        $this->_saveMlSnapshot(
            $mergedHorses, $gapTypeForMerge, $primaryGapUpperPopForMerge,
            $mergeUpperMax, $mergeMidMax, $mergeLowerMax,
            $horseCount2nd, $upsetRaceFinal,
            $b14WaveLevel, $b14LowerEntry, $b14BigGap,
            $condAMet, $condBMet, $condCMet, $condDMet,
            $b10ScoreE, $firstAiHorses, $secondAiHorses,
            $oddsData, $oddsHorseBlocks, $b6TanPopMap, $b6FukuPopMap, $b6OddsRows,
            $b13ScoreAMap, $b10ScoreDMap,
            $date, $kaisuu, $basho, $day, $race, $raceRow,
            $b10ScoreEMap   // 【20260924】馬ごとの基礎点E（断層構造の穴進入根拠）
        );
        } catch (\Throwable $auxE2) {
            // @ANCHOR-20261005-AUX-NEVER-BREAKS
            \Log::error('[AUX_FAILED] 学習用スナップショットの保存に失敗（予想表示は継続）', [
                'race'    => "{$date} {$kaisuu}回{$basho} {$day}日目 {$race}R",
                'message' => $auxE2->getMessage(),
                'file'    => $auxE2->getFile() . ':' . $auxE2->getLine(),
            ]);
        }
        // ── Block 11 End ──────────────────────────────────────────────────────────

        // ── Flutter応答の組み立て: シャドー専用の値を応答から除去する ──────────
        // 【仕様】受入チェック#36・#51、および【シャドー表示制御】
        //   「シャドー検証中の強化指標・馬券判定は内部計算とログ保存だけに使用し、
        //     Flutterの候補・順位・選出理由へ影響しない」
        //   「シャドー中は数値をログだけに保存し、…Flutterへ表示せず」
        //   B-8 / B-10 は $mergedHorses（参照渡し）へシャドー値を付与するため、
        //   そのまま返すとシャドー値がFlutterまで出てしまう。ここで必ず落とす。
        //   ★本番有効化が決まるまで、このキー一覧を減らしてはいけない。
        $shadowOnlyKeys = self::SHADOW_ONLY_KEYS;
        $flutterHorses = array_map(
            function (array $fh) use ($shadowOnlyKeys): array {
                foreach ($shadowOnlyKeys as $fk) unset($fh[$fk]);
                return $fh;
            },
            $mergedHorses
        );
//         \Log::debug('[Flutter] シャドー値を応答から除去', [
//             'removed_keys' => $shadowOnlyKeys,
//             'horses'       => count($flutterHorses),
//         ]);

        return response()->json(['data' => [
            'date'          => $date,
            'kaisuu'        => $kaisuu,
            'basho_code'    => $basho,
            'day'           => $day,
            'race'          => $race,
            'analysis_text' => self::publicPart($analysisText),   // 【20261004】内部監査用JSONは返さない
            'merged_horses' => $flutterHorses,   // ← シャドー値を除いた候補配列
            // 【20260928 受入チェック#84】厳選穴レースは 1 / 0 / 不明 の三値。
            //   既存の upset_race は数値のまま（不明は null）。Flutter は null 安全に読む。
            //   文字列表現は upset_race_status を新設して渡す（既存キーの型は変えない）。
            'upset_race'        => $upsetRaceFinal,
            'upset_race_status' => $upsetRaceStatus,
            // レース指標は 1st AI の出力をそのまま使う（⑨仕様）。
            // Flutter が 1st AI テキストを再パースしなくて済むよう応答にも載せる。
            'race_metrics'  => ($b14WaveLevel !== null && $b14LowerEntry !== null && $b14BigGap !== null)
                ? ['波乱度' => $b14WaveLevel, '下位進入度' => $b14LowerEntry, '大穴進入度' => $b14BigGap]
                : null,
        ]]);

    } catch (\Illuminate\Contracts\Cache\LockTimeoutException $e) {
        return response()->json(['error' => 'しばらくしてから再試行してください'], 503);
    } catch (\Throwable $raceE) {
        // 【20260928 レース停止回避追補】レース単位の例外境界（2nd AI側）
        //   想定外の例外を次のレースへ伝播させない。AIは呼び直さない。
        //   候補行0件・厳選穴レース不成立の部分結果を HTTP 200 で返す。
        //   @ANCHOR-20260928-RACE-PROCESSING-ERROR
        // ══════════════════════════════════════════════════════════════════════
        // @ANCHOR-20261005-FALLBACK-SAVED-MERGE  例外時も保存済みの統合結果で粘る
        // ══════════════════════════════════════════════════════════════════════
        // Block 14 が統合結果をDBへ保存したあとに例外が出た場合、
        // 空の候補を返すと「計算も保存も済んでいるのに画面には何も出ない」
        // という最悪の形になる。保存済みの結果があればそれを返す。
        // 無ければ従来どおり候補0件の部分結果を返す（捏造はしない）。
        // ══════════════════════════════════════════════════════════════════════
        // @ANCHOR-20261006-FALLBACK-SAME-INPUT  復帰は同じ入力の結果に限る
        // ══════════════════════════════════════════════════════════════════════
        // 【20261006 ご指摘・第7節】
        //   「第26章の救済は、同じレース・対象時点・入力に対応する有効な保存結果に
        //     限ることを確認してください。第21章の『入力を混ぜない』と両立させる必要がある」
        //   → 6分前オッズのスナップショットIDが一致したときだけ、保存済み結果へ復帰する。
        //     一致しない／確認できない場合は復帰せず、従来どおり候補0件で返す。
        $raceFallback = [];
        $fbSnapshotOk = (isset($auPromptSnapshotId, $auNowSnapshotId)
                         && $auPromptSnapshotId !== null
                         && $auNowSnapshotId !== null
                         && $auPromptSnapshotId === $auNowSnapshotId);
        if ($fbSnapshotOk) {
            $raceFallback = $this->_loadSavedMergeResult($date, $kaisuu, $basho, $day, $race);
        }
        \Log::error('[RACE_PROCESSING_ERROR] 2nd AI統合処理で想定外の例外', [
            'date' => $date, 'kaisuu' => $kaisuu, 'basho' => $basho, 'day' => $day, 'race' => $race,
            'stage'   => '2nd_ai_merge',
            'message' => $raceE->getMessage(),
            'file'    => $raceE->getFile() . ':' . $raceE->getLine(),
            'trace'   => mb_substr($raceE->getTraceAsString(), 0, 2000),
            '応答'    => empty($raceFallback['merged_horses'])
                ? '候補0件の部分結果で続行'
                : '保存済みの統合結果（' . count($raceFallback['merged_horses']) . '頭）で続行',
            // @ANCHOR-20261006-FALLBACK-SAME-INPUT
            '保存済み結果への復帰' => $fbSnapshotOk
                ? '可（6分前オッズのsnapshot_idが一致）'
                : '不可（snapshot_idが一致しない、または確認できない。入力を混ぜないため復帰しない）',
        ]);
        return response()->json(['data' => array_merge([
            'date'          => $date,
            'kaisuu'        => $kaisuu,
            'basho_code'    => $basho,
            'day'           => $day,
            'race'          => $race,
            'analysis_text'     => '',
            'merged_horses'     => [],   // 候補行0件
            'upset_race'        => 0,    // 条件A不成立 → 厳選穴レース|0
            'upset_race_status' => '0',
            'race_metrics'      => null, // 未取得値は「不明」
        ], $raceFallback)]);
    } finally {
        self::releaseRaceLock($lock);   // @ANCHOR-20261005-LOCK-FALLBACK
    }
}

    /**
     * 【20260928】1st AI が通信失敗・APIエラーのときに空回答を保存する。
     *   2nd AI（DeepSeek）側が「1st AIの分析が完了していません（409）」で止まらず、
     *   DeepSeek の有効候補だけでレースを成立させられるようにするため。
     *   自動再試行は禁止なので、やり直すときは ai_analysis の該当行を削除して再実行する。
     *   @ANCHOR-20260928-NO-RACE-STOP
     */
    private function _saveEmptyFirstAiAnalysis(
        string $date, $kaisuu, string $basho, $day, $race, $raceRow, string $reason
    ): void {
        // @ANCHOR-20261004-DRY-RUN  試算モードでは保存しない
        if (self::$dryRunNoPersist) return;
        try {
            DB::table('t_horse_odds_finder_ai_analysis')->updateOrInsert(
                ['date' => $date, 'kaisuu' => $kaisuu, 'basho_code' => $basho, 'day' => $day, 'race' => $race],
                [
                    'basho'         => $raceRow->basho_name ?? '',
                    'race_name'     => $raceRow->race_name  ?? '',
                    'analysis_text' => '',
                ]
            );
            \Log::warning('[PREDICTION_PARTIAL] 1st AI を空回答として保存（2nd AIで続行）', [
                'reason' => $reason,
                'date' => $date, 'kaisuu' => $kaisuu, 'basho' => $basho, 'day' => $day, 'race' => $race,
            ]);
        } catch (\Throwable $seE) {
            \Log::error('[RACE_PROCESSING_ERROR] 1st AI 空回答の保存に失敗（処理は継続）', [
                'message' => $seE->getMessage(),
                'date' => $date, 'kaisuu' => $kaisuu, 'basho' => $basho, 'day' => $day, 'race' => $race,
            ]);
        }
    }

    private function _getGapBand(float $changeRate): string
    {
        if ($changeRate <= -30) return '30%以上下落';
        if ($changeRate <= -20) return '20〜30%下落';
        if ($changeRate <= -10) return '10〜20%下落';
        if ($changeRate <= -5)  return '5〜10%下落';
        if ($changeRate <   5)  return '±5%以内';
        if ($changeRate <  10)  return '5〜10%上昇';
        if ($changeRate <  20)  return '10〜20%上昇';
        if ($changeRate <  30)  return '20〜30%上昇';
        return '30%以上上昇';
    }

    private function _getPopularityBand(int $popularity): string
    {
        if ($popularity <= 3) return '1〜3人気';
        if ($popularity <= 6) return '4〜6人気';
        if ($popularity <= 9) return '7〜9人気';
        return '10人気以上';
    }

    private function _getOpiBand(float $opi): string
    {
        if ($opi <  0.70) return '0.70未満';
        if ($opi <  0.85) return '0.70〜0.85';
        if ($opi <  1.00) return '0.85〜1.00';
        if ($opi <  1.15) return '1.00〜1.15';
        if ($opi <  1.30) return '1.15〜1.30';
        if ($opi <  1.50) return '1.30〜1.50';
        return '1.50以上';
    }

    private function _getPhaseDirection(float $rate): string
    {
        if ($rate <= -5.0) return '下落';
        if ($rate <   5.0) return '横ばい';
        return '上昇';
    }

    private function _parsePayoutString(?string $payoutStr): array
    {
        if ($payoutStr === null || $payoutStr === '') {
            return [];
        }
        $map = [];
        foreach (explode('/', $payoutStr) as $entry) {
            $parts = explode('|', trim($entry));
            if (count($parts) === 2 && $parts[0] !== '' && is_numeric($parts[1])) {
                $num       = ltrim($parts[0], '0') ?: '0';
                $map[$num] = (int) $parts[1];
            }
        }
        return $map;
    }



    /**
     * ═════════════════════════════════════════════════════════════════════════
     * @ANCHOR-20261013-V04-HV-FIX  研究用H/V採点の訂正要求（AIごと最大1回）
     * ═════════════════════════════════════════════════════════════════════════
     * 10/13（5回目）のご指摘【4】
     *   「仕様書に定める『各AIにつき最大1回の訂正要求』が未実装」
     * 付録A・Bの「修正要求はAIごと最大1回」に合わせて実装する。
     *
     * 【なぜ必要になったか】
     *   10/13の実AI送信テストで、AIが配点の上限を超えてきた。
     *   15番の H5 が7点（上限6）で invalid、16番は H5 欠落で partial。
     *   現行の訂正要求は11項目の採点にしか付いていなかった。
     *
     * 【費用について】
     *   訂正要求は1回につきAI呼び出しが1回増える。
     *   BAGANRIKI_V04_HV_PROMPT が既定OFFなので、本番では一度も発生しない。
     *   発生するのは --v04-hv-trial で研究用H/Vを頼んだときだけ。
     *
     * 【2回目は送らない】
     *   既存の _requestScoreFix() と同じで、maxAttempts は1固定。
     *   訂正後も直らなければ、その馬の採点は partial/invalid のまま使う
     *   （0点補完も推測埋めもしない）。
     *
     * @param  string $aiLabel        '1st' / '2nd'
     * @param  string $originalPrompt そのAIへ送った送信文
     * @param  array  $errors         指摘（上限超過・欠落・混入など）
     * @param  string $raceLabel      レース表記
     * @return string|null            訂正後の生回答（失敗時は null）
     */
    private function _requestHvFix(
        string $aiLabel,
        string $originalPrompt,
        array  $errors,
        string $raceLabel
    ): ?string {
        $cap = [];
        foreach (self::V04_SCORE_CAP as $k => $max) { $cap[] = "{$k}は0〜{$max}"; }

        $ask = "直前のあなたの回答のうち、研究用の全頭採点（" . self::V04_SCORING_VERSION . "）に不備がありました。\n"
             . "次の指摘をすべて直し、" . self::V04_HV_JSON_BEGIN . " と " . self::V04_HV_JSON_END
             . " で囲んだ研究用の全頭採点JSONだけを、もう一度出力してください。\n"
             . "・公開候補行は出し直さないでください（前回の候補行をそのまま使います）。\n"
             . "・現行の全頭採点（" . self::AUDIT_JSON_BEGIN . "）も出し直さないでください。\n"
             . "・各項目の上限を必ず守ってください（" . implode('／', $cap) . "）。\n"
             . "・採点できない項目は0ではなく null にし、score_status を partial、total_score を null に\n"
             . "  してください。推測値や0で埋めないでください。\n"
             . "・全実出走馬を入れ、馬番の重複・欠落・実在しない馬番をなくしてください。\n\n"
             . "【指摘】\n・" . implode("\n・", array_slice($errors, 0, 30)) . "\n";

        \Log::warning("[HV_FIX_REQUEST] 研究用H/V採点の訂正要求を1回だけ送る（{$aiLabel}）", [
            'race'     => $raceLabel,
            'AI'       => $aiLabel,
            '版'       => self::V04_SCORING_VERSION,
            '指摘件数' => count($errors),
            '指摘'     => array_slice($errors, 0, 30),
            '位置づけ' => '付録A・Bの「修正要求はAIごと最大1回」。通常の2回とは別枠の例外',
            '費用'     => 'AI呼び出しが1回増える。BAGANRIKI_V04_HV_PROMPT がOFFの本番では発生しない',
        ]);

        try {
            if ($aiLabel === '1st') {
                $res = $this->anthropic->sendWithRetry(
                    prompt:      $originalPrompt . "\n\n" . $ask,
                    system:      'あなたは競馬オッズ分析の専門家（1st AI）です。直前の回答の研究用H/V採点JSONだけを、指摘どおりに直して出力してください。公開候補行と現行の全頭採点は出力しません。',
                    maxAttempts: 1,   // 訂正要求も1回のみ。2以上にしてはいけない
                    sleepBase:   2,
                    timeout:     240, // H/Vは出力が増えるため長めに待つ（@ANCHOR-20261013-V04-HV-TIMEOUT）
                );
                return $this->anthropic->extractText($res);
            }

            $http = Http::timeout(120)->withHeaders([
                'Authorization' => 'Bearer ' . env('DEEPSEEK_API_KEY'),
            ])->post('https://api.deepseek.com/v1/chat/completions', [
                'model'      => 'deepseek-chat',
                'max_tokens' => 8192,
                'messages'   => [
                    ['role' => 'system', 'content' => 'あなたは競馬オッズ分析の専門家（2nd AI）です。直前の回答の研究用H/V採点JSONだけを、指摘どおりに直して出力してください。公開候補行と現行の全頭採点は出力しません。'],
                    ['role' => 'user',   'content' => $originalPrompt . "\n\n" . $ask],
                ],
            ]);
            if ($http->failed()) {
                \Log::error('[HV_FIX_REQUEST] 2nd の訂正要求が通信失敗（訂正なしで続行）', [
                    'race' => $raceLabel, 'status' => $http->status(),
                ]);
                return null;
            }
            $json = $http->json();
            $fin  = $json['choices'][0]['finish_reason'] ?? null;
            if ($fin !== null && $fin !== 'stop') {
                \Log::error('[HV_FIX_REQUEST] 2nd の訂正回答が途中で終わっている', [
                    'race' => $raceLabel, 'finish_reason' => $fin,
                ]);
            }
            return trim($json['choices'][0]['message']['content'] ?? '');
        } catch (\Throwable $e) {
            \Log::error('[HV_FIX_REQUEST] 訂正要求で例外（訂正なしで続行）', [
                'race' => $raceLabel, 'AI' => $aiLabel, 'message' => $e->getMessage(),
            ]);
            return null;
        }
    }

    /**
     * @ANCHOR-20261013-V04-HV-FIX  訂正要求を出すべき不備を並べる
     *   上限超過（invalid）・項目欠落（partial）・馬番の欠落・実在しない馬番・
     *   マーカー欠落・schema_version不一致を拾う。
     *
     * @param  array $parsed   v04ParseHvJson() の戻り
     * @param  array $validNums 6分前に出走が確認できた馬番
     * @return array           指摘の配列（空なら訂正要求は不要）
     */
    private static function v04HvFixReasons(array $parsed, array $validNums): array
    {
        $why = [];
        foreach (($parsed['errors'] ?? []) as $e) { $why[] = $e; }

        $cap = self::V04_SCORE_CAP;
        foreach (($parsed['horses'] ?? []) as $num => $row) {
            $miss = []; $over = [];
            foreach ($cap as $k => $max) {
                $v = $row['scores'][$k] ?? null;
                if ($v === null) { $miss[] = $k; continue; }
                if (!is_numeric($v) || $v < 0 || $v > $max) $over[] = "{$k}={$v}（上限{$max}）";
            }
            if (!empty($over)) $why[] = "馬番{$num}: 上限を超えている項目 " . implode('・', $over);
            if (!empty($miss)) $why[] = "馬番{$num}: 採点が無い項目 " . implode('・', $miss)
                                        . '（採点できないなら null のままで構いませんが、理由を missing_reasons に入れてください）';
        }

        $expect = array_fill_keys(array_map('intval', $validNums), true);
        foreach (array_keys($parsed['horses'] ?? []) as $num) {
            if (!isset($expect[(int) $num])) $why[] = "馬番{$num}: 6分前に出走していない馬番が入っている";
        }
        foreach (array_keys($expect) as $num) {
            if (!isset($parsed['horses'][$num])) $why[] = "馬番{$num}: 採点が欠けている（全頭必須）";
        }
        return $why;
    }

    /**
     * 人気帯別回収率の集計（K-3補足）
     *
     * AIが選んだ馬を t_horse_odds_finder_race_result_history の popularity_rank で帯に分類し、
     * 各帯の単勝・複勝回収率を返す。
     *
     * 人気帯:
     *   1_3   : 1〜3番人気
     *   4_6   : 4〜6番人気
     *   7plus : 7番人気以下
     *
     * @return array{1_3: array, 4_6: array, 7plus: array}
     */
    private function _calcAiRecoveryByPopularity(): array
    {
        // AI 選択馬データを全件取得（pickup_horse1〜3）
        // ※ t_horse_odds_finder_ai_analysis_check は現在未使用のためコメントアウト中
        // ※ ai-analysis-check を再有効化する際にコメントを外すこと
        // $checks = DB::table('t_horse_odds_finder_ai_analysis_check')
        //     ->orderBy('date')
        //     ->get(['date', 'kaisuu', 'basho_code', 'day', 'race',
        //            'pickup_horse1', 'pickup_horse2', 'pickup_horse3']);
        $checks = collect([]);

        // 人気帯ごとの集計バケツ
        $buckets = [
            '1_3'   => ['invest' => 0, 'tan_return' => 0, 'fuku_return' => 0, 'count' => 0],
            '4_6'   => ['invest' => 0, 'tan_return' => 0, 'fuku_return' => 0, 'count' => 0],
            '7plus' => ['invest' => 0, 'tan_return' => 0, 'fuku_return' => 0, 'count' => 0],
        ];

        foreach ($checks as $v) {
            // AIが選んだ馬名リスト（null・空文字除外）
            $pickNames = array_values(array_filter([
                $v->pickup_horse1 ?? null,
                $v->pickup_horse2 ?? null,
                $v->pickup_horse3 ?? null,
            ], fn($n) => $n !== null && $n !== ''));

            if (empty($pickNames)) continue;

            // 払戻データを取得（なければスキップ）
            $payout = DB::table('t_horse_odds_finder_race_result_payout')
                ->where('date',       $v->date)
                ->where('kaisuu',     $v->kaisuu)
                ->where('basho_code', $v->basho_code)
                ->where('day',        $v->day)
                ->where('race',       $v->race)
                ->first(['tan', 'fuku']);

            if (!$payout) continue;

            // 払戻マップ（馬番 => 払戻額）
            $tanMap  = $this->_parsePayoutString($payout->tan);
            $fukuMap = $this->_parsePayoutString($payout->fuku);

            // 各選択馬の馬番・人気を race_result_history から取得
            $histRows = DB::table('t_horse_odds_finder_race_result_history')
                ->where('date',       $v->date)
                ->where('kaisuu',     $v->kaisuu)
                ->where('basho_code', $v->basho_code)
                ->where('day',        $v->day)
                ->where('race',       $v->race)
                ->whereIn('name', $pickNames)
                ->get(['name', 'num', 'popularity_rank']);

            foreach ($histRows as $h) {
                $pop = (int) $h->popularity_rank;
                if ($pop <= 0) continue; // 人気不明はスキップ

                // 人気帯を決定
                if ($pop <= 3) {
                    $band = '1_3';
                } elseif ($pop <= 6) {
                    $band = '4_6';
                } else {
                    $band = '7plus';
                }

                $num = ltrim((string) $h->num, '0') ?: '0';

                $buckets[$band]['invest']      += 100;
                $buckets[$band]['tan_return']  += $tanMap[$num]  ?? 0;
                $buckets[$band]['fuku_return'] += $fukuMap[$num] ?? 0;
                $buckets[$band]['count']++;
            }
        }

        // 回収率の計算
        $result = [];
        foreach ($buckets as $band => $b) {
            $result[$band] = [
                'horse_count'  => $b['count'],
                'total_invest' => $b['invest'],
                'tan_return'   => $b['tan_return'],
                'fuku_return'  => $b['fuku_return'],
                'tan_rate'     => $b['invest'] > 0
                    ? round($b['tan_return']  / $b['invest'] * 100, 1)
                    : null,
                'fuku_rate'    => $b['invest'] > 0
                    ? round($b['fuku_return'] / $b['invest'] * 100, 1)
                    : null,
            ];
        }

        return $result;
    }
    // ─────────────────────────────────────────────────────────────────
    // _parseAiHorses()
    // AI 生テキストから選出馬の構造化配列を抽出する
    // 期待フォーマット:
    //   馬番：X、馬名：XXX、人気順: X、6分前オッズ: X.X、おすすめ度: XX、選出理由：〜
    // ─────────────────────────────────────────────────────────────────
    // ─────────────────────────────────────────────────────────────────
    // @ANCHOR-20261004-AUDIT-ALLSCORE  全頭採点（内部用JSON）の読み取りと検証
    //
    // よっしー20261004回答③Aの条件:
    //   ・1st・2ndとも全実出走馬の11項目得点、小計、総合点を取得する
    //   ・馬番の重複・欠落、点数範囲、合計、候補行との一致を検証する
    //   ・2ndの公開候補が0頭でも全頭採点JSONは取得する
    //   ・未定義の点数を0や推測値で補わない（仕様書6.3）
    //
    // @param ?string $jsonRaw      splitAuditJson() が取り出したJSON文字列
    // @param array   $validNums    実出走馬の馬番（int配列）
    // @param array   $publicHorses _parseAiHorses() の出力（候補行との一致検証用）
    // @param string  $aiLabel      '1st' or '2nd'
    // @return array{
    //   ok: bool, horses: array<int, array>, errors: array<string>,
    //   missing: array<int>, duplicated: array<int>, extra: array<int>
    // }
    // ─────────────────────────────────────────────────────────────────
    // ─────────────────────────────────────────────────────────────────
    // @ANCHOR-20261004-FIX-REQUEST  不正回答への修正要求（該当AIにつき1回まで）
    //
    // よっしー20261004回答③A：
    //   「通常のAI呼び出しは2回とし、仕様書にある不正回答への修正要求は、
    //     該当AIにつき1回までの例外として区別してください。
    //     なお無効なら有効な他方を使い、両方無効なら未確定表示とし、
    //     HTTP500にはしないでください。」
    //
    // 仕様書9.2 表11「数値や内訳不一致 → 修正要求は1回。なお無効なら当該回答を
    // 採用せず、有効な他方のデータを使用」。
    //
    // ※通常の2回（1st・2nd各1回）とは別枠。呼んだことを必ずログに残す。
    // ※全頭採点JSONだけを出し直させる。公開候補行は変更させない
    //   （候補が入れ替わると、せっかく検証した公開部分が無駄になるため）。
    //
    // @return ?string 新しい全頭採点JSON（マーカーを外した中身）。失敗時は null
    // ─────────────────────────────────────────────────────────────────
    private function _requestScoreFix(
        string $aiLabel,
        string $originalPrompt,
        string $previousText,
        array  $errors,
        string $raceLabel
    ): ?string {
        $fxAsk = "直前のあなたの回答に、全頭採点（内部用）の不備がありました。\n"
               . "次の指摘をすべて直し、" . self::AUDIT_JSON_BEGIN . " と " . self::AUDIT_JSON_END
               . " で囲んだ全頭採点のJSONだけを、もう一度出力してください。\n"
               . "・公開候補行は出し直さないでください（前回の候補行をそのまま使います）。\n"
               . "・小計と合計は必ず内訳の合計と一致させてください。\n"
               . "・全実出走馬を入れ、馬番の重複・欠落をなくしてください。\n"
               . "・推測値や0で埋めないでください。採点できない項目がある馬は、その馬を出さずに報告してください。\n\n"
               . "【指摘】\n・" . implode("\n・", array_slice($errors, 0, 30)) . "\n";

        \Log::warning("[FIX_REQUEST] 全頭採点の修正要求を1回だけ送る（{$aiLabel}）", [
            'race'       => $raceLabel,
            'AI'         => $aiLabel,
            '版'         => self::ALLOC_SPEC_VERSION,
            '指摘件数'   => count($errors),
            '指摘'       => array_slice($errors, 0, 30),
            '位置づけ'   => '通常の2回とは別枠の例外（該当AIにつき1回まで）',
        ]);

        try {
            if ($aiLabel === '1st') {
                $fxRes = $this->anthropic->sendWithRetry(
                    prompt:      $originalPrompt . "\n\n" . $fxAsk,
                    system:      'あなたは競馬オッズ分析の専門家（1st AI）です。直前の回答の全頭採点JSONだけを、指摘どおりに直して出力してください。公開候補行は出力しません。',
                    maxAttempts: 1,   // 修正要求も1回のみ。2以上にしてはいけない
                    sleepBase:   2,
                    timeout:     90,
                );
                $fxText = $this->anthropic->extractText($fxRes);
            } else {
                $fxHttp = Http::timeout(60)->withHeaders([
                    'Authorization' => 'Bearer ' . env('DEEPSEEK_API_KEY'),
                ])->post('https://api.deepseek.com/v1/chat/completions', [
                    'model'    => 'deepseek-chat',
                    'messages' => [
                        ['role' => 'system', 'content' => 'あなたは競馬オッズ分析の専門家（2nd AI）です。直前の回答の全頭採点JSONだけを、指摘どおりに直して出力してください。公開候補行は出力しません。'],
                        ['role' => 'user',   'content' => $originalPrompt . "\n\n" . $fxAsk],
                    ],
                ]);
                if ($fxHttp->failed()) {
                    \Log::warning("[FIX_REQUEST] 修正要求の通信に失敗（{$aiLabel}・当該回答は採用しない）", [
                        'race'   => $raceLabel,
                        'status' => $fxHttp->status(),
                    ]);
                    return null;
                }
                $fxJson = $fxHttp->json();
                $fxText = trim($fxJson['choices'][0]['message']['content'] ?? '');
            }
        } catch (\Throwable $fxE) {
            \Log::warning("[FIX_REQUEST] 修正要求で例外（{$aiLabel}・当該回答は採用しない）", [
                'race'    => $raceLabel,
                'message' => $fxE->getMessage(),
            ]);
            return null;
        }

        $fxSplit = self::splitAuditJson((string) $fxText);
        if ($fxSplit['json'] === null) {
            \Log::warning("[FIX_REQUEST] 修正要求の回答にも全頭採点JSONが無い（{$aiLabel}）", [
                'race'     => $raceLabel,
                'raw_head' => mb_substr((string) $fxText, 0, 500),
            ]);
            return null;
        }
        return $fxSplit['json'];
    }

    /**
     * @ANCHOR-20261006-SCORE-SOURCE-OF-TRUTH
     * 検証済みの全頭採点だけを取り出す。
     *
     * 20261006 ご指摘②「修正後も不一致なら、その馬の内部採点は未検証として扱い、
     * 検証済み採点を必要とする補充順位に使わない」に対応する。
     * 採点そのものが読めない（ok=false）場合は1頭も使わない。
     *
     * @param  array $res _parseAllHorseScores() の戻り値
     * @return array 馬番 => 採点（検証済みのみ）
     */
    private static function verifiedAllScore(array $res): array
    {
        if (empty($res['ok'])) return [];
        return array_filter(
            $res['horses'] ?? [],
            static fn($h) => !empty($h['verified'])
        );
    }

    private function _parseAllHorseScores(
        ?string $jsonRaw,
        array   $validNums,
        array   $publicHorses,
        string  $aiLabel
    ): array {
        // ══════════════════════════════════════════════════════════════════════
        // @ANCHOR-20261005-ALLSCORE-WARN  致命的な不備と、警告どまりの不備を分ける
        // ══════════════════════════════════════════════════════════════════════
        // 【実測でわかったこと（2026-10-05・10/3の24レースを呼び直し）】
        //   JSON自体は正しく返る（馬番の重複・欠落なし、内訳と小計も一致）。
        //   落ちていたのは「候補行のおすすめ度」と「JSONの総合点」の一致だけで、
        //   78対93、72対66のように大きくずれる。
        //   同じ採点を長い出力の中で2回書かせているため、LLMには再現できない。
        //   これだけで全頭採点を丸ごと捨てると、よっしー回答③Aの目的
        //   「選ばれなかった理由を追えるようにする」が達成できない。
        //
        // 【分け方】
        //   errors   … 採点として使えない（JSONなし・読めない・点数範囲外・
        //               内訳と小計の不一致・馬番の重複・実在しない馬番）
        //   warnings … 使えるが食い違いがある（候補行のおすすめ度との不一致、
        //               公開候補行にあるのにJSONに無い、実出走馬の一部が欠落）
        //   ok は errors が空なら true。warnings は件数と中身を必ず記録する。
        //
        // 【画面と内部値の関係】
        //   画面に出すおすすめ度は候補行の値のまま（PHPは書き換えない）。
        //   JSONの総合点は、候補行に載っていない馬の順位づけと監査にだけ使う。
        //   両者が混ざることはないので、不一致が表示へ影響することはない。
        // ══════════════════════════════════════════════════════════════════════
        // @ANCHOR-20261006-SCORE-SOURCE-OF-TRUTH  点数の正本を1つに決める
        // ══════════════════════════════════════════════════════════════════════
        // 【20261006 ご指摘②】
        //   「公開候補、内部採点、補充候補、統合順位で、どの点数を正とするかを統一する」
        //   「公開候補と内部総合点の不一致は該当AIへの既定の修正要求（最大1回）の対象にする」
        //   「修正後も不一致なら、その馬の内部採点は未検証として扱い、
        //     検証済み採点を必要とする補充順位に使わない。公開候補を保持して続行する」
        //   「JSONの一部欠落は有効な他馬まで捨てる必要はないが、欠落馬を『採点なし』と
        //     明記し、全頭採点完了と数えない。欠落馬の採点を推測して補充しない」
        //
        // 【決めた正本】
        //   ・画面に出す候補行のおすすめ度 … AIの公開候補行の値が正本。PHPは書き換えない。
        //   ・内部採点（JSON総合点）       … 公開候補行と一致した馬だけを「検証済み」とする。
        //   ・補充候補の生成と統合順位      … 検証済みの内部採点だけを使う。
        //     不一致の馬は内部採点を使わない（公開候補行はそのまま残す）。
        //   これで「表示に使う点数」と「選出に使う点数」が同じ馬では必ず一致する。
        //
        // 【出力の意味】
        //   ok          … 採点として読める（JSONあり・点数範囲内・小計一致・重複なし）
        //   needs_fix   … 修正要求の対象（不一致または欠落がある）
        //   complete    … 実出走馬が全頭そろい、全頭が検証済み（＝全頭採点完了）
        //   horses[n]['verified'] … その馬の内部採点を補充順位に使ってよいか
        $out = ['ok' => false, 'horses' => [], 'errors' => [], 'warnings' => [],
                'missing' => [], 'duplicated' => [], 'extra' => [],
                'unverified' => [], 'needs_fix' => false, 'complete' => false,
                'mismatch' => 0];

        if ($jsonRaw === null || trim($jsonRaw) === '') {
            $out['errors'][] = '全頭採点のJSONが無い（マーカーなし、または途中で切れている）';
            return $out;
        }

        $decoded = json_decode($jsonRaw, true);
        if (!is_array($decoded) || !isset($decoded['horses']) || !is_array($decoded['horses'])) {
            $out['errors'][] = 'JSONとして読めない、または horses 配列が無い';
            return $out;
        }

        $validNums = array_map('intval', $validNums);
        $seen      = [];
        foreach ($decoded['horses'] as $row) {
            if (!is_array($row) || !isset($row['n']) || !is_numeric($row['n'])) {
                $out['errors'][] = '馬番(n)の無い行がある';
                continue;
            }
            $num = (int) $row['n'];
            if (isset($seen[$num])) { $out['duplicated'][] = $num; continue; }
            $seen[$num] = true;

            if (!in_array($num, $validNums, true)) { $out['extra'][] = $num; continue; }

            // 11項目の点数範囲
            $conf  = (isset($row['c']) && is_array($row['c'])) ? array_values($row['c']) : null;
            $merit = (isset($row['m']) && is_array($row['m'])) ? array_values($row['m']) : null;
            if ($conf === null || count($conf) !== count(self::CONF_ITEM_MAX)) {
                $out['errors'][] = "馬番{$num}: 信頼度7項目(c)が揃っていない";
                continue;
            }
            if ($merit === null || count($merit) !== count(self::MERIT_ITEM_MAX)) {
                $out['errors'][] = "馬番{$num}: 妙味4項目(m)が揃っていない";
                continue;
            }
            $rangeNg = false;
            foreach (self::CONF_ITEM_MAX as $i => $max) {
                if (!is_numeric($conf[$i]) || $conf[$i] < 0 || $conf[$i] > $max) {
                    $out['errors'][] = "馬番{$num}: 信頼度{$i}項目目が範囲外（0〜{$max}）";
                    $rangeNg = true;
                }
            }
            foreach (self::MERIT_ITEM_MAX as $i => $max) {
                if (!is_numeric($merit[$i]) || $merit[$i] < 0 || $merit[$i] > $max) {
                    $out['errors'][] = "馬番{$num}: 妙味{$i}項目目が範囲外（0〜{$max}）";
                    $rangeNg = true;
                }
            }
            if ($rangeNg) continue;

            // 小計・合計の一致（0や推測値で補わず、合わなければその馬を無効にする）
            $confSum  = array_sum(array_map('floatval', $conf));
            $meritSum = array_sum(array_map('floatval', $merit));
            $cs = isset($row['cs']) && is_numeric($row['cs']) ? (float) $row['cs'] : null;
            $ms = isset($row['ms']) && is_numeric($row['ms']) ? (float) $row['ms'] : null;
            $tt = isset($row['t'])  && is_numeric($row['t'])  ? (float) $row['t']  : null;
            if ($cs === null || abs($cs - $confSum) > 0.001) {
                $out['errors'][] = "馬番{$num}: 信頼度小計(cs)が内訳の合計と一致しない（cs="
                    . var_export($row['cs'] ?? null, true) . " / 内訳合計={$confSum}）";
                continue;
            }
            if ($ms === null || abs($ms - $meritSum) > 0.001) {
                $out['errors'][] = "馬番{$num}: 妙味小計(ms)が内訳の合計と一致しない（ms="
                    . var_export($row['ms'] ?? null, true) . " / 内訳合計={$meritSum}）";
                continue;
            }
            if ($tt === null || abs($tt - ($cs + $ms)) > 0.001) {
                $out['errors'][] = "馬番{$num}: 総合点(t)が小計の合計と一致しない（t="
                    . var_export($row['t'] ?? null, true) . " / cs+ms=" . ($cs + $ms) . '）';
                continue;
            }

            $out['horses'][$num] = [
                // @ANCHOR-20261006-SCORE-SOURCE-OF-TRUTH
                //   公開候補行との突き合わせはこのあと行う。既定は未検証。
                'verified'    => false,
                'unverified_reason' => '公開候補行との突き合わせ前',
                'conf_items'  => array_map('floatval', $conf),
                'conf_sub'    => $cs,
                'merit_items' => array_map('floatval', $merit),
                'merit_sub'   => $ms,
                'total'       => $tt,
                // 能力適性は採点不能なら null のまま（0で補わない）
                'ability'     => (isset($row['a']) && is_numeric($row['a'])) ? (float) $row['a'] : null,
            ];
        }

        // 欠落（実出走馬にいてJSONに無い馬）
        $out['missing']    = array_values(array_diff($validNums, array_keys($out['horses'])));
        $out['duplicated'] = array_values(array_unique($out['duplicated']));
        $out['extra']      = array_values(array_unique($out['extra']));

        // ══════════════════════════════════════════════════════════════════
        // @ANCHOR-20261006-SCORE-SOURCE-OF-TRUTH  馬ごとに検証済みかを決める
        // ══════════════════════════════════════════════════════════════════
        //   公開候補行に載っている馬 … おすすめ度と総合点が一致すれば検証済み
        //   公開候補行に無い馬       … 突き合わせる相手がいないので検証済みとする
        //                              （この馬の点数の正本は内部採点しかない）
        //   不一致の馬               … 未検証。補充順位には使わない
        $mismatch   = 0;
        $publicNums = [];
        foreach ($publicHorses as $ph) {
            $pn = (int) ($ph['num'] ?? 0);
            $publicNums[] = $pn;
            if (!isset($out['horses'][$pn])) {
                // 公開候補にあるのにJSONに無い＝採点なし。推測で補わない。
                $out['warnings'][]   = "馬番{$pn}: 公開候補行にあるがJSONに無い（採点なし）";
                $out['unverified'][] = ['num' => $pn, '理由' => 'JSONに無い（採点なし）'];
                continue;
            }
            $pScore = (float) ($ph['score'] ?? -1);
            if (abs($out['horses'][$pn]['total'] - $pScore) <= 0.001) {
                $out['horses'][$pn]['verified']          = true;
                $out['horses'][$pn]['unverified_reason'] = null;
            } else {
                $mismatch++;
                $out['horses'][$pn]['verified'] = false;
                $out['horses'][$pn]['unverified_reason'] = sprintf(
                    '候補行のおすすめ度(%s)と総合点(%s)が一致しない', $pScore, $out['horses'][$pn]['total']
                );
                $out['warnings'][]   = sprintf(
                    '馬番%d: 候補行のおすすめ度(%s)とJSONの総合点(%s)が一致しない → 内部採点は未検証',
                    $pn, $pScore, $out['horses'][$pn]['total']
                );
                $out['unverified'][] = ['num' => $pn, '理由' => '候補行と総合点が一致しない',
                                        '候補行' => $pScore, 'JSON' => $out['horses'][$pn]['total']];
            }
        }
        // 公開候補行に無い馬は突き合わせる相手がいない。内部採点を正本として扱う。
        foreach ($out['horses'] as $hn => $_hv) {
            if (in_array((int) $hn, $publicNums, true)) continue;
            $out['horses'][$hn]['verified']          = true;
            $out['horses'][$hn]['unverified_reason'] = null;
        }
        // 実出走馬の欠落は「採点なし」。推測で補わない。
        foreach ($out['missing'] as $mn) {
            $out['warnings'][]   = "馬番{$mn}: 実出走馬だがJSONに無い（採点なし）";
            $out['unverified'][] = ['num' => (int) $mn, '理由' => '実出走馬だがJSONに無い（採点なし）'];
        }

        $out['mismatch'] = $mismatch;

        // 採点として読めるか（致命的な不備が無いか）
        $out['ok'] = empty($out['errors'])
                  && empty($out['duplicated'])
                  && empty($out['extra'])
                  && count($out['horses']) > 0;

        // @ANCHOR-20261006-SCORE-SOURCE-OF-TRUTH
        //   修正要求の対象 … 不一致または欠落があるとき
        //   全頭採点完了   … 実出走馬が全頭そろい、全頭が検証済みのとき
        $verifiedCount    = count(array_filter($out['horses'], static fn($h) => !empty($h['verified'])));
        $out['needs_fix'] = (!$out['ok']) || $mismatch > 0 || !empty($out['missing']);
        $out['complete']  = $out['ok']
                         && empty($out['missing'])
                         && $mismatch === 0
                         && $verifiedCount === count($validNums);

        \Log::info("[AUDIT_AI] 全頭採点の検証（{$aiLabel}・@ANCHOR-20261004-AUDIT-ALLSCORE）", [
            'AI'         => $aiLabel,
            '版'         => self::ALLOC_SPEC_VERSION,
            '判定'       => $out['ok'] ? 'OK' : 'NG',
            '取得頭数'   => count($out['horses']),
            '実出走頭数' => count($validNums),
            '欠落'       => $out['missing'],
            '重複'       => $out['duplicated'],
            '実在しない馬番' => $out['extra'],
            'エラー'     => $out['errors'],
            '警告'       => $out['warnings'],
            '候補行との不一致数' => $mismatch,
            '未検証'     => $out['unverified'],
            '全頭採点完了' => $out['complete'] ? 'はい' : 'いいえ',
            '修正要求の対象' => $out['needs_fix'] ? 'はい' : 'いいえ',
            '注記'       => '画面のおすすめ度は候補行の値が正本。内部採点は候補行と一致した馬だけを'
                            . '検証済みとし、補充候補の生成と統合順位には検証済みだけを使う'
                            . '（@ANCHOR-20261006-SCORE-SOURCE-OF-TRUTH）',
        ]);

        return $out;
    }

    private function _parseAiHorses(string $aiText): array
    {
        // 【20261004】内部監査用JSON（@ANCHOR-20261004-AUDIT-ALLSCORE）を必ず落としてから扱う。
        //   公開パーサー・回答判定に内部データを混ぜない（よっしー回答③Aの条件）。
        $aiText = self::publicPart($aiText);
        $horses = [];
        $lines  = explode("\n", $aiText);

        foreach ($lines as $line) {
            $line = trim($line);
            if (empty($line)) continue;

            if (!preg_match(self::PUBLIC_ROW_REGEX, $line, $m)) {
                continue;
            }

            $horses[] = [
                'num'        => (int)   $m[1],
                'name'       => trim(   $m[2]),
                'popularity' => (int)   $m[3],
                'odds_6'     => (float) $m[4],
                'score'      => (int)   $m[5],
                'reason'     => trim(   $m[6]),
            ];
        }

        return $horses;
    }

    // ─────────────────────────────────────────────────────────────────
    // _dbValidateHorses() ── ⑥ AI回答のDB照合強化
    //
    // $aiHorses を参照渡しで受け取り、以下の照合を適用する:
    //   1. 実在馬番チェック → 存在しない馬番のエントリを除去
    //   2. 同一回答内の馬番重複チェック → 後者を除去
    //   3. おすすめ度 0〜100 範囲チェック → 0〜100 にクランプ
    //   4. 人気順のDB照合 → $b6TanPopMap のDB値で上書き
    //   5. 6分前オッズのDB照合 → DBの値で上書き（乖離をLOGに記録）
    //
    // @param array  &$aiHorses   _parseAiHorses() の出力（参照渡し）
    // @param string  $aiLabel    ログ識別子 ('1st' or '2nd')
    // @param array   $validNums  有効な馬番（int）の配列
    // @param array   $popMap     num => 人気順（int）マップ
    // @param array   $oddsMap    num => 6分前単勝オッズ（float）マップ
    // ─────────────────────────────────────────────────────────────────
    private function _dbValidateHorses(
        array  &$aiHorses,
        string  $aiLabel,
        array   $validNums,
        array   $popMap,
        array   $oddsMap
    ): void {
        $seen    = [];
        $removed = [];
        $fixed   = [];
        $fixedRows = [];   // @ANCHOR-20261004-AUDIT-FIX  表10「補正」用の構造化データ

        // ── 【20260928】同一回答内で重複した馬番は「その馬番の全行」を無効化する ──
        //   よっしー20260928指摘：
        //     「同一AIの回答内で馬番が重複した場合、その馬番に該当する行はすべて
        //       無効として除外し、他の有効行は利用する。」
        //   旧実装は先に出た1行を残して2行目以降だけ捨てていた。
        //   どちらが正しい行かAIに聞き直せない以上、重複した馬番は全部捨てる。
        //   @ANCHOR-20260928-DUP-ALL-INVALID
        $dupCount = [];
        foreach ($aiHorses as $dupH) {
            $dupNum = (int)($dupH['num'] ?? -1);
            $dupCount[$dupNum] = ($dupCount[$dupNum] ?? 0) + 1;
        }
        $dupNums = array_keys(array_filter($dupCount, fn($n) => $n >= 2));

        foreach ($aiHorses as $i => &$h) {
            $num = (int)($h['num'] ?? -1);

            // ① 実在馬番チェック
            if (!in_array($num, $validNums, true)) {
                $removed[] = "馬番{$num}（実在せず）";
                unset($aiHorses[$i]);
                continue;
            }

            // ② 重複チェック（重複した馬番は該当行をすべて除外する）
            if (in_array($num, $dupNums, true)) {
                $removed[] = "馬番{$num}（重複のため全行を無効化）";
                unset($aiHorses[$i]);
                continue;
            }
            $seen[$num] = true;

            // ③ おすすめ度 0〜100 範囲チェック
            $score = (int)($h['score'] ?? 0);
            if ($score < 0 || $score > 100) {
                $clamped = max(0, min(100, $score));
                $fixed[] = "馬番{$num} おすすめ度 {$score}→{$clamped}";
                $fixedRows[] = ['馬番' => $num, '項目' => 'おすすめ度',
                                'AI出力値' => $score, 'DB確定値' => $clamped, '根拠' => '0〜100にクランプ'];
                $h['score'] = $clamped;
            }

            // ④ 人気順のDB照合（DB値で上書き）
            if (isset($popMap[$num])) {
                $dbPop  = (int)$popMap[$num];
                $aiPop  = (int)($h['popularity'] ?? 0);
                if ($aiPop !== $dbPop) {
                    $fixed[] = "馬番{$num} 人気順 {$aiPop}→{$dbPop}(DB)";
                    $fixedRows[] = ['馬番' => $num, '項目' => '人気順',
                                    'AI出力値' => $aiPop, 'DB確定値' => $dbPop, '根拠' => 'DB値で上書き'];
                    $h['popularity'] = $dbPop;
                }
            }

            // ⑤ 6分前オッズのDB照合（DB値で上書き）
            // 【20260928 よっしー判断】「DBを正とし、差異があったことはログに残してください」
            //   → 乖離0.15超だけでなく、表示精度（小数第1位）で違えば必ず記録する。
            //   @ANCHOR-20260928-DB-OVERWRITE
            if (isset($oddsMap[$num])) {
                $dbOdds = $oddsMap[$num];
                $aiOdds = (float)($h['odds_6'] ?? 0.0);
                if (round($aiOdds, 1) !== round((float)$dbOdds, 1)) {
                    $fixed[] = sprintf(
                        "馬番{$num} 6分前オッズ %.1f→%.1f(DB)%s",
                        $aiOdds, $dbOdds, (abs($aiOdds - $dbOdds) > 0.15) ? '【乖離大】' : ''
                    );
                    $fixedRows[] = ['馬番' => $num, '項目' => '6分前オッズ',
                                    'AI出力値' => round($aiOdds, 1), 'DB確定値' => round((float) $dbOdds, 1),
                                    '根拠' => (abs($aiOdds - $dbOdds) > 0.15) ? 'DB値で上書き（乖離大）' : 'DB値で上書き'];
                }
                $h['odds_6'] = $dbOdds; // 常にDB値で上書き
            }
        }
        unset($h);

        // 配列を再インデックス
        $aiHorses = array_values($aiHorses);

        if (!empty($removed)) {
            // 【20260928】無効化した行は理由つきで必ず記録する（仕様: 原文・理由をログへ残す）
            \Log::warning("[B16-{$aiLabel}] 無効化した候補行", ['理由' => $removed]);
        }
        if (!empty($fixed)) {
            // 【20260928 よっしー判断】AIの人気順・6分前オッズ・おすすめ度がDBと違う場合、
            //   候補行は消さずDB値で上書きする（行を消すと候補数が減り、頭数不一致につながるため）。
            //   そのうえで「差異があったこと」を必ずログに残す。
            //   @ANCHOR-20260928-DB-OVERWRITE
            \Log::info("[B16-{$aiLabel}] DB値で上書き（行は削除しない）", ['差異' => $fixed]);

            // ── @ANCHOR-20261004-AUDIT-FIX  監査ログ【補正単位】（仕様書9.1 表10）──
            //   保存内容: 馬番、項目、AI出力値、DB確定値、変更時刻、取消更新と再実行履歴
            //   ※変更時刻はJST（サーバのタイムゾーン設定に依らないよう明示する）。
            \Log::info('[AUDIT_FIX] 補正単位の監査ログ（@ANCHOR-20261004-AUDIT-FIX）', [
                'AI'       => $aiLabel,
                '版'       => self::ALLOC_SPEC_VERSION,
                '変更時刻' => (new \DateTimeImmutable('now', new \DateTimeZone('Asia/Tokyo')))
                                  ->format('Y-m-d H:i:s') . ' JST',
                '件数'     => count($fixedRows),
                '補正'     => $fixedRows,
                '無効化'   => $removed,
            ]);
            self::auditFile('AUDIT_FIX', [
                'AI'       => $aiLabel,
                '版'       => self::ALLOC_SPEC_VERSION,
                '変更時刻' => (new \DateTimeImmutable('now', new \DateTimeZone('Asia/Tokyo')))
                                  ->format('Y-m-d H:i:s') . ' JST',
                '件数'     => count($fixedRows),
                '補正'     => $fixedRows,
                '無効化'   => $removed,
            ]);
        }
    }

    // ─────────────────────────────────────────────────────────────────
    // _mergeAiResults()
    // 1st AI / 2nd AI の選出結果を統合する
    //
    // 処理順:
    //   1. 出走頭数別の最終表示上限を決定
    //   2. 断層タイプ別の 2nd AI 独自発見枠上限を決定
    //   3. 馬番をキーに first/second のインデックスを構築
    //   4. matched / firstOnly / secondOnly に分類し統合おすすめ度を算出
    //   5. 2nd AI 独自発見馬の採用条件判定（70点以上 + 根拠キーワード2件以上）
    //   6. メイン候補（matched + firstOnly）をスコア降順にソート
    //   7. 適格な 2nd 独自馬を独自発見枠として追加 or 入れ替え
    //   8. displayLimit 以内にスライスして返す
    //
    // @param array  $firstAiHorses   1st AI の選出馬配列
    // @param array  $secondAiHorses  2nd AI の選出馬配列
    // @param string $gapType         断層タイプ（'A'〜'E'）
    // @param int    $totalHorses     出走頭数
    // @return array                  統合後の最終候補馬リスト（統合おすすめ度降順）
    // ─────────────────────────────────────────────────────────────────
    private function _mergeAiResults(
        array  $firstAiHorses,
        array  $secondAiHorses,
        string $gapType,
        int    $totalHorses,
        int    $pickupUpperMax = 4,   // Block 8: 1〜6番人気上限
        int    $pickupMidMax   = 3,   // Block 8: 7〜10番人気上限
        int    $pickupLowerMax = 2,   // Block 8: 11番人気以下上限
        array  $horseFlagsMap  = [],  // Block 6: F1〜F8フラグマップ（num => [F1..F8]）
        ?\Closure $preCapFilter = null, // 【20260924】最低基準→低配当除外→回収率フィルター（上限適用前に実行）
        array  $protectedNums   = [],   // 【20260927】人気薄の根拠付き保護対象の馬番（@ANCHOR-20260927-PROTECTED-LONGSHOT）
        // 【20261004】配分モードと目標配分（_getAiAnalysisPrompt が確定しプロンプトに凍結した値）
        string $allocMode          = '通常',
        ?int   $allocTargetFav     = null,  // 人気側（1〜6番人気）の目標頭数。null = 既存目安
        ?int   $allocTargetLong    = null,  // 資格あり穴側の目標頭数。null = 既存目安
        array  $allocQualifiedNums = [],    // PHPが資格を確認した7番人気以下の馬番
        // 【20261004 よっしー回答①A-2】検証済みの全頭採点からPHPが候補行を生成するための入力
        //   @ANCHOR-20261004-PHP-CANDIDATE
        array  $allScore1st   = [],  // 馬番 => ['conf_sub','merit_sub','total','ability']（検証OKのみ）
        array  $allScore2nd   = [],
        array  $qualEvidence  = [],  // 馬番 => ['pop','s216','s96','fuku','opi']（プロンプト凍結値）
        array  $dbNameMap     = [],  // 馬番 => 馬名（DB）
        array  $dbOdds6Map    = [],  // 馬番 => 6分前単勝オッズ（DB）
        // @ANCHOR-20261006-QUAL-STATE  馬番 => 資格判定（true=成立 / false=不成立 / null=不明）
        array  $qualState     = []
    ): array {

        // ── Step1: 出走頭数別の【目標数C】 ────────────────────────────
        // 【20260927 → 20260928 仕様変更】
        //   Cは「目標かつ表示上限」。有効候補がC頭未満でもその頭数で表示し、
        //   候補不足を理由に公開を止めない（20260928 レース停止回避追補）。
        //   N≦8 は min(N,4)（旧実装は N=3 でも 4 を返していた）。
        //   @ANCHOR-20260927-TARGET-COUNT
        $displayLimit = self::targetSelectionCount((int) $totalHorses);

        // ── Step2: 断層タイプ別の 2nd AI 独自発見枠上限 ───────────────
        // タイプ A: 原則0頭。おすすめ度80点以上 かつ F1〜F8フラグ true数3個以上の場合のみ
        //           最大1頭まで許可（F1〜F8判定は Block 6 実装後に $secondUniqueLimit を昇格）
        $secondUniqueLimit = match ($gapType) {
            'A'     => 0,   // 原則0頭（Block 6完了後にF1〜F8判定で昇格）
            'B', 'C'=> 1,
            'D', 'E'=> 2,
            default => 1,
        };
        $strictScoreForA = ($gapType === 'A');  // タイプAは80点以上必須（F1〜F8昇格時にも適用）

        // ── Step3: 馬番をキーにしたインデックスを構築 ────────────────
        $firstMap  = [];
        foreach ($firstAiHorses as $h) {
            $firstMap[$h['num']] = $h;
        }
        $secondMap = [];
        foreach ($secondAiHorses as $h) {
            $secondMap[$h['num']] = $h;
        }

        // ── Step4: 候補区分に分類し、統合おすすめ度を算出 ────────────
        $allNums    = array_unique(array_merge(array_keys($firstMap), array_keys($secondMap)));
        $matched    = [];   // 両 AI 一致馬
        $firstOnly  = [];   // 1st AI 独自馬
        $secondOnly = [];   // 2nd AI 独自発見馬

        foreach ($allNums as $num) {
            $inFirst  = isset($firstMap[$num]);
            $inSecond = isset($secondMap[$num]);

            if ($inFirst && $inSecond) {
                // ══════════════════════════════════════════════════════════════
                // @ANCHOR-20261006-MATCH-BONUS  一致加点は「公開候補での一致」
                // ══════════════════════════════════════════════════════════════
                // 【20261006 ご指摘・第7節】
                //   「両AIにあれば平均＋5が、公開候補での一致を指すのか、
                //     両AIの全頭採点があることを指すのかを明確にする必要がある。
                //     全頭採点は原則両AIにあるため、それだけで一致加点すると
                //     当初の『両方が選んだ馬』への加点とは意味が変わる」
                //   → ここで突き合わせている $firstMap / $secondMap は
                //     _parseAiHorses() の出力、すなわち【公開候補行】だけです。
                //     全頭採点（内部用JSON）は一切使っていません。
                //     したがって加点の対象は「両AIが候補として挙げた馬」だけで、
                //     当初の意味から変わっていません。
                // 統合おすすめ度 = 平均 + 5（上限100）
                $avg   = ($firstMap[$num]['score'] + $secondMap[$num]['score']) / 2;
                $score = round(min(100.0, $avg + 5), 1); // ④ 小数第1位保持（Flutter表示時のみint化）

                $matched[] = [
                    'num'        => $num,
                    'name'       => $firstMap[$num]['name'],
                    'score'      => $score,
                    'score_1st'  => $firstMap[$num]['score'],
                    'score_2nd'  => $secondMap[$num]['score'],
                    'popularity' => $firstMap[$num]['popularity'] ?? null,
                    'odds_6'     => $firstMap[$num]['odds_6']    ?? null,
                    'reason'     => $firstMap[$num]['reason'],
                    'reason_2nd' => $secondMap[$num]['reason'],
                    'category'   => 'matched',
                ];

            } elseif ($inFirst) {
                $firstOnly[] = [
                    'num'        => $num,
                    'name'       => $firstMap[$num]['name'],
                    'score'      => $firstMap[$num]['score'],
                    'score_1st'  => $firstMap[$num]['score'],
                    'score_2nd'  => null,
                    'popularity' => $firstMap[$num]['popularity'] ?? null,
                    'odds_6'     => $firstMap[$num]['odds_6']    ?? null,
                    'reason'     => $firstMap[$num]['reason'],
                    'reason_2nd' => null,
                    'category'   => 'first_only',
                ];

            } else {
                $secondOnly[] = [
                    'num'        => $num,
                    'name'       => $secondMap[$num]['name'],
                    'score'      => $secondMap[$num]['score'],
                    'score_1st'  => null,
                    'score_2nd'  => $secondMap[$num]['score'],
                    'popularity' => $secondMap[$num]['popularity'] ?? null,
                    'odds_6'     => $secondMap[$num]['odds_6']    ?? null,
                    'reason'     => $secondMap[$num]['reason'],
                    'reason_2nd' => null,
                    'category'   => 'second_only',
                ];
            }
        }

        // ── Step4b: 【20260924】最低基準→低配当除外→回収率フィルター（仕様: 上限適用より前）──
        $auPreFilterNums = array_map(
            static fn($x) => (int) $x['num'],
            array_merge($matched, $firstOnly, $secondOnly)
        );
        $auDroppedByFilter = [];
        if ($preCapFilter !== null) {
            $b4Pool = $preCapFilter(array_merge($matched, $firstOnly, $secondOnly));
            $auDroppedByFilter = array_values(array_diff(
                $auPreFilterNums,
                array_map(static fn($x) => (int) $x['num'], $b4Pool)
            ));
            $matched    = array_values(array_filter($b4Pool, fn($h) => $h['category'] === 'matched'));
            $firstOnly  = array_values(array_filter($b4Pool, fn($h) => $h['category'] === 'first_only'));
            $secondOnly = array_values(array_filter($b4Pool, fn($h) => $h['category'] === 'second_only'));
        }

        // ── Step5: 2nd AI 独自発見馬の採用条件判定（Block 6: F1〜F8 DB値判定） ──
        // 条件: スコア ≥ 70（タイプA は ≥ 80）+ F1〜F8フラグのうち 2 個以上 true（仕様どおり）
        // 【20260924 修正】F1（基礎点A≥12）・F5（馬ごとの基礎点E≥6）は算出済みのため判定に含める。
        //   旧実装は F1・F5 を数えておらず、根拠のある独自発見馬が採用されにくくなっていた。
        //   不明（null）のフラグは true 数に加えない（false と同じく数えないだけで、減点はしない）。
        $b6ActiveFlags = ['F1', 'F2', 'F3', 'F4', 'F5', 'F6', 'F7', 'F8'];

        // 【20260928 仕様変更（よっしー20260928指摘）】
        //   「2nd AI独自発見枠のF1〜F8・タイプ別上限・比較条件は候補分類と診断ログにのみ使い、
        //     最終候補への追加確保・入替には使わない。」
        //   そのため判定結果は各馬へフラグとして持たせるだけにし、
        //   条件を満たさない2nd独自馬も候補集合に残す（落とさない）。
        //   @ANCHOR-20260928-SECOND-UNIQUE-DIAGNOSTIC-ONLY
        $qualifiedSecondOnly = [];
        foreach ($secondOnly as $i => $h) {
            $minScore = $strictScoreForA ? 80 : 70;

            $flags     = $horseFlagsMap[$h['num']] ?? [];
            $trueCount = 0;
            foreach ($b6ActiveFlags as $f) {
                if (!empty($flags[$f])) $trueCount++;
            }
            $minTrue = $strictScoreForA ? 3 : 2;
            $qualified = ($h['score'] >= $minScore) && ($trueCount >= $minTrue);

            $secondOnly[$i]['evidence_count']       = $trueCount;
            $secondOnly[$i]['second_unique_ok']     = $qualified ? 1 : 0;
            $secondOnly[$i]['second_unique_detail'] = [
                'min_score' => $minScore, 'score' => $h['score'],
                'min_true'  => $minTrue,  'true_count' => $trueCount,
            ];

            if ($qualified) {
                $h['evidence_count']   = $trueCount;
                $qualifiedSecondOnly[] = $h;   // 診断ログ・タイプA昇格判定にのみ使う
            }
        }
        if (count($qualifiedSecondOnly) !== count($secondOnly)) {
            \Log::info('[独自発見] 条件未達の2nd独自馬も候補に残す（診断ログ専用）', [
                '2nd独自馬' => count($secondOnly),
                '条件クリア' => count($qualifiedSecondOnly),
            ]);
        }

        // ── タイプA 独自発見枠昇格（Block 6: F1〜F8フラグ 3 個以上 かつ score ≥ 80） ──
        // gapType=A 時に $secondUniqueLimit を 0 → 1 に昇格し、1 頭だけ採用を許可する
        if ($gapType === 'A' && $secondUniqueLimit === 0) {
            foreach ($qualifiedSecondOnly as $qh) {
                $qFlags = $horseFlagsMap[$qh['num']] ?? [];
                $qCount = 0;
                foreach ($b6ActiveFlags as $f) {
                    if (!empty($qFlags[$f])) $qCount++;
                }
                if ($qCount >= 3 && $qh['score'] >= 80) {
                    $secondUniqueLimit = 1;
//                     \Log::info('[Block6] タイプA 独自発見枠昇格', [
//                         'num'       => $qh['num'],
//                         'name'      => $qh['name'],
//                         'score'     => $qh['score'],
//                         'trueCount' => $qCount,
//                     ]);
                    break;
                }
            }
        }

        // ── Step6〜9: 最終順位の確定と上限適用（仕様【最終順位決定・タイブレーク（正規仕様）】）──────
        // 【20260924 修正】仕様の最終版は「候補同士を場当たり的なペア比較で入れ替えてはならない」とし、
        //   次の固定手順を唯一の正規仕様としている（旧版の「5点以内なら4項目で比べて入れ替え」は廃止）。
        //   ① 全候補（一致馬・1st独自馬・独自発見条件を満たした2nd独自馬）を
        //      統合おすすめ度の降順 → 同点は一致馬優先 → 馬番の小さい順 で並べる
        //   ② その順位のまま、断層位置別・人気帯別上限を超える馬を各人気帯の下位から除く
        //   ③ 2nd独自発見枠（タイプ別上限）を超える2nd独自馬を下位から除く
        //   ④ 出走頭数別上限（4〜7頭）を全体順位の下位から適用する
        //   除外後の空枠を、すでにフィルターで除外された馬で補充しない（ここには入ってこない）。
        //   旧実装は「表示枠いっぱいなら最下位と比べて入れ替え」を人気帯上限より前に行っており、
        //   入れ替えた馬が人気帯上限で落とされる等、仕様の順番と食い違っていた。
        // 【20261004】仕様書6.2「統合順位の同点処理は既存定義を優先し、
        //   最後に有効AIの信頼度平均降順、馬番昇順を用いる。」
        //   信頼度小計は公開候補行には出力されない（プロンプトで出力を禁じている）ため、
        //   全頭採点の内部構造化応答（ステップ6）で取得できたときだけ使う。
        //   取得できない場合は 0 や推測値で補わない（仕様書6.3）。= 従来どおり馬番昇順。
        $confAvg = static function (array $h): ?float {
            $vals = [];
            foreach (['conf_1st', 'conf_2nd'] as $ck) {
                if (isset($h[$ck]) && is_numeric($h[$ck])) $vals[] = (float) $h[$ck];
            }
            return empty($vals) ? null : array_sum($vals) / count($vals);
        };
        $tiebreakMain = function ($a, $b) use ($confAvg) {
            if ($b['score'] !== $a['score']) return $b['score'] <=> $a['score'];
            $catPriority = ['matched' => 0, 'first_only' => 1, 'second_only' => 1];
            $aCat = $catPriority[$a['category'] ?? 'second_only'] ?? 1;
            $bCat = $catPriority[$b['category'] ?? 'second_only'] ?? 1;
            if ($aCat !== $bCat) return $aCat <=> $bCat;
            $aConf = $confAvg($a);
            $bConf = $confAvg($b);
            if ($aConf !== null && $bConf !== null && $aConf !== $bConf) return $bConf <=> $aConf;
            return $a['num'] <=> $b['num'];
        };
        // 【20260928】2nd独自馬は条件の成否にかかわらず候補集合へ入れる
        //   （F1〜F8とタイプ別上限は診断ログ専用。最終候補の確保・入替には使わない）
        $rankedCandidates = array_merge($matched, $firstOnly, $secondOnly);
        usort($rankedCandidates, $tiebreakMain);

        // ══════════════════════════════════════════════════════════════
        // 【20260927 仕様変更】②人気帯別上限・③ 2nd独自発見枠は
        //   「順位づけの優先目安」であり、目標数Cを下回らせるハード上限ではない。
        //   第1パスで目安を尊重して選び、C頭に届かなければ第2パスで順位順に補充する。
        //   ＝ 旧仕様の「上限であり選出義務ではない／頭数を埋めない」は無効。
        //   @ANCHOR-20260927-FILL-TO-TARGET
        // ══════════════════════════════════════════════════════════════
        $upperCount = 0;
        $midCount   = 0;
        $lowerCount = 0;
        $secondUniqueAdded = 0;
        $finalCandidates = [];

        // @ANCHOR-20261004-AUDIT-MERGE  馬番 => 選出・非選出の理由（仕様書9.1 表10「統合」）
        //   仕様書11.3の受入条件「全頭の脱落理由が追跡できること」に対応する。
        $auReason = [];
        // @ANCHOR-20261006-NO-BUYAVOID-IN-SELECTION
        //   最低基準点で第1パスを後回しにした馬番（どの馬に作用したかを必ず残す）
        $slotDeferMin = [];
        // @ANCHOR-20261004-PHP-CANDIDATE  PHPが全頭採点から生成した候補行（監査に載せる）
        $pgGenerated = [];

        // ══════════════════════════════════════════════════════════════
        // 【20261004 仕様変更】@ANCHOR-20261004-SLOT-RESERVE
        //   仕様書6.1⑤「人気側と資格あり穴側から、それぞれ目標頭数を統合順位順に
        //   確保する。全体上位C頭の再抽出で穴枠を消さない。」
        //   目標配分が決まっている場合（C=7の通常／中／強、C=4〜6の中・強）は
        //   人気帯別の目安ではなく、人気側枠・資格あり穴側枠の2本で確保する。
        //   目標配分が null（C=4〜6の通常、Cが4〜7以外）は既存目安を維持する。
        // ══════════════════════════════════════════════════════════════
        $allocQualifiedNums = array_values(array_unique(array_map('intval', $allocQualifiedNums)));
        //   フラグ OFF（仕様書11.2の巻き戻し）のときは枠確保を使わず、
        //   人気帯別の目安＋旧保護枠（2026-09-28時点の安定動作）に戻す。
        $allocFeatureOn = self::allocFeatureEnabled();
        $allocSlotMode  = ($allocFeatureOn && $allocTargetFav !== null && $allocTargetLong !== null);

        if ($allocSlotMode) {
            $slotFav = 0; $slotLong = 0;
            foreach ($rankedCandidates as $h) {
                $num = (int) $h['num'];
                if (count($finalCandidates) >= $displayLimit) {
                    $auReason[$num] = $auReason[$num] ?? '第1パスは目標数Cで打ち切り';
                    continue;   // ④ 目標数C（以降も理由を記録するため break しない）
                }
                // ══════════════════════════════════════════════════════════
                // @ANCHOR-20261006-NO-BUYAVOID-IN-SELECTION
                //   購入回避フラグは選出順位に効かせない
                // ══════════════════════════════════════════════════════════
                // 【20261006 ご指摘③】
                //   「第152項（購入回避の印がある馬は最初の枠確保では選ばない）と
                //     第162項（購入判断だけに使う）が一致していない。
                //     最初にほかの馬で枠が埋まれば、後回しの馬は戻れない。
                //     購入回避フラグだけで初回選出を後回しにしているなら、162項に合わせる」
                //   → buy_avoid_longshot を第1パスの後回し条件から外した。
                //     このフラグは馬券判定を「見送り」「監視」にするためだけに使う。
                //   ※最低基準点（below_min_score）は購入判断とは別の論点なので残す。
                //     どの馬に作用したかは $auReason と下の集計で必ず記録する。
                if (!empty($h['below_min_score'])) {
                    $auReason[$num] = '最低基準点未満（第1パスでは選ばない・第2パスで拾う）';
                    $slotDeferMin[] = $num;
                    continue;
                }
                $pop    = (int) ($h['popularity'] ?? 0);
                $isFav  = ($pop >= 1 && $pop <= 6);
                $isLong = in_array($num, $allocQualifiedNums, true);
                if ($isFav && $slotFav < $allocTargetFav) {
                    $slotFav++;
                    $auReason[$num] = "選出（人気側枠 {$slotFav}/{$allocTargetFav}）";
                } elseif ($isLong && $slotLong < $allocTargetLong) {
                    $slotLong++;
                    $auReason[$num] = "選出（資格あり穴側枠 {$slotLong}/{$allocTargetLong}）";
                } else {
                    // 枠が埋まっている、または資格のない7番人気以下
                    //   （根拠の弱い穴馬を数合わせで穴枠に入れない・仕様書6.2）
                    if ($isFav) {
                        $auReason[$num] = "人気側枠が満杯（{$allocTargetFav}頭）";
                    } elseif ($isLong) {
                        $auReason[$num] = "資格あり穴側枠が満杯（{$allocTargetLong}頭）";
                    } else {
                        $auReason[$num] = '資格未達の7番人気以下（穴枠に入れない）';
                    }
                    continue;
                }
                if (($h['category'] ?? '') === 'second_only') $secondUniqueAdded++;
                $finalCandidates[] = $h;
            }
            // @ANCHOR-20261005-AUX-NEVER-BREAKS
            //   下のPHP候補生成は20261004で追加した新しい経路で、
            //   検証済み全頭採点が揃った本番でしか動かない。
            //   ここで例外が出ても、すでに確保した枠（$finalCandidates）は捨てない。
            try {
            // ══════════════════════════════════════════════════════════════
            // @ANCHOR-20261004-PHP-CANDIDATE
            //   よっしー20261004回答①A-2：
            //     「検証済みの全頭採点を使い、PHPで候補行と定型の選出理由を生成してください。
            //       ・穴側の優先枠は、仕様書の資格条件を満たした馬から統合順位順に選ぶ。
            //       ・理由文には確認できた入力値と時点だけを使い、点数・能力評価・根拠を
            //         推測で補わない。
            //       ・有効な採点や資格馬が不足した場合は、既定の降格・補充ルールに従い、
            //         それでも不足すれば確認済みの頭数で公開する。
            //       ・補充した馬番、採点、根拠、選出経路をログに残す。」
            //   仕様書6.3・受入試験T14に対応する。
            //   両AIの公開候補行に無い馬でも、検証済みの全頭採点があれば候補行を起こす。
            //   採点が無い馬は作らない（推測で埋めない）。
            // ══════════════════════════════════════════════════════════════
            $phpGenLog = [];
            if ($slotLong < $allocTargetLong && count($finalCandidates) < $displayLimit) {
                $pgPicked = array_map(static fn($x) => (int) $x['num'], $finalCandidates);

                // 能力適性の点数から評価区分を出す（A/B/C/D。点数が無ければ不明）
                $pgGrade = static function (?float $a): string {
                    if ($a === null) return '不明（採点不可）';
                    if ($a >= 80) return 'A（' . (int) round($a) . '点）';
                    if ($a >= 70) return 'B（' . (int) round($a) . '点）';
                    if ($a >= 60) return 'C（' . (int) round($a) . '点）';
                    return 'D（' . (int) round($a) . '点）';
                };
                // 定型の選出理由。確認できた入力値と時点だけを使い、無い値は書かない。
                $pgReason = static function (int $num, array $ev, ?float $s1, ?float $s2, string $grade): string {
                    $parts = [];
                    $parts[] = '能力適性:' . $grade . '。';
                    $parts[] = 'PHPが検証済みの全頭採点から生成した候補です。';
                    if (isset($ev['s216']) && $ev['s216'] !== null) {
                        $parts[] = sprintf('複勝最小オッズが21分前→6分前で%.2f%%短縮。', $ev['s216']);
                    }
                    if (isset($ev['s96']) && $ev['s96'] !== null) {
                        $parts[] = sprintf('9分前→6分前で%.2f%%短縮。', $ev['s96']);
                    }
                    if (isset($ev['pop']) && $ev['pop'] !== null
                        && isset($ev['fuku']) && $ev['fuku'] !== null) {
                        $parts[] = sprintf('6分前は単勝%d番人気に対し複勝%d番人気（差%d）。',
                            (int) $ev['pop'], (int) $ev['fuku'], (int) $ev['pop'] - (int) $ev['fuku']);
                    }
                    if (isset($ev['opi']) && $ev['opi'] !== null) {
                        $parts[] = sprintf('予測補正OPIは%.2f。', $ev['opi']);
                    }
                    $sc = [];
                    if ($s1 !== null) $sc[] = sprintf('1st %.1f点', $s1);
                    if ($s2 !== null) $sc[] = sprintf('2nd %.1f点', $s2);
                    if (!empty($sc)) {
                        $parts[] = '全頭採点の総合点は' . implode('／', $sc) . '（検証済み）。';
                    }
                    return implode('', $parts);
                };

                $pgPool = [];
                foreach ($allocQualifiedNums as $pgNum) {
                    if (in_array($pgNum, $pgPicked, true)) continue;
                    // 公開候補行にある馬は枠確保で扱う（ここで二重に起こさない）
                    if (isset($firstMap[$pgNum]) || isset($secondMap[$pgNum])) continue;

                    $pgS1 = isset($allScore1st[$pgNum]['total']) ? (float) $allScore1st[$pgNum]['total'] : null;
                    $pgS2 = isset($allScore2nd[$pgNum]['total']) ? (float) $allScore2nd[$pgNum]['total'] : null;
                    if ($pgS1 === null && $pgS2 === null) continue;   // 検証済み採点なし → 作らない

                    // 統合式は公開候補と同じ：両AIにあれば平均+5（上限100）、片方だけならその点
                    $pgScore = ($pgS1 !== null && $pgS2 !== null)
                        ? round(min(100.0, ($pgS1 + $pgS2) / 2 + 5), 1)
                        : (float) ($pgS1 ?? $pgS2);

                    $pgAb = $allScore1st[$pgNum]['ability'] ?? $allScore2nd[$pgNum]['ability'] ?? null;
                    $pgEv = $qualEvidence[$pgNum] ?? [];

                    $pgPool[] = [
                        'num'        => $pgNum,
                        'name'       => $dbNameMap[$pgNum] ?? ('馬' . $pgNum),
                        'score'      => $pgScore,
                        'score_1st'  => $pgS1,
                        'score_2nd'  => $pgS2,
                        'popularity' => isset($pgEv['pop']) && $pgEv['pop'] !== null ? (int) $pgEv['pop'] : null,
                        'odds_6'     => $dbOdds6Map[$pgNum] ?? null,
                        'reason'     => $pgReason($pgNum, $pgEv, $pgS1, $pgS2,
                                            $pgGrade(is_numeric($pgAb) ? (float) $pgAb : null)),
                        'reason_2nd' => null,
                        'category'   => 'php_generated',
                        'conf_1st'   => $allScore1st[$pgNum]['conf_sub'] ?? null,
                        'conf_2nd'   => $allScore2nd[$pgNum]['conf_sub'] ?? null,
                    ];
                }

                // 統合順位順（点数降順・同点は馬番昇順）に穴側の残り枠へ入れる
                usort($pgPool, static fn($a, $b) => ($b['score'] <=> $a['score']) ?: ($a['num'] <=> $b['num']));
                foreach ($pgPool as $pgRow) {
                    if ($slotLong >= $allocTargetLong) break;
                    if (count($finalCandidates) >= $displayLimit) break;
                    $slotLong++;
                    $finalCandidates[] = $pgRow;
                    $pgGenerated[]     = $pgRow;
                    $auReason[(int) $pgRow['num']] =
                        "選出（資格あり穴側枠 {$slotLong}/{$allocTargetLong}・PHPが全頭採点から生成）";
                    $phpGenLog[] = [
                        '馬番'   => $pgRow['num'],
                        '馬名'   => $pgRow['name'],
                        '人気'   => $pgRow['popularity'],
                        '統合点' => $pgRow['score'],
                        '1st総合' => $pgRow['score_1st'],
                        '2nd総合' => $pgRow['score_2nd'],
                        '根拠'   => $qualEvidence[(int) $pgRow['num']] ?? [],
                        '選出経路' => '資格あり → 公開候補行なし → 検証済み全頭採点から候補行を生成 → 穴側枠へ',
                        '理由文' => $pgRow['reason'],
                    ];
                }

                if (!empty($phpGenLog)) {
                    \Log::info('[PHP_CANDIDATE] 全頭採点から候補行を生成して穴側枠を補充（@ANCHOR-20261004-PHP-CANDIDATE）', [
                        '配分モード' => $allocMode,
                        '目標配分'   => "{$allocTargetFav}＋{$allocTargetLong}",
                        '生成頭数'   => count($phpGenLog),
                        '内訳'       => $phpGenLog,
                    ]);
                }
                // 生成しても穴側枠が埋まらない場合は、不足していることを必ず残す。
                //   よっしー回答①A-2「それでも不足すれば確認済みの頭数で公開する」。
                if ($slotLong < $allocTargetLong) {
                    \Log::info('[PHP_CANDIDATE] 穴側枠が埋まらないまま確定（推測で作らない）', [
                        '配分モード'   => $allocMode,
                        '目標配分'     => "{$allocTargetFav}＋{$allocTargetLong}",
                        '確保済み穴側' => $slotLong,
                        '不足'         => $allocTargetLong - $slotLong,
                        '生成頭数'     => count($phpGenLog),
                        '資格あり馬番' => $allocQualifiedNums,
                        '理由'         => '資格馬に検証済みの全頭採点が無い、または全員すでに候補',
                    ]);
                }
            }
            } catch (\Throwable $pgE) {
                // @ANCHOR-20261005-AUX-NEVER-BREAKS
                \Log::error('[PHP_CANDIDATE] 候補行の生成に失敗（確保済みの枠で続行）', [
                    '配分モード' => $allocMode,
                    '確保頭数'   => count($finalCandidates),
                    'message'    => $pgE->getMessage(),
                    'file'       => $pgE->getFile() . ':' . $pgE->getLine(),
                ]);
            }

            \Log::info('[配分] 枠確保の結果（@ANCHOR-20261004-SLOT-RESERVE）', [
                '配分モード' => $allocMode,
                '目標配分'   => "{$allocTargetFav}＋{$allocTargetLong}",
                '実配分'     => "{$slotFav}＋{$slotLong}",
                '目標数C'    => $displayLimit,
                '確保頭数'   => count($finalCandidates),
                '人気側不足' => max(0, $allocTargetFav  - $slotFav),
                '穴側不足'   => max(0, $allocTargetLong - $slotLong),
                '資格あり馬番' => $allocQualifiedNums,
            ]);
        } else {

        foreach ($rankedCandidates as $h) {
            $num = (int) $h['num'];
            if (count($finalCandidates) >= $displayLimit) {
                $auReason[$num] = $auReason[$num] ?? '第1パスは目標数Cで打ち切り';
                continue;   // ④ 目標数C
            }
            $pop = (int) ($h['popularity'] ?? 0);
            // ② 人気帯別の優先目安（1〜6番人気 / 7〜10番人気 / 11番人気以下）
            if ($pop >= 1 && $pop <= 6) {
                if ($upperCount >= $pickupUpperMax) {
                    $auReason[$num] = "1〜6番人気の目安を超過（{$pickupUpperMax}頭）";
                    continue;
                }
            } elseif ($pop >= 7 && $pop <= 10) {
                if ($midCount >= $pickupMidMax) {
                    $auReason[$num] = "7〜10番人気の目安を超過（{$pickupMidMax}頭）";
                    continue;
                }
            }
            // 【20261004 廃止】11番人気以下だけの最大1〜2頭制限
            //   仕様書6.2「11人気以下だけの最大1〜2頭制限は廃止する」。
            //   フラグ OFF のときだけ旧上限を適用する（巻き戻し用）。
            elseif (!$allocFeatureOn && $lowerCount >= $pickupLowerMax) {
                $auReason[$num] = "11番人気以下の旧上限を超過（{$pickupLowerMax}頭・可変配分を無効にしているため適用）";
                continue;
            }
            // ③ 2nd独自発見枠（タイプ別上限）
            //   【20260928 仕様変更】上限を超えても候補を落とさない。
            //   仕様「タイプ別上限は候補分類と診断ログにのみ使い、
            //   最終候補への追加確保・入替には使わない」に従い、記録だけ残す。
            if (($h['category'] ?? '') === 'second_only') {
                $secondUniqueAdded++;
            }
            // ⑤ 【20260927】最低基準点未満は第1パスでは選ばない
            //   （除外ではなく後回し。C頭に届かなければ第2パスで拾い上げる）
            //   @ANCHOR-20261006-NO-BUYAVOID-IN-SELECTION
            //     購入回避フラグ（buy_avoid_longshot）はここから外した。上の枠確保側と同じ理由。
            if (!empty($h['below_min_score'])) {
                if (($h['category'] ?? '') === 'second_only') $secondUniqueAdded--;   // 枠を戻す
                $auReason[$num] = '最低基準点未満（第1パスでは選ばない・第2パスで拾う）';
                $slotDeferMin[] = $num;
                continue;
            }
            if ($pop >= 1 && $pop <= 6)       $upperCount++;
            elseif ($pop >= 7 && $pop <= 10)  $midCount++;
            else                              $lowerCount++;
            $auReason[$num] = '選出（人気帯別の目安内）';
            $finalCandidates[] = $h;
        }

        }   // ← if ($allocSlotMode) ... else の閉じ

        // ── 第2パス: 目標数C頭の確保 ──────────────────────────────────
        //   優先目安に触れて落ちた馬を、統合おすすめ度の順位に従って補充する。
        //   AIが出力していない馬は $rankedCandidates に入っていないため、
        //   ここで新規に馬を発明することはない（仕様の禁止事項を守る）。
        // ══════════════════════════════════════════════════════════════════
        // @ANCHOR-20261014-FILL-MODE  補充方式A/B/Cで扱いを変える
        // ══════════════════════════════════════════════════════════════════
        //   監査ログに残すため、第2パスの外で宣言しておきます。
        $fillMode    = self::fillMode();
        $mcSkipWeak  = [];   // 補充に使わなかった「資格なしの7番人気以下」
        $mcFilled    = [];   // 補充枠に入れた馬番（通常選出と区別する）
        $mcFillWhy   = [];   // 馬番 => 補充の根拠（監査ログ用）

        if (count($finalCandidates) < $displayLimit) {
            $mcPicked    = array_map(static fn($x) => (int) $x['num'], $finalCandidates);
            foreach ($rankedCandidates as $h) {
                if (count($finalCandidates) >= $displayLimit) break;
                $fNum = (int) $h['num'];
                if (in_array($fNum, $mcPicked, true)) continue;

                $fPop        = (int) ($h['popularity'] ?? 0);
                $fQualified  = in_array($fNum, $allocQualifiedNums, true);
                $fUnqualLong = ($allocSlotMode && $fPop >= 7 && !$fQualified);

                if ($fUnqualLong) {
                    // 【20261004】仕様書6.2「足りない枠は未選出全頭の順位で補い、
                    //   根拠の弱い穴馬を数合わせで強制しない。」
                    //   前半を採るか後半を採るかが方式の違いです。
                    //   判定は fillAllowUnqualified() に寄せてあり、
                    //   --v04-test の FM-T01〜FM-T11 で検証しています。
                    $fInd   = self::$v04LastEvidence[$fNum]['独立群数'] ?? null;
                    $fJudge = self::fillAllowUnqualified(
                        $fillMode, ($fInd === null) ? null : (int) $fInd);
                    if (!$fJudge['allow']) {
                        $mcSkipWeak[]    = $fNum;
                        $auReason[$fNum] = $fJudge['reason'];
                        continue;
                    }
                    // ご依頼②「7番人気以下の補充馬は、通常候補と区別できるようにする」
                    // ご依頼③「補充馬を自動的に購入推奨しない」
                    $h['fill_slot']             = true;
                    $h['fill_slot_unqualified'] = true;
                    $h['fill_mode']             = $fillMode;
                    $mcFilled[] = $fNum;

                    // ご依頼「断層・時系列オッズ・資金流入・単複差・期待値などの
                    //   選出根拠を監査ログに残す」への対応。
                    //   v0.4の独立根拠5系統がそれぞれに対応しています。
                    //     market        … 単複の絶対短縮（時系列オッズ・資金流入）
                    //     gap           … 断層の位置と好走根拠
                    //     win_place     … 単勝と複勝の支持差（単複差）
                    //     similar_value … 母数確認済みの類似統計・予測補正OPI（期待値代理）
                    //     ability       … 過去能力・同条件適性
                    $fEv = self::$v04LastEvidence[$fNum] ?? null;
                    $mcFillWhy[$fNum] = [
                        '人気'       => $fPop,
                        '統合点'     => $h['score'] ?? null,
                        '資格'       => '未達（旧 F AND (R OR O)）',
                        '補充方式'   => $fillMode,
                        '独立根拠'   => ($fEv === null) ? '記録なし' : [
                            '5系統'   => $fEv['families']   ?? null,
                            '独立群'   => $fEv['独立群']     ?? null,
                            '独立群数' => $fEv['独立群数']   ?? null,
                            'Tier'     => $fEv['tier']       ?? null,
                            // @ANCHOR-20261014-EVIDENCE-VALUES  判定に使った実数値
                            //   理由文だけでなく、短縮率・人気順位差・断層・OPI・
                            //   類似統計の母数などの数値をそのまま残します。
                            '判定数値' => $fEv['判定数値']   ?? null,
                        ],
                        '購入推奨'   => false,
                        '購入見送り' => [
                            '最低基準点未満' => !empty($h['below_min_score']),
                            '低配当'         => !empty($h['buy_avoid_low_payout']),
                            '回収率40%未満'  => !empty($h['buy_avoid_recovery']),
                            '大穴条件の不成立' => !empty($h['buy_avoid_longshot']),
                        ],
                    ];
                    $auReason[$fNum] = $fJudge['reason'];
                } else {
                    $auReason[$fNum] = '選出（第2パスで順位順に補充）';
                }
                $finalCandidates[] = $h;
                $mcPicked[]        = $fNum;
            }
            if (!empty($mcSkipWeak)) {
                \Log::info('[配分] 資格なしの7番人気以下は数合わせに使わなかった', [
                    '配分モード' => $allocMode,
                    '対象馬番'   => $mcSkipWeak,
                    '目標数C'    => $displayLimit,
                    '確定頭数'   => count($finalCandidates),
                ]);
            }
            usort($finalCandidates, $tiebreakMain);

            if (count($finalCandidates) < $displayLimit) {
                // 【20260928】候補不足は部分表示で続行する（公開停止・HTTP 500 は禁止）
                \Log::warning('[PREDICTION_PARTIAL] 有効候補が目標数Cに届かない（その頭数で部分表示）', [
                    '目標数C'   => $displayLimit,
                    '確定頭数'  => count($finalCandidates),
                    '不足数'    => $displayLimit - count($finalCandidates),
                    '候補総数'  => count($rankedCandidates),
                ]);
            } else {
                \Log::info('[目標数] 優先目安だけではC頭に届かないため順位順に補充', [
                    '目標数C'  => $displayLimit,
                    '確定頭数' => count($finalCandidates),
                ]);
            }
        }

        // ══════════════════════════════════════════════════════════════════════
        // @ANCHOR-20261005-NEVER-EMPTY  候補0頭だけは最後の手段で避ける
        // ══════════════════════════════════════════════════════════════════════
        // 枠確保モードでは、資格のない7番人気以下を第1パスでも第2パスでも使わない
        // （仕様書6.2「根拠の弱い穴馬を数合わせで強制しない」）。
        // そのため、AIの候補が「資格なしの7番人気以下」だけだったレースでは
        // 最終候補が0頭になり、画面に何も出なくなる。
        // AIが候補を出しているのに画面が空になるのは、仕様を守った結果としても
        // 利用者から見れば障害と同じなので、0頭のときだけ順位順に補充する。
        //   ・発動するのは「0頭になる場合」だけ。C頭への数合わせには使わない
        //   ・AIが出していない馬は追加しない（$rankedCandidates の中だけ）
        //   ・発動したら \Log::error で残す（LOG_LEVEL=error でも消えない）
        // 【20261006 ご指摘④で定義を明文化】
        //   ・発動条件　… 最終候補が0頭、かつAIが出した候補（$rankedCandidates）が1頭以上ある
        //                  有効なAI回答が無い場合（未確定）はここへ来ないので対象外。
        //                  入力が混在したレースも未確定で返るため対象外。
        //   ・補充上限　… 目標数C。ただし「0頭を避ける」のが目的なので、
        //                  資格の状態で優先順をつけ、必要最小限から順に入れる。
        //   ・優先順　　… ①資格が不明な馬（データ欠損で確認できなかっただけ。
        //                    仕様書の三値判定で「不明を不成立として扱わない」に合わせる）
        //                  ②資格が不成立の馬（確認できて満たさなかった）
        //                  どちらも統合おすすめ度の順位順。
        //   ・選出理由　… 「例外補充」と明記し、通常の資格あり候補と区別する。
        //   ・記録　　　… 監査ログに「例外補充」として別立てで残し、集計でも区別する。
        $neExceptionNums = [];
        if (empty($finalCandidates) && !empty($rankedCandidates)) {
            // 資格の状態で2群に分ける（$qualState が読めなければ全て「不明」扱い）
            $neUnknown = [];   // 資格不明
            $neFailed  = [];   // 資格不成立
            foreach ($rankedCandidates as $neH) {
                $neN = (int) $neH['num'];
                $neP = (int) ($neH['popularity'] ?? 0);
                if ($neP >= 1 && $neP <= 6) { $neUnknown[] = $neH; continue; }  // 人気側は資格の対象外
                $neS = array_key_exists($neN, $qualState) ? $qualState[$neN] : null;
                if ($neS === false) { $neFailed[] = $neH; } else { $neUnknown[] = $neH; }
            }

            foreach ([['不明または資格対象外', $neUnknown], ['不成立', $neFailed]] as [$neLabel, $neList]) {
                foreach ($neList as $neH) {
                    if (count($finalCandidates) >= $displayLimit) break 2;
                    $neN = (int) $neH['num'];
                    $finalCandidates[]  = $neH;
                    $neExceptionNums[]  = ['num' => $neN, '資格' => $neLabel,
                                           'おすすめ度' => $neH['score'] ?? null,
                                           '人気' => (int) ($neH['popularity'] ?? 0)];
                    $auReason[$neN]     = "例外補充（候補0頭を避けるため・資格{$neLabel}・統合順位順）";
                }
            }
            usort($finalCandidates, $tiebreakMain);
            \Log::error('[NEVER_EMPTY] 資格条件で候補が0頭になったため例外補充した', [
                '配分モード'   => $allocMode,
                '目標配分'     => ($allocTargetFav === null) ? '既存目安' : "{$allocTargetFav}＋{$allocTargetLong}",
                '目標数C'      => $displayLimit,
                '補充上限'     => $displayLimit,
                '例外補充'     => $neExceptionNums,
                '候補総数'     => count($rankedCandidates),
                '資格あり馬番' => $allocQualifiedNums,
                '資格判定の読み戻し' => empty($qualState) ? '読めなかった（全て不明として扱った）' : '読めた',
                '注記'         => '仕様書6.2の正式な例外（20261006 ご指摘④で定義）。'
                                  . '通常の資格あり候補とは区別して集計する',
            ]);
        }

        // ── 人気薄の根拠付き保護枠（最大1頭）───────────────────────────
        //   @ANCHOR-20260927-PROTECTED-LONGSHOT
        //   C≧4 で、最終候補に保護対象が1頭もいないときだけ、
        //   統合おすすめ度が最高の対象馬1頭を採用し、通常順位の最下位と入れ替える。
        //   この保護枠は「固定上位C頭のみ」「2nd独自発見のタイプ別上限」に優先する。
        //   AIが出力していない馬は追加できない（1st・2ndどちらも出していなければ通常候補で続行）。
        // ══════════════════════════════════════════════════════════════
        // 【20261004 廃止】人気薄の根拠付き保護枠（旧 @ANCHOR-20260927-PROTECTED-LONGSHOT）
        //   仕様書6.2「旧保護対象は参考入力とする。無条件の1頭入替、別枠追加、
        //   11人気以下だけの最大1〜2頭制限は廃止する。資格馬は全て同じ穴側の
        //   配分内で比較する。」
        //   → 保護対象は資格F/R/Oの入力として使うだけにし、最下位との入替はしない。
        //     コードは削除せずコメントアウトで残す。
        //   @ANCHOR-20261004-PROTECTED-REFERENCE-ONLY
        // ══════════════════════════════════════════════════════════════
        if (!empty($protectedNums)) {
            $protectedNums = array_map('intval', $protectedNums);
            $prInFinal = [];
            foreach ($finalCandidates as $h) {
                if (in_array((int) $h['num'], $protectedNums, true)) $prInFinal[] = (int) $h['num'];
            }
            \Log::info('[保護枠] 参考入力として記録（入替はしない・@ANCHOR-20261004-PROTECTED-REFERENCE-ONLY）', [
                '対象馬番'       => $protectedNums,
                '最終候補に居る' => $prInFinal,
                '配分モード'     => $allocMode,
                '資格あり馬番'   => $allocQualifiedNums,
            ]);
        }
        // ── 旧保護枠の入替処理（フラグ OFF のときだけ動く・仕様書11.2の巻き戻し先）──
        //   フラグ ON では上の @ANCHOR-20261004-PROTECTED-REFERENCE-ONLY が働き、
        //   ここは条件で素通りする。コードは消さずに残す。
        if (!$allocFeatureOn && $displayLimit >= 4 && !empty($protectedNums)) {
            $protectedNums  = array_map('intval', $protectedNums);
            $mcHasProtected = false;
            foreach ($finalCandidates as $h) {
                if (in_array((int) $h['num'], $protectedNums, true)) { $mcHasProtected = true; break; }
            }

            if (!$mcHasProtected) {
                // 採用候補は「AIが実際に出力した馬」に限る。
                // 優先順は 一致馬 → 1st独自 → 2nd独自（発見条件クリア）→ 2nd独自（条件未達）。
                $mcPool = [];
                $mcSeen = [];
                foreach ([$matched, $firstOnly, $qualifiedSecondOnly, $secondOnly] as $mcGroup) {
                    foreach ($mcGroup as $mcH) {
                        $mcNum = (int) $mcH['num'];
                        if (isset($mcSeen[$mcNum]))                          continue;
                        if (!in_array($mcNum, $protectedNums, true))          continue;
                        $mcSeen[$mcNum] = true;
                        $mcPool[]       = $mcH;
                    }
                }

                if (!empty($mcPool)) {
                    usort($mcPool, $tiebreakMain);   // 統合おすすめ度最高・同点は一致馬優先→馬番小
                    $mcPick = $mcPool[0];

                    if (($mcPick['category'] ?? '') === 'second_only') {
                        \Log::warning('[保護枠] 1st AIが保護対象を出力していないため2nd AI側から採用', [
                            'num'      => $mcPick['num'],
                            'name'     => $mcPick['name'] ?? '',
                            '対象馬番' => $protectedNums,
                        ]);
                    }

                    $mcDropped = array_pop($finalCandidates);   // 通常順位の最下位を外す
                    $finalCandidates[] = $mcPick;
                    usort($finalCandidates, $tiebreakMain);

                    \Log::info('[保護枠] 人気薄の保護対象を1頭採用（最下位と入替）', [
                        '採用' => [
                            'num'   => $mcPick['num'],
                            'name'  => $mcPick['name']  ?? '',
                            'score' => $mcPick['score'] ?? null,
                            'pop'   => $mcPick['popularity'] ?? null,
                        ],
                        '除外' => [
                            'num'   => $mcDropped['num'],
                            'name'  => $mcDropped['name']  ?? '',
                            'score' => $mcDropped['score'] ?? null,
                            'pop'   => $mcDropped['popularity'] ?? null,
                        ],
                        '対象馬番' => $protectedNums,
                    ]);
                } else {
                    \Log::warning('[保護枠] 両AIが保護対象を出力していないため通常候補で続行', [
                        '対象馬番' => $protectedNums,
                    ]);
                }
            }
        }

        // ═══════════════════════════════════════════════════════════════════════
        // @ANCHOR-20261004-AUDIT-MERGE  監査ログ【統合単位】（仕様書9.1 表10）
        // ═══════════════════════════════════════════════════════════════════════
        //   保存内容: 統合式の版、統合点と順位、帯内順位、選出と非選出理由、購入見送りフラグ
        //   ※ここは診断専用。失敗しても予測を止めない。
        try {
            $auFinalNums = array_map(static fn($x) => (int) $x['num'], $finalCandidates);

            // 帯内順位（1〜6番人気 / 7〜10番人気 / 11番人気以下）。
            //   統合順位と同じ並び（おすすめ度降順 → 一致馬優先 → 信頼度平均 → 馬番）で数える。
            $auBandSeq  = ['上' => 0, '中' => 0, '下' => 0];
            $auBandRank = [];
            $auRows     = [];
            // 【20261004】PHPが全頭採点から生成した候補も監査に載せる（選出経路を追うため）。
            //   統合点の降順に並べ直してから順位を数える。
            //   @ANCHOR-20261004-PHP-CANDIDATE
            $auAllRows = array_merge($rankedCandidates, $pgGenerated);
            if (!empty($pgGenerated)) {
                usort($auAllRows, $tiebreakMain);
            }
            foreach ($auAllRows as $auIdx => $auH) {
                $auNum  = (int) $auH['num'];
                $auPop  = (int) ($auH['popularity'] ?? 0);
                $auBand = ($auPop >= 1 && $auPop <= 6) ? '上' : (($auPop >= 7 && $auPop <= 10) ? '中' : '下');
                $auBandSeq[$auBand]++;
                $auBandRank[$auNum] = $auBandSeq[$auBand];
                $auSelected = in_array($auNum, $auFinalNums, true);
                $auRows[$auNum] = [
                    '人気'     => $auPop,
                    '統合点'   => $auH['score'] ?? null,
                    '1st点'    => $auH['score_1st'] ?? null,
                    '2nd点'    => $auH['score_2nd'] ?? null,
                    '区分'     => $auH['category'] ?? null,
                    '統合順位' => $auIdx + 1,
                    '帯'       => $auBand,
                    '帯内順位' => $auBandSeq[$auBand],
                    '選出'     => $auSelected,
                    '理由'     => $auReason[$auNum] ?? ($auSelected ? '選出' : '非選出（理由の記録漏れ）'),
                    '購入見送り' => [
                        '最低基準点未満' => !empty($auH['below_min_score']),
                        '購入回避'       => !empty($auH['buy_avoid_longshot']),
                    ],
                    // @ANCHOR-20261014-EVIDENCE-AUDIT  C方式（独立根拠で補充）の算出に使う
                    //   v0.4シャドーが動いていない日のレースは null になります。
                    '独立根拠' => self::$v04LastEvidence[$auNum] ?? null,
                    // @ANCHOR-20261014-FILL-MODE  公開候補と購入推奨を分けて残す
                    '補充枠'   => in_array($auNum, $mcFilled, true),
                    '購入推奨' => $auSelected
                        ? self::fillPurchaseRecommended(
                            $auH + ['fill_slot_unqualified' => in_array($auNum, $mcFilled, true)])
                        : false,
                ];
            }
            // 事前フィルター（最低基準→低配当除外→回収率）で統合前に落ちた馬
            foreach ($auDroppedByFilter as $auDn) {
                $auRows[(int) $auDn] = [
                    '選出' => false,
                    '理由' => '事前フィルターで除外（最低基準・低配当・回収率／上限適用より前）',
                ];
            }

            $this->lastMergeAudit = [
                // ══════════════════════════════════════════════════════════════
                // @ANCHOR-20261014-AUDIT-RACEID  どのレースの記録かを必ず残す
                // ══════════════════════════════════════════════════════════════
                // 10/14のご依頼C「各段階を同じレースIDで出力してください」への対応。
                // 【旧実装の問題】
                //   AUDIT_MERGE にレース表記が入っておらず、監査ログを後から
                //   読んでも「どのレースの統合か」が分からなかった。
                //   他のタグ（AUDIT_RACE / AUDIT_HORSE / AUDIT_AI）には race が
                //   入っているのに、AUDIT_MERGE だけ抜けていた。
                'race'         => self::$v04RaceGuardKey,
                'race_id'      => self::$v04RaceId,
                // ══════════════════════════════════════════════════════════════
                // @ANCHOR-20261014-FILL-MODE  補充方式と、A方式の結果の併記
                // ══════════════════════════════════════════════════════════════
                // 10/14（3回目）ご依頼「A方式の結果も保存し、比較できる状態を
                //   維持する」への対応です。B方式で公開しても、A方式なら
                //   どうだったかを同じレコードから読めるようにします。
                //   A方式相当 … 公開候補から補充枠（資格未達）の馬を除いたもの
                //   B方式相当 … 公開候補に、資格未達で補充しなかった馬を足したもの
                //                （A方式で動かしているときの比較用）
                // @ANCHOR-20261014-EVIDENCE-AUDIT2  依頼書②⑦⑧の証跡
                '送信文ハッシュ'      => self::$v04PromptHash,
                '断層の明細'          => self::$v04GapDetail,
                '段階ごとの頭数'      => self::$v04StageCount,
                '補充方式'            => $fillMode,
                '補充枠の馬番'        => $mcFilled,
                '補充の根拠'          => $mcFillWhy,
                '資格未達で補充しなかった馬番' => $mcSkipWeak,
                'A方式相当の選出'     => array_values(array_diff($auFinalNums, $mcFilled)),
                'B方式相当の選出'     => array_values(array_unique(array_merge(
                    $auFinalNums,
                    array_slice($mcSkipWeak, 0, max(0, $displayLimit - count($auFinalNums)))
                ))),
                '統合式の版'   => self::MERGE_FORMULA_VERSION,
                // ══════════════════════════════════════════════════════════════
                // @ANCHOR-20261006-ANSWER-HASH  どのAI回答で統合したかを残す
                // ══════════════════════════════════════════════════════════════
                // 【20261006 ご指摘⑥】
                //   「BとCが同じAI回答を使った比較になっていることを、
                //     実行日時・版・回答ハッシュ・該当レースの理由で確認してください」
                //   公開部分だけのハッシュ（内部JSONの有無で値が変わらないようにする）と、
                //   全文のハッシュを両方残す。比較ツールはこれを並べて表示する。
                '回答ハッシュ' => [
                    '1st_公開部' => $this->lastAnswerHash['1st_public'] ?? null,
                    '1st_全文'   => $this->lastAnswerHash['1st_raw']    ?? null,
                    '2nd_公開部' => $this->lastAnswerHash['2nd_public'] ?? null,
                    '2nd_全文'   => $this->lastAnswerHash['2nd_raw']    ?? null,
                ],
                // 【20261004 回答④B】検証済みの全頭採点が使えたかどうか。
                //   比較の限界（保存回答に全頭採点が無い場合）を明記するために残す。
                '全頭採点'     => [
                    '1st' => !empty($allScore1st),
                    '2nd' => !empty($allScore2nd),
                    '頭数' => ['1st' => count($allScore1st), '2nd' => count($allScore2nd)],
                ],
                '仕様の版'     => self::ALLOC_SPEC_VERSION,
                '可変配分'     => $allocFeatureOn ? '有効' : '無効（巻き戻し中）',
                '配分モード'   => $allocMode,
                '目標配分'     => ($allocTargetFav === null)
                    ? '既存目安（表6に数値なし）'
                    : "{$allocTargetFav}＋{$allocTargetLong}",
                '実配分'       => [
                    '人気側' => count(array_filter($finalCandidates,
                        static fn($x) => (int) ($x['popularity'] ?? 0) >= 1 && (int) ($x['popularity'] ?? 0) <= 6)),
                    '資格あり穴側' => count(array_filter($finalCandidates,
                        static fn($x) => in_array((int) $x['num'], $allocQualifiedNums, true))),
                ],
                '目標数C'      => $displayLimit,
                // @ANCHOR-20261006-NO-BUYAVOID-IN-SELECTION
                //   購入回避フラグは選出順位に効かせていないことを、提出物で確認できるようにする。
                '購入回避の扱い' => '選出順位には使わない（馬券判定の見送り・監視のみ）',
                '最低基準点で第1パス後回しにした馬番' => array_values(array_unique($slotDeferMin)),
                // @ANCHOR-20261005-NEVER-EMPTY / 20261006 ご指摘④
                //   0頭回避の例外で入れた馬は、通常の資格あり候補と必ず区別する。
                '例外補充（0頭回避）' => $neExceptionNums,
                '資格判定の三値'   => $qualState,
                '最終表示'     => $auFinalNums,
                '資格あり馬番' => $allocQualifiedNums,
                '保護対象馬番' => array_map('intval', $protectedNums),
                '全頭'         => $auRows,
            ];

            \Log::info('[AUDIT_MERGE] 統合単位の監査ログ（@ANCHOR-20261004-AUDIT-MERGE）', $this->lastMergeAudit);
            self::auditFile('AUDIT_MERGE', $this->lastMergeAudit);
        } catch (\Throwable $amE) {
            $this->lastMergeAudit = ['error' => $amE->getMessage()];
            \Log::warning('[AUDIT_MERGE] 統合単位の監査ログの作成に失敗（処理は継続）', [
                'message' => $amE->getMessage(),
            ]);
        }

        // ══════════════════════════════════════════════════════════════════
        // @ANCHOR-20261014-FILL-MODE  公開候補と購入推奨を別の値にして両方残す
        // ══════════════════════════════════════════════════════════════════
        // 10月14日（3回目）ご依頼③「補充馬を自動的に購入推奨しない。
        //   公開候補と購入判断を分離する」への対応です。
        // 画面に出すかどうか（公開候補）と、買う価値があるかどうか（購入推奨）を
        // 別の値にして、どちらも merged_horses と監査ログに残します。
        // 既存の購入回避条件（低配当・回収率40%未満・最低基準点・大穴条件）は
        // 判定内容も閾値も変えていません。ここで使っているだけです。
        foreach ($finalCandidates as &$fcH) {
            $fcH['fill_slot']             = !empty($fcH['fill_slot']);
            $fcH['fill_slot_unqualified'] = !empty($fcH['fill_slot_unqualified']);
            $fcH['purchase_recommended']  = self::fillPurchaseRecommended($fcH);
        }
        unset($fcH);

        return $finalCandidates;
    }



